QT_ISI(14,{"1803":["(Alif laam raa) hanya Allahlah yang mengetahui maksudnya. (Ini) ayat-ayat ini (adalah sebagian dari ayat-ayat kitab) Alquran; idhafat di sini mengandung makna min yang berarti sebagian (yaitu Alquran yang memberi penjelasan) yang memenangkan perkara yang hak atas perkara yang batil. Lafal ayat ini diathafkan kepada lafal sebelumnya dengan ditambah sifat.",[["الٓر ۚ","Alif Laam Ra"],["تِلْكَ","Ini"],["ءَايَـٰتُ","(adalah) ayat-ayat"],["ٱلْكِتَـٰبِ","Kitab"],["وَقُرْءَانٍۢ","dan Al-Quran"],["مُّبِينٍۢ","yang nyata"]]],"1804":["(Sering kali) dapat dibaca rubbamaa dan rubamaa (berkeinginan) mengharapkan (orang-orang yang kafir itu) kelak di hari kiamat, yaitu sewaktu diperlihatkan kepada mereka keadaan diri mereka dan keadaan kaum Muslimin (seandainya mereka menjadi orang-orang muslim) lafal rubba menunjukkan makna littaktsir/sering, karena sesungguhnya mereka sering kali mengharapkan hal tersebut. Akan tetapi menurut pendapat lain menunjukkan makna littaqlil, artinya sedikit, karena sesungguhnya kengerian-kengerian pemandangan di hari kiamat membuat mereka terkejut dengan sangat, sehingga mereka tidak sadar untuk berharap seperti itu melainkan hanya dalam masa yang sedikit.",[["رُّبَمَا","barangkali"],["يَوَدُّ","akan berhajat"],["ٱلَّذِينَ","orang yang"],["كَفَرُوا۟","kufur"],["لَوْ","jika"],["كَانُوا۟","mereka telah"],["مُسْلِمِينَ","orang Islam"]]],"1805":["(Biarkanlah mereka) biarkanlah orang-orang kafir itu, hai Muhammad (makan dan bersenang-senang) di dunia mereka ini (dan dilalaikan) disibukkan (oleh angan-angan kosong) dengan dipanjangkan umur mereka dan lain-lainnya sehingga mereka lupa daratan akan iman (maka kelak mereka akan mengetahui) akibat daripada perbuatan mereka. Ayat ini diturunkan sebelum ada perintah untuk memerangi mereka.",[["ذَرْهُمْ","Tinggalkan mereka"],["يَأْكُلُوا۟","(untuk) makan"],["وَيَتَمَتَّعُوا۟","dan nikmati"],["وَيُلْهِهِمُ","dan mengalihkan mereka"],["ٱلْأَمَلُ ۖ","harapan itu"],["فَسَوْفَ","kemudian tidak lama lagi"],["يَعْلَمُونَ","mereka akan tahu"]]],"1806":["(Dan Kami tiada membinasakan) huruf min adalah zaidah (sesuatu negeri pun) yang dimaksud adalah para penduduknya (melainkan ada baginya ketentuan) masa (yang telah ditetapkan) yang terbatas untuk pembinasaan mereka.",[["وَمَآ","Dan tidak"],["أَهْلَكْنَا","Kami musnahkan"],["مِن","sebarang"],["قَرْيَةٍ","bandar"],["إِلَّا","tetapi"],["وَلَهَا","(ada) untuknya"],["كِتَابٌۭ","sebuah dekri"],["مَّعْلُومٌۭ","diketahui"]]],"1807":["(Tiada yang dapat mendahului) huruf min adalah zaidah (suatu umat pun akan ajalnya, dan tiada pula yang dapat mengundurkannya) menangguhkan saat ajalnya dari waktu yang telah ditentukan oleh Allah.",[["مَّا","Tidak"],["تَسْبِقُ","(boleh) maju"],["مِنْ","sebarang"],["أُمَّةٍ","bangsa"],["أَجَلَهَا","istilahnya"],["وَمَا","dan bukan"],["يَسْتَـْٔخِرُونَ","(boleh) melengahkannya"]]],"1808":["(Dan mereka berkata) yaitu orang-orang kafir Mekah kepada Nabi saw. (\"Hai orang yang diturunkan Adz-Dzikru kepadanya!) yakni Alquran, menurut perkiraan (Sesungguhnya kamu benar-benar orang yang gila.\")",[["وَقَالُوا۟","Dan mereka berkata"],["يَـٰٓأَيُّهَا","Wahai"],["ٱلَّذِى","(kepada) siapa"],["نُزِّلَ","telah diturunkan"],["عَلَيْهِ","[pada dia]"],["ٱلذِّكْرُ","Peringatan itu"],["إِنَّكَ","sesungguhnya, kamu"],["لَمَجْنُونٌۭ","(adalah) pasti marah"]]],"1809":["(\"Mengapa tidak) (kamu datangkan malaikat kepada kami, jika kamu termasuk orang-orang yang benar?\") di dalam ucapanmu itu yang mengatakan, bahwa kamu adalah seorang nabi, dan Alquran ini dari sisi Allah?",[["لَّوْ","kenapa"],["مَا","tidak"],["تَأْتِينَا","kamu bawa kepada kami"],["بِٱلْمَلَـٰٓئِكَةِ","para Malaikat"],["إِن","jika"],["كُنتَ","kamu"],["مِنَ","daripada"],["ٱلصَّـٰدِقِينَ","yang benar"]]],"1810":["Allah berfirman (Kami tidak menurunkan) dan menurut suatu qiraat dibaca tanazzalu dengan membuang salah satu huruf ta-nya (malaikat melainkan dengan benar) untuk membawa azab (dan tiadalah mereka ketika itu) sewaktu malaikat turun dengan membawa azab (diberi tangguh) ditangguhkan azabnya.",[["مَا","Tidak"],["نُنَزِّلُ","Kami hantar turun"],["ٱلْمَلَـٰٓئِكَةَ","para Malaikat"],["إِلَّا","kecuali"],["بِٱلْحَقِّ","dengan kebenaran"],["وَمَا","dan bukan"],["كَانُوٓا۟","mereka akan menjadi"],["إِذًۭا","kemudian"],["مُّنظَرِينَ","diberi tangguh"]]],"1811":["(Sesungguhnya Kamilah) lafal nahnu mentaukidkan atau mengukuhkan makna yang terdapat di dalam isimnya inna, atau sebagai fashl (yang menurunkan Adz-Dzikr) Alquran (dan sesungguhnya Kami benar-benar memeliharanya) dari penggantian, perubahan, penambahan dan pengurangan.",[["إِنَّا","Sesungguhnya Kami"],["نَحْنُ","Kami"],["نَزَّلْنَا","telah menurunkan"],["ٱلذِّكْرَ","Peringatan itu"],["وَإِنَّا","dan sesungguhnya Kami"],["لَهُۥ","daripadanya"],["لَحَـٰفِظُونَ","(adalah) sesungguhnya penjaga-penjaga"]]],"1812":["(Dan sesungguhnya Kami telah mengutus sebelum kamu) beberapa rasul (kepada umat-umat) golongan-golongan (terdahulu.)",[["وَلَقَدْ","Dan sungguh"],["أَرْسَلْنَا","Kami (telah) menghantar"],["مِن","sebelum kamu"],["قَبْلِكَ","sebelum kamu"],["فِى","dalam"],["شِيَعِ","mazhab-mazhab"],["ٱلْأَوَّلِينَ","(dari) orang-orang dahulu"]]],"1813":["(Dan tidak) sekali-kali (datang seorang rasul pun kepada mereka melainkan mereka selalu memperolok-olokkannya) sebagaimana kaummu memperolok-olokkanmu. Ayat ini dimaksudkan untuk menghibur hati Nabi saw.",[["وَمَا","Dan tidak"],["يَأْتِيهِم","datang kepada mereka"],["مِّن","sebarang"],["رَّسُولٍ","Utusan"],["إِلَّا","tetapi"],["كَانُوا۟","mereka lakukan"],["بِهِۦ","pada dia"],["يَسْتَهْزِءُونَ","mengejek"]]],"1814":["(Demikianlah Kami memasukkannya) artinya seperti itulah gambarannya bila Kami memasukkan ke dalam hati orang-orang kafir rasa ingkar dan memperolok-olokkan (ke dalam hati orang-orang yang berdosa) yaitu orang-orang kafir Mekah.",[["كَذَٰلِكَ","Demikianlah"],["نَسْلُكُهُۥ","Kami biarkan ia masuk"],["فِى","dalam"],["قُلُوبِ","(the) hati"],["ٱلْمُجْرِمِينَ","(dari) penjenayah"]]],"1815":["(Mereka tidak beriman kepadanya) kepada Nabi saw. (dan sesungguhnya telah berlalu sunatullah terhadap orang-orang yang dahulu) artinya kebiasaan yang dilakukan oleh Allah swt. terhadap orang-orang yang tidak beriman, yaitu mengazab mereka disebabkan perbuatan dusta mereka terhadap nabi-nabi mereka. Orang-orang kafir Mekah pun akan mengalami hal yang serupa.",[["لَا","Tidak"],["يُؤْمِنُونَ","mereka beriman"],["بِهِۦ ۖ","di dalamnya"],["وَقَدْ","dan sesungguhnya"],["خَلَتْ","telah berlalu"],["سُنَّةُ","cara"],["ٱلْأَوَّلِينَ","(dari) orang-orang dahulu"]]],"1816":["(Dan seandainya Kami membukakan kepada mereka salah satu dari pintu-pintu langit, lalu mereka terus-menerus padanya) pada pintu tersebut (dalam keadaan naik) selalu naik.",[["وَلَوْ","Dan (walaupun) jika"],["فَتَحْنَا","Kami buka"],["عَلَيْهِم","kepada mereka"],["بَابًۭا","sebuah pintu pagar"],["مِّنَ","daripada"],["ٱلسَّمَآءِ","syurga itu"],["فَظَلُّوا۟","dan mereka harus meneruskan"],["فِيهِ","di dalamnya"],["يَعْرُجُونَ","(untuk) naik"]]],"1817":["(Tentulah mereka berkata, \"Sesungguhnya benar-benar telah dikaburkan) telah ditutup (pandangan kami bahkan kami adalah orang-orang yang kena sihir.\") seolah-olah tampak hal itu di mata kami secara ilusi.",[["لَقَالُوٓا۟","Mereka pasti akan berkata"],["إِنَّمَا","Hanya"],["سُكِّرَتْ","telah terpesona"],["أَبْصَـٰرُنَا","mata kita"],["بَلْ","Bahkan"],["نَحْنُ","kita"],["قَوْمٌۭ","(adalah) suatu kaum"],["مَّسْحُورُونَ","disihir"]]],"1818":["(Dan sesungguhnya Kami menciptakan gugusan bintang-bintang di langit) yang berjumlah dua belas, yaitu: Aries, Taurus, Gemini, Cancer, Leo, Virgo, Libra, Scorpio, Sagitarius, Capricorn, Aquarius dan Pisces. Bintang-bintang tersebut merupakan garis-garis peredaran daripada tujuh bintang yang beredar, yaitu Mars mempunyai garis edar pada bintang Aries dan bintang Scorpio; Venus mempunyai garis edar pada bintang Taurus dan bintang Libra; Utarid mempunyai garis edar pada bintang Gemini dan bintang Virgo; bulan mempunyai garis edar pada bintang Cancer; matahari mempunyai garis edar pada bintang Leo; Jupiter mempunyai garis edar pada bintang Sagitarius dan Pisces; Saturnus mempunyai garis edar pada bintang Capricorn dan Aquarius (dan Kami telah menghiasi langit itu) dengan bintang-bintang yang gemerlapan (bagi orang-orang yang memandang.)",[["وَلَقَدْ","Dan sesungguhnya"],["جَعَلْنَا","Kami telah meletakkan"],["فِى","dalam"],["ٱلسَّمَآءِ","langit"],["بُرُوجًۭا","buruj"],["وَزَيَّنَّـٰهَا","dan Kami telah menghiasinya"],["لِلنَّـٰظِرِينَ","untuk pemerhati"]]],"1819":["(Dan Kami menjaganya) dengan meteor-meteor (dari tiap-tiap setan yang terkutuk) yang terlaknat.",[["وَحَفِظْنَـٰهَا","Dan Kami telah memeliharanya"],["مِن","daripada"],["كُلِّ","setiap"],["شَيْطَـٰنٍۢ","syaitan"],["رَّجِيمٍ","terkutuk"]]],"1820":["(Akan tetapi) tetapi (setan yang mencuri-curi berita yang dapat didengar) yang menyadapnya (maka ia pasti dikejar oleh semburan api yang terang) yakni bintang yang menyala terang dan dapat membakar atau menembus atau membuatnya cacat.",[["إِلَّا","Kecuali"],["مَنِ","(satu) siapa"],["ٱسْتَرَقَ","mencuri"],["ٱلسَّمْعَ","pendengaran"],["فَأَتْبَعَهُۥ","kemudian mengikutinya"],["شِهَابٌۭ","api yang menyala"],["مُّبِينٌۭ","yang nyata"]]],"1821":["(Dan Kami telah menghamparkan bumi) telah membuatnya terbentang (dan Kami menjadikan padanya gunung-gunung) yang kokoh dan tegak supaya jangan bergerak-gerak mengguncangkan penduduknya (dan Kami tumbuhkan padanya segala sesuatu menurut ukuran) yang telah ditentukan secara pasti.",[["وَٱلْأَرْضَ","Dan bumi"],["مَدَدْنَـٰهَا","Kami telah menyebarkannya"],["وَأَلْقَيْنَا","dan [Kami] melemparkan"],["فِيهَا","di dalamnya"],["رَوَٰسِىَ","gunung yang kukuh"],["وَأَنۢبَتْنَا","dan [Kami] menyebabkan berkembang"],["فِيهَا","di dalamnya"],["مِن","daripada"],["كُلِّ","setiap"],["شَىْءٍۢ","perkara"],["مَّوْزُونٍۢ","seimbang"]]],"1822":["(Dan Kami telah menjadikan untuk kalian di muka bumi keperluan-keperluan hidup) berupa buah-buahan dan biji-bijian (dan) Kami jadikan pula untuk kalian (makhluk-makhluk yang kalian sekali-kali bukan pemberi rezeki kepadanya) yaitu berupa hamba-hamba sahaya, binatang-binatang dan berbagai macam jenis ternak; hanya Allahlah yang memberi rezeki kepada mereka.",[["وَجَعَلْنَا","Dan Kami telah menjadikan"],["لَكُمْ","bagi kamu"],["فِيهَا","di dalamnya"],["مَعَـٰيِشَ","cara hidup"],["وَمَن","dan siapa"],["لَّسْتُمْ","kamu tidak"],["لَهُۥ","baginya"],["بِرَٰزِقِينَ","pembekal"]]],"1823":["(Dan tiada) tidak ada (sesuatu pun melainkan pada sisi Kamilah khazanahnya) huruf min adalah zaidah; yang dimaksud adalah kunci-kunci perbendaharaan segala sesuatu itu (dan Kami tidak menurunkannya melainkan dengan ukuran-ukuran yang tertentu) sesuai dengan kepentingan-kepentingannya.",[["وَإِن","Dan tidak"],["مِّن","(adalah) mana-mana"],["شَىْءٍ","perkara"],["إِلَّا","tetapi"],["عِندَنَا","dengan Kami"],["خَزَآئِنُهُۥ","(adalah) khazanahnya"],["وَمَا","dan bukan"],["نُنَزِّلُهُۥٓ","Kami hantar ke bawah"],["إِلَّا","kecuali"],["بِقَدَرٍۢ","dalam ukuran"],["مَّعْلُومٍۢ","diketahui"]]],"1824":["(Dan Kami telah meniupkan angin untuk mengumpulkan awan) menggiring mendung sehingga terkumpul lalu penuh dengan air (lalu Kami turunkan dari langit) dari mendung itu (air) air hujan (kemudian Kami beri minum kamu dengan air itu, dan sekali-kali bukanlah kalian yang menyimpannya) artinya, bukanlah kalian yang menyimpannya dengan upaya tangan kalian.",[["وَأَرْسَلْنَا","Dan Kami telah mengutus"],["ٱلرِّيَـٰحَ","angin"],["لَوَٰقِحَ","membaja"],["فَأَنزَلْنَا","dan Kami turunkan"],["مِنَ","daripada"],["ٱلسَّمَآءِ","langit"],["مَآءًۭ","air"],["فَأَسْقَيْنَـٰكُمُوهُ","dan Kami berikan kepadamu minuman itu"],["وَمَآ","Dan tidak"],["أَنتُمْ","kamu"],["لَهُۥ","daripadanya"],["بِخَـٰزِنِينَ","(adalah) penahan"]]],"1825":["(Dan sesungguhnya benar-benar Kamilah yang menghidupkan dan mematikan dan Kami pula yang mewarisi) yang tetap hidup dan mewarisi semua makhluk.",[["وَإِنَّا","Dan sesungguhnya, Kami"],["لَنَحْنُ","pasti [Kami]"],["نُحْىِۦ","Kami memberi kehidupan"],["وَنُمِيتُ","dan Kami menyebabkan kematian"],["وَنَحْنُ","dan Kami"],["ٱلْوَٰرِثُونَ","(adalah) orang-orang yang mewarisi"]]],"1826":["(Dan sesungguhnya Kami telah mengetahui orang-orang yang terdahulu daripada kalian) yaitu makhluk-makhluk yang terdahulu sejak Nabi Adam (dan sesungguhnya Kami mengetahui pula orang-orang yang terkemudian) orang-orang yang akan datang kemudian hingga hari kiamat.",[["وَلَقَدْ","Dan sesungguhnya"],["عَلِمْنَا","Kami tahu"],["ٱلْمُسْتَقْدِمِينَ","yang terdahulu"],["مِنكُمْ","antara kamu"],["وَلَقَدْ","dan sesungguhnya"],["عَلِمْنَا","Kami tahu"],["ٱلْمُسْتَـْٔخِرِينَ","yang terkemudian"]]],"1827":["(Sesungguhnya Rabbmu, Dialah yang akan menghimpunkan mereka. Sesungguhnya Dia adalah Maha Bijaksana) di dalam pekerjaan-Nya (lagi Maha Mengetahui.) tentang makhluk-Nya.",[["وَإِنَّ","Dan sesungguhnya"],["رَبَّكَ","Tuhanmu"],["هُوَ","Dia"],["يَحْشُرُهُمْ ۚ","akan mengumpulkan mereka"],["إِنَّهُۥ","Sesungguhnya Dia"],["حَكِيمٌ","(adalah) Maha Bijaksana"],["عَلِيمٌۭ","Maha Mengetahui"]]],"1828":["(Dan sesungguhnya Kami telah menciptakan manusia) yaitu Nabi Adam (dari tanah liat kering) tanah liat kering yang apabila diketuk akan terdengar daripadanya suara melenting (yang berasal dari lumpur hitam) tanah liat yang hitam (yang diberi bentuk) diubah bentuknya.",[["وَلَقَدْ","Dan sesungguhnya"],["خَلَقْنَا","Kami mencipta"],["ٱلْإِنسَـٰنَ","manusia"],["مِن","(keluar) daripada"],["صَلْصَـٰلٍۢ","tanah liat yang berbunyi"],["مِّنْ","daripada"],["حَمَإٍۢ","lumpur hitam"],["مَّسْنُونٍۢ","diubah"]]],"1829":["(Dan jin) maksudnya biangnya jin, yaitu iblis (Kami telah menciptakan sebelumnya) sebelum Nabi Adam diciptakan (dari api yang sangat panas) yaitu api yang sama sekali tidak berasap dan dapat menembus pori-pori.",[["وَٱلْجَآنَّ","Dan jin"],["خَلَقْنَـٰهُ","Kami menciptanya"],["مِن","sebelum"],["قَبْلُ","sebelum"],["مِن","daripada"],["نَّارِ","kebakaran"],["ٱلسَّمُومِ","terik"]]],"1830":["(Dan) ingatlah (ketika Rabbmu berfirman kepada para malaikat, \"Sesungguhnya Aku akan menciptakan seorang manusia dari tanah liat kering yang berasal dan lumpur hitam yang diberi bentuk).",[["وَإِذْ","Dan apabila"],["قَالَ","Tuhanmu berfirman"],["رَبُّكَ","Tuhanmu berfirman"],["لِلْمَلَـٰٓئِكَةِ","kepada para Malaikat"],["إِنِّى","Sesungguhnya aku"],["خَـٰلِقٌۢ","(akan) mencipta"],["بَشَرًۭا","seorang manusia"],["مِّن","(keluar) daripada"],["صَلْصَـٰلٍۢ","tanah liat"],["مِّنْ","daripada"],["حَمَإٍۢ","lumpur hitam"],["مَّسْنُونٍۢ","diubah"]]],"1831":["(Maka apabila Aku telah menyempurnakan kejadiannya) telah merampungkan bentuknya (dan Aku telah meniupkan) maksudnya telah mengalirkan (ke dalam tubuhnya roh ciptaan-Ku) sehingga ia menjadi hidup; diidhafatkannya lafal ruuh kepada-Nya sebagai penghormatan kepada Adam (maka tunduklah kalian kepadanya dengan bersujud) yaitu sujud penghormatan dengan cara membungkuk.",[["فَإِذَا","Jadi, apabila"],["سَوَّيْتُهُۥ","Aku telah membentuk dia"],["وَنَفَخْتُ","dan [aku] bernafas"],["فِيهِ","ke dalam dia"],["مِن","daripada"],["رُّوحِى","semangat aku"],["فَقَعُوا۟","kemudian jatuh ke bawah"],["لَهُۥ","kepadanya"],["سَـٰجِدِينَ","sujud"]]],"1832":["(Maka bersujudlah para malaikat itu semuanya bersama-sama) di dalam ayat ini terdapat dua taukid, yaitu lafal kulluhum dan lafal ajma'uuna.",[["فَسَجَدَ","Jadi sujud"],["ٱلْمَلَـٰٓئِكَةُ","para Malaikat"],["كُلُّهُمْ","kesemuanya"],["أَجْمَعُونَ","bersama-sama"]]],"1833":["(Kecuali iblis) dia adalah biangnya jin yang dahulu hidup di antara para malaikat (ia enggan) menolak untuk (ikut bersama-sama malaikat yang sujud itu.\")",[["إِلَّآ","Kecuali"],["إِبْلِيسَ","Iblis"],["أَبَىٰٓ","Dia menolak"],["أَن","kepada"],["يَكُونَ","jadilah"],["مَعَ","dengan"],["ٱلسَّـٰجِدِينَ","mereka yang sujud"]]],"1834":["(Allah berfirman) Maha Tinggi Allah (\"Hai iblis! Apa sebabnya kamu) apa yang menyebabkan kamu enggan (tidak mau) huruf laa adalah zaidah (ikut sujud bersama-sama mereka yang sujud itu?\")",[["قَالَ","Dia berkata"],["يَـٰٓإِبْلِيسُ","Wahai Iblis"],["مَا","Apa"],["لَكَ","(adalah) untuk kamu"],["أَلَّا","itu tidak"],["تَكُونَ","kamu"],["مَعَ","dengan"],["ٱلسَّـٰجِدِينَ","mereka yang sujud"]]],"1835":["(Berkata iblis, \"Aku sekali-kali tidak akan sujud) tidak layak bagiku untuk sujud (kepada manusia yang Engkau telah menciptakannya dari tanah liat kering yang berasal dari lumpur hitam yang diberi bentuk.\")",[["قَالَ","Dia berkata"],["لَمْ","aku tidak"],["أَكُن","aku tidak"],["لِّأَسْجُدَ","(satu) untuk sujud"],["لِبَشَرٍ","kepada seorang manusia"],["خَلَقْتَهُۥ","yang Engkau ciptakan"],["مِن","(keluar) daripada"],["صَلْصَـٰلٍۢ","tanah liat"],["مِّنْ","daripada"],["حَمَإٍۢ","lumpur hitam"],["مَّسْنُونٍۢ","diubah"]]],"1836":["(Allah berfirman, \"Keluarlah dari surga) menurut suatu pendapat dari langit (karena sesungguhnya kamu terkutuk.\") terusir.",[["قَالَ","Dia berkata"],["فَٱخْرُجْ","Lepas tu keluar"],["مِنْهَا","daripadanya"],["فَإِنَّكَ","kerana sesungguhnya, kamu"],["رَجِيمٌۭ","(ada) diusir"]]],"1837":["(Dan sesungguhnya kutukan itu tetap menimpamu sampai hari kiamat) sampai hari pembalasan",[["وَإِنَّ","Dan sesungguhnya"],["عَلَيْكَ","ke atas kamu"],["ٱللَّعْنَةَ","(akan menjadi) laknat"],["إِلَىٰ","sehingga"],["يَوْمِ","(the) Hari"],["ٱلدِّينِ","(dari) Penghakiman"]]],"1838":["(Berkata iblis, \"Ya Rabbku! Kalau begitu maka beri tangguhlah kepadaku sampai hari dibangkitkan.\") nya manusia",[["قَالَ","Dia berkata"],["رَبِّ","Wahai Tuhanku"],["فَأَنظِرْنِىٓ","Kemudian beri aku tangguh"],["إِلَىٰ","sehingga"],["يَوْمِ","(the) Hari"],["يُبْعَثُونَ","mereka dibesarkan"]]],"1839":["(Allah berfirman, \"Kalau begitu, maka sesungguhnya kamu termasuk orang-orang yang diberi tangguh).",[["قَالَ","Dia berkata"],["فَإِنَّكَ","Maka sesungguhnya kamu"],["مِنَ","(adalah) daripada"],["ٱلْمُنظَرِينَ","yang diberi tangguh"]]],"1840":["(sampai hari suatu waktu yang telah ditentukan.\") yaitu sampai tiupan sangkakala yang pertama.",[["إِلَىٰ","Sehingga"],["يَوْمِ","Hari itu"],["ٱلْوَقْتِ","(dari) masa"],["ٱلْمَعْلُومِ","terkenal"]]],"1841":["(Iblis berkata, \"Ya Rabbku! Oleh sebab Engkau telah memutuskan bahwa aku sesat) artinya disebabkan Engkau telah menetapkan aku sesat; huruf ba pada lafal bimaa adalah bermakna qasam, sedangkan jawabnya ialah (pasti aku akan menjadikan mereka memandang baik di muka bumi ini) terhadap perbuatan-perbuatan maksiat (dan pasti aku akan menyesatkan mereka semuanya).",[["قَالَ","Dia berkata"],["رَبِّ","Tuhanku"],["بِمَآ","Kerana"],["أَغْوَيْتَنِى","Kamu mengelirukan aku"],["لَأُزَيِّنَنَّ","nescaya Aku akan menjadikan (kejahatan) kelihatan baik"],["لَهُمْ","kepada mereka"],["فِى","dalam"],["ٱلْأَرْضِ","bumi"],["وَلَأُغْوِيَنَّهُمْ","dan Aku akan menyesatkan mereka"],["أَجْمَعِينَ","semua"]]],"1842":["(Kecuali hamba-hamba Engkau yang mukhlis di antara mereka\") yakni orang-orang yang beriman.",[["إِلَّا","Kecuali"],["عِبَادَكَ","hambamu"],["مِنْهُمُ","antara mereka"],["ٱلْمُخْلَصِينَ","mereka yang ikhlas"]]],"1843":["(Berfirmanlah Allah) swt. (\"Inilah jalan yang lurus; kewajiban Akulah memeliharanya\")",[["قَالَ","Dia berkata"],["هَـٰذَا","Ini"],["صِرَٰطٌ","(adalah) jalannya"],["عَلَىَّ","kepada-Ku"],["مُسْتَقِيمٌ","lurus"]]],"1844":["(Sesungguhnya hamba-hamba-Ku) yang beriman (tidak ada kekuasaan bagimu terhadap mereka) kamu tidak mempunyai kekuatan (kecuali) hanyalah (orang-orang yang mengikut kalian; yaitu orang-orang yang sesat) yakni orang-orang kafir.",[["إِنَّ","Sesungguhnya"],["عِبَادِى","budak-budak aku"],["لَيْسَ","tidak"],["لَكَ","kamu ada"],["عَلَيْهِمْ","atas mereka"],["سُلْطَـٰنٌ","mana-mana pihak berkuasa"],["إِلَّا","kecuali"],["مَنِ","orang yang"],["ٱتَّبَعَكَ","ikut kamu"],["مِنَ","daripada"],["ٱلْغَاوِينَ","mereka yang sesat"]]],"1845":["(Dan sesungguhnya Jahanam itu benar-benar tempat yang telah dijanjikan kepada mereka semuanya) yaitu kepada orang-orang yang mengikutimu.",[["وَإِنَّ","Dan sesungguhnya"],["جَهَنَّمَ","Neraka"],["لَمَوْعِدُهُمْ","(ialah) sesungguhnya tempat yang dijanjikan untuk mereka"],["أَجْمَعِينَ","semua"]]],"1846":["(Jahanam itu mempunyai tujuh pintu) tujuh lapis (Tiap-tiap pintu) daripadanya (adalah untuk segolongan di antara mereka bagian) yakni jatah (yang tertentu).",[["لَهَا","Untuk itu"],["سَبْعَةُ","(adalah) tujuh"],["أَبْوَٰبٍۢ","pintu pagar"],["لِّكُلِّ","untuk setiap"],["بَابٍۢ","pintu pagar"],["مِّنْهُمْ","antara mereka"],["جُزْءٌۭ","(adalah) sebahagian"],["مَّقْسُومٌ","ditugaskan"]]],"1847":["(Sesungguhnya orang-orang yang bertakwa itu berada di dalam surga) kebun-kebun surga (dan mata air-mata air) yang mengalir di dalamnya.",[["إِنَّ","Sesungguhnya"],["ٱلْمُتَّقِينَ","orang yang soleh"],["فِى","(akan) masuk"],["جَنَّـٰتٍۢ","Taman-taman"],["وَعُيُونٍ","dan mata air"]]],"1848":["Dan dikatakan kepada mereka (\"Masuklah ke dalamnya dengan sejahtera) dengan perasaan yang aman dari setiap hal yang menakutkan. Atau masuklah ke dalamnya dengan bersalam artinya, bersalamlah lalu masuklah (lagi aman\") dari setiap hal-hal yang mengerikan.",[["ٱدْخُلُوهَا","Masukkan ia"],["بِسَلَـٰمٍ","dalam keadaan aman"],["ءَامِنِينَ","selamat"]]],"1849":["(Dan Kami lenyapkan segala rasa dendam yang berada dalam hati mereka) maksudnya semua perasaan dengki (sedangkan mereka merasa bersaudara) lafal ikhwaanan ini menjadi hal tentang keadaan mereka (duduk berhadap-hadapan di atas dipan-dipan) kalimat ayat ini pun menggambarkan tentang keadaan mereka; artinya sebagian dari mereka tidak melihat kepada tengkuk sebagian yang lain karena tempat duduk mereka saling berhadap-hadapan.",[["وَنَزَعْنَا","Dan Kami (akan) hapuskan"],["مَا","apa"],["فِى","(berada) dalam"],["صُدُورِهِم","buah dada mereka"],["مِّنْ","daripada"],["غِلٍّ","dendam"],["إِخْوَٰنًا","(mereka akan menjadi) bersaudara"],["عَلَىٰ","pada"],["سُرُرٍۢ","takhta"],["مُّتَقَـٰبِلِينَ","berdepan antara satu sama lain"]]],"1850":["(Mereka tidak merasa lelah di dalamnya) tidak pernah merasa penat (dan mereka sekali-kali tidak akan dikeluarkan daripadanya) untuk selama-lamanya.",[["لَا","Tidak"],["يَمَسُّهُمْ","akan menyentuh mereka"],["فِيهَا","di dalamnya"],["نَصَبٌۭ","keletihan"],["وَمَا","dan bukan"],["هُم","mereka"],["مِّنْهَا","daripadanya"],["بِمُخْرَجِينَ","akan dikeluarkan"]]],"1851":["(Kabarkanlah) beritakanlah, hai Muhammad (kepada hamba-hamba-Ku bahwa sesungguhnya Akulah Yang Maha Pengampun) terhadap orang-orang mukmin (lagi Maha Penyayang) terhadap mereka yang beriman.",[["۞ نَبِّئْ","Maklumkan"],["عِبَادِىٓ","budak-budak aku"],["أَنِّىٓ","bahawa aku"],["أَنَا","aku"],["ٱلْغَفُورُ","Yang Maha Pengampun"],["ٱلرَّحِيمُ","Yang Maha Mengasihani"]]],"1852":["(Dan bahwa sesungguhnya azab-Ku) terhadap orang-orang yang durhaka (adalah azab yang sangat pedih) sangat menyakitkan.",[["وَأَنَّ","Dan bahawa"],["عَذَابِى","hukuman aku"],["هُوَ","ia"],["ٱلْعَذَابُ","(adalah) hukuman"],["ٱلْأَلِيمُ","yang paling menyakitkan"]]],"1853":["(Dan kabarkanlah kepada mereka tentang tamu-tamu Ibrahim) yaitu malaikat-malaikat yang berjumlah dua belas malaikat, atau sepuluh malaikat, atau tiga malaikat yang salah satu di antara mereka adalah malaikat Jibril.",[["وَنَبِّئْهُمْ","Dan maklumkan kepada mereka"],["عَن","tentang"],["ضَيْفِ","(para) tetamu"],["إِبْرَٰهِيمَ","(dari) Ibrahim"]]],"1854":["(Ketika mereka masuk ke tempatnya, lalu mereka mengucapkan, \"Salam.\") mereka mengucapkan lafal itu. (Berkata Ibrahim) ketika disuguhkan hidangan makanan kepada mereka, akan tetapi mereka tidak memakannya (\"Sesungguhnya kami merasa takut kepada kalian.\") yakni merasa ngeri.",[["إِذْ","Apabila"],["دَخَلُوا۟","mereka masuk"],["عَلَيْهِ","atasnya"],["فَقَالُوا۟","dan berkata"],["سَلَـٰمًۭا","Damai"],["قَالَ","Dia berkata"],["إِنَّا","Sesungguhnya kami"],["مِنكُمْ","(adalah) daripada kamu"],["وَجِلُونَ","takut"]]],"1855":["(Mereka berkata, \"Janganlah kamu merasa takut) merasa ngeri terhadap kami (sesungguhnya kami) adalah utusan-utusan Rabbmu (memberi kabar gembira kepadamu dengan kelahiran seorang anak laki-laki yang akan menjadi orang yang alim.\") anak yang mempunyai ilmu yang banyak, yaitu Nabi Ishak, seperti yang telah kami sebutkan dalam surah Hud.",[["قَالُوا۟","Mereka berkata"],["لَا","Jangan"],["تَوْجَلْ","takutlah"],["إِنَّا","sesungguhnya, kita"],["نُبَشِّرُكَ","[kami] membawa berita gembira kepada kamu"],["بِغُلَـٰمٍ","seorang budak lelaki"],["عَلِيمٍۢ","dipelajari"]]],"1856":["(Berkata Ibrahim, \"Apakah kalian memberi kabar gembira kepadaku) dengan melahirkan seorang anak (padahal usiaku telah lanjut) kalimat ini menjadi hal; artinya padahal usia tua telah kualami (maka dengan cara manakah) dengan cara apakah (terlaksananya berita gembira seperti apa yang kalian katakan itu?\") Istifham di sini mengandung makna takjub.",[["قَالَ","Dia berkata"],["أَبَشَّرْتُمُونِى","Adakah kamu memberi aku berita gembira"],["عَلَىٰٓ","Adakah kamu memberi aku berita gembira"],["أَن","walaupun"],["مَّسَّنِىَ","telah mengatasi aku"],["ٱلْكِبَرُ","usia tua"],["فَبِمَ","Kemudian tentang apa"],["تُبَشِّرُونَ","kamu memberi khabar gembira"]]],"1857":["(Mereka berkata, \"Kami menyampaikan kabar gembira kepadamu dengan benar) dengan sungguh-sungguh (maka janganlah kamu termasuk orang-orang yang berputus asa.\") putus harapan.",[["قَالُوا۟","Mereka berkata"],["بَشَّرْنَـٰكَ","Kami memberi khabar gembira kepada kamu"],["بِٱلْحَقِّ","dalam kebenaran"],["فَلَا","jadi (jangan)"],["تَكُن","jadilah"],["مِّنَ","daripada"],["ٱلْقَـٰنِطِينَ","yang putus asa"]]],"1858":["(Ibrahim berkata, \"Tiada) tidak ada (orang orang berputus asa) dapat dibaca yaqnithu dan yaqnathu (dari rahmat Rabbnya melainkan orang-orang yang sesat.\") yakni orang-orang kafir.",[["قَالَ","Dia berkata"],["وَمَن","Dan siapa"],["يَقْنَطُ","putus asa"],["مِن","daripada"],["رَّحْمَةِ","(the) Rahmat"],["رَبِّهِۦٓ","(dari) Tuhannya"],["إِلَّا","kecuali"],["ٱلضَّآلُّونَ","mereka yang sesat"]]],"1859":["(Berkata pula Ibrahim, \"Apakah urusan kalian) yakni kepentingan kalian (hai para utusan?\").",[["قَالَ","Dia berkata"],["فَمَا","Kemudian apa"],["خَطْبُكُمْ","(adalah) perniagaan kamu"],["أَيُّهَا","Wahai para rasul"],["ٱلْمُرْسَلُونَ","Wahai para rasul"]]],"1860":["(Mereka menjawab, \"Kami sesungguhnya diutus kepada kaum yang berdosa) orang-orang kafir, yang dimaksud adalah kaum Nabi Luth, untuk membinasakan mereka.",[["قَالُوٓا۟","Mereka berkata"],["إِنَّآ","Sesungguhnya kami"],["أُرْسِلْنَآ","[kami] telah dihantar"],["إِلَىٰ","kepada"],["قَوْمٍۢ","suatu kaum"],["مُّجْرِمِينَ","penjenayah"]]],"1861":["(Kecuali Luth dan pengikut-pengikutnya. Sesungguhnya Kami akan menyelamatkan mereka-semuanya) karena mereka adalah orang-orang yang beriman.",[["إِلَّآ","Kecuali"],["ءَالَ","keluarga"],["لُوطٍ","daripada Lut"],["إِنَّا","sesungguhnya, kita"],["لَمُنَجُّوهُمْ","pasti akan menyelamatkan mereka"],["أَجْمَعِينَ","semua"]]],"1862":["(Kecuali istrinya, kami telah menentukan, bahwa sesungguhnya ia itu termasuk orang-orang yang tertinggal.\") bersama orang-rang kafir lainnya yang tertimpa azab.",[["إِلَّا","Kecuali"],["ٱمْرَأَتَهُۥ","isterinya"],["قَدَّرْنَآ ۙ","Kami telah menetapkan"],["إِنَّهَا","bahawa dia"],["لَمِنَ","(adalah) pasti daripada"],["ٱلْغَـٰبِرِينَ","mereka yang tinggal di belakang"]]],"1863":["(Maka tatkala datang kepada kaum Luth) yang dimaksud adalah Nabi Luth (para utusan itu).",[["فَلَمَّا","Dan apabila"],["جَآءَ","datang"],["ءَالَ","(kepada) keluarga"],["لُوطٍ","(dari) Lut"],["ٱلْمُرْسَلُونَ","para rasul"]]],"1864":["(Ia berkata) kepada para utusan itu (\"Sesungguhnya kalian adalah orang-orang yang tidak dikenal.\")",[["قَالَ","Dia berkata"],["إِنَّكُمْ","Sesungguhnya kamu"],["قَوْمٌۭ","(adalah) suatu kaum"],["مُّنكَرُونَ","tidak diketahui"]]],"1865":["(Para utusan menjawab, \"Sebenarnya kami ini datang kepadamu dengan membawa apa yang mereka) yakni kaummu (mendustakannya.\") mereka meragukan tentangnya; subjek yang dimaksud adalah azab.",[["قَالُوا۟","Mereka berkata"],["بَلْ","Bahkan"],["جِئْنَـٰكَ","kami telah datang kepada kamu"],["بِمَا","dengan apa"],["كَانُوا۟","mereka adalah"],["فِيهِ","di dalamnya"],["يَمْتَرُونَ","mempertikaikan"]]],"1866":["(\"Dan kami datang kepadamu membawa kebenaran dan sesungguhnya kami betul-betul orang-orang yang benar.\") di dalam pengakuan kami ini.",[["وَأَتَيْنَـٰكَ","Dan kami telah datang kepada kamu"],["بِٱلْحَقِّ","dengan kebenaran"],["وَإِنَّا","dan sesungguhnya, kita"],["لَصَـٰدِقُونَ","sesungguhnya (adalah) orang yang benar"]]],"1867":["(Maka pergilah kamu di akhir malam dengan membawa keluargamu dan ikutilah mereka dari belakang) berjalanlah kamu di belakang keluargamu (dan janganlah seorang pun di antara kalian menoleh ke belakang) supaya ia tidak melihat besarnya azab yang menimpa mereka (dan teruskanlah perjalanan ke tempat yang diperintahkan kepada kalian) yaitu negeri Syam.",[["فَأَسْرِ","Jadi melancong"],["بِأَهْلِكَ","bersama keluarga kamu"],["بِقِطْعٍۢ","dalam bahagian"],["مِّنَ","daripada"],["ٱلَّيْلِ","malam"],["وَٱتَّبِعْ","dan ikut"],["أَدْبَـٰرَهُمْ","belakang mereka"],["وَلَا","dan bukan"],["يَلْتَفِتْ","mari lihat ke belakang"],["مِنكُمْ","antara kamu"],["أَحَدٌۭ","sesiapa sahaja"],["وَٱمْضُوا۟","dan teruskan"],["حَيْثُ","di mana"],["تُؤْمَرُونَ","kamu diperintahkan"]]],"1868":["(Dan telah Kami putuskan) telah Kami wahyukan (kepada Luth perkara itu) yaitu (bahwa mereka akan ditumpas habis di waktu subuh) lafal mushbihiin menjadi hal; artinya pembinasaan mereka dilakukan pada waktu subuh.",[["وَقَضَيْنَآ","Dan Kami sampaikan"],["إِلَيْهِ","kepadanya"],["ذَٰلِكَ","[bahawa]"],["ٱلْأَمْرَ","perkara itu"],["أَنَّ","bahawa"],["دَابِرَ","(the) akar"],["هَـٰٓؤُلَآءِ","(daripada) ini"],["مَقْطُوعٌۭ","akan dipotong"],["مُّصْبِحِينَ","(oleh) awal pagi"]]],"1869":["(Dan datanglah penduduk kota) yaitu kota Sodom yang para penduduknya adalah kaum Nabi Luth; mereka datang sewaktu mendengar bahwa di dalam rumah Nabi Luth terdapat beberapa laki-laki tampan yang masih muda-muda, mereka adalah para malaikat itu (dengan gembira) lafal yastabsyiruun menjadi hal, artinya keadaan mereka sangat gembira sekali dengan kedatangan para tamu itu, karena mereka berniat untuk melampiaskan nafsu homonya terhadap tamu-tamu itu.",[["وَجَآءَ","Dan datang"],["أَهْلُ","kaum"],["ٱلْمَدِينَةِ","(dari) bandar itu"],["يَسْتَبْشِرُونَ","bergembira"]]],"1870":["(Ia berkata) yakni Nabi Luth (\"Sesungguhnya mereka adalah tamuku; maka janganlah kalian memberi malu kepadaku.\")",[["قَالَ","Dia berkata"],["إِنَّ","Sesungguhnya"],["هَـٰٓؤُلَآءِ","ini"],["ضَيْفِى","(adalah) tetamu aku"],["فَلَا","jadi (jangan)"],["تَفْضَحُونِ","memalukan aku"]]],"1871":["(\"Dan bertakwalah kepada Allah dan janganlah kalian membuat aku terhina.\") dengan niat kalian yang ingin melampiaskan nafsu homo kalian terhadap mereka itu.",[["وَٱتَّقُوا۟","Dan ketakutan"],["ٱللَّهَ","Allah"],["وَلَا","dan jangan"],["تُخْزُونِ","memalukan aku"]]],"1872":["(Mereka berkata, \"Bukankah kami telah melarangmu dari menerima manusia?\") yakni menerima mereka sebagai tamumu.",[["قَالُوٓا۟","Mereka berkata"],["أَوَلَمْ","tidak"],["نَنْهَكَ","kami melarang kamu"],["عَنِ","daripada"],["ٱلْعَـٰلَمِينَ","dunia"]]],"1873":["(Luth berkata, \"Inilah putri-putriku, jika kalian hendak berbuat,\") untuk melampiaskan nafsu syahwat kalian, oleh sebab itu maka kawinilah mereka. Lalu Allah berfirman:",[["قَالَ","Dia berkata"],["هَـٰٓؤُلَآءِ","Ini"],["بَنَاتِىٓ","(adalah) anak perempuan aku"],["إِن","jika"],["كُنتُمْ","kamu akan menjadi"],["فَـٰعِلِينَ","pelaku"]]],"1874":["(\"Demi umurmu) khithab atau pembicaraan ini ditujukan kepada Nabi saw.; artinya demi hidupmu (sesungguhnya mereka terombang-ambing di dalam kemabukan atau kesesatan\") yakni mereka bergelimang di dalam kesesatannya.",[["لَعَمْرُكَ","Dengan hidup kamu"],["إِنَّهُمْ","sesungguhnya, mereka"],["لَفِى","berada di"],["سَكْرَتِهِمْ","mabuk mereka"],["يَعْمَهُونَ","merayau buta"]]],"1875":["(Maka mereka dibinasakan oleh suara keras yang mengguntur) oleh suara keras malaikat Jibril (ketika matahari akan terbit).",[["فَأَخَذَتْهُمُ","Jadi, tangkap mereka"],["ٱلصَّيْحَةُ","tangisan yang mengerikan"],["مُشْرِقِينَ","pada waktu matahari terbit"]]],"1876":["(Maka Kami jadikan bagian atasnya) yakni bagian atas kota mereka (terbalik ke bawah) malaikat Jibril mengangkatnya ke langit kemudian menjatuhkannya dalam keadaan terbalik ke tanah (dan Kami hujani mereka dengan batu dari tanah yang keras) yaitu tanah liat yang dibakar dengan api.",[["فَجَعَلْنَا","Dan Kami jadikan"],["عَـٰلِيَهَا","tertinggi (bahagian)"],["سَافِلَهَا","paling rendah"],["وَأَمْطَرْنَا","dan Kami menghujani"],["عَلَيْهِمْ","ke atas mereka"],["حِجَارَةًۭ","batu"],["مِّن","daripada"],["سِجِّيلٍ","tanah liat yang dibakar"]]],"1877":["(Sesungguhnya pada yang demikian itu) hal yang telah disebutkan itu (benar-benar terdapat tanda-tanda) yang menunjukkan kepada keesaan Allah (bagi orang-orang yang memperhatikan tanda-tanda) bagi orang-orang yang mau memperhatikannya kemudian mau mengambilnya sebagai pelajaran.",[["إِنَّ","Sesungguhnya"],["فِى","dalam"],["ذَٰلِكَ","bahawa"],["لَـَٔايَـٰتٍۢ","(ialah) tanda-tanda"],["لِّلْمُتَوَسِّمِينَ","bagi mereka yang memahami"]]],"1878":["(Dan sesungguhnya kota itu) yaitu kota kaum Nabi Luth (benar-benar terletak di jalan yang masih tetap dilalui manusia) yakni jalan yang masih dipakai oleh orang-orang Quraisy untuk menuju ke negeri Syam; jalan itu masih tetap ada; mengapa mereka tidak mau menjadikannya sebagai pelajaran?",[["وَإِنَّهَا","Dan sesungguhnya, ia"],["لَبِسَبِيلٍۢ","(berada) di jalan raya"],["مُّقِيمٍ","ditegakkan"]]],"1879":["(Sesungguhnya pada yang demikian itu benar-benar terdapat tanda-tanda) yakni pelajaran-pelajaran (bagi orang-orang yang beriman).",[["إِنَّ","Sesungguhnya"],["فِى","dalam"],["ذَٰلِكَ","bahawa"],["لَـَٔايَةًۭ","sesungguhnya (adalah) suatu tanda"],["لِّلْمُؤْمِنِينَ","untuk orang yang beriman"]]],"1880":["(Dan sesungguhnya) lafal in adalah bentuk takhfif daripada inna (adalah penduduk Aikah itu) yang terkenal dengan pohon-pohonnya yang subur dan rindang, terletak di dekat kota Madyan, dan mereka adalah kaum Nabi Syuaib (benar-benar kaum yang zalim) disebabkan mereka mendustakan Nabi Syuaib.",[["وَإِن","Dan telah"],["كَانَ","Dan telah"],["أَصْحَـٰبُ","(para) sahabat"],["ٱلْأَيْكَةِ","(dari) kayu itu"],["لَظَـٰلِمِينَ","sesungguhnya orang-orang yang zalim"]]],"1881":["(Maka Kami membalas perbuatan mereka itu) yaitu membinasakan mereka dengan musim panas yang sangat (Dan sesungguhnya kedua kota itu) yaitu kota kaum Nabi Luth dan kota kaum Nabi Syuaib (benar-benar terletak di jalan umum) yakni jalan raya (yang terang) jelas; mengapa kalian hai penduduk Mekah tidak mau mengambil pelajaran daripadanya?",[["فَٱنتَقَمْنَا","Maka Kami mengambil pembalasan"],["مِنْهُمْ","daripada mereka"],["وَإِنَّهُمَا","dan sesungguhnya, mereka berdua"],["لَبِإِمَامٍۢ","(berada) di lebuh raya"],["مُّبِينٍۢ","yang nyata"]]],"1882":["(Dan sesungguhnya penduduk kota Al-Hijr telah mendustakan) Al-Hijr, nama sebuah lembah yang terletak di antara kota Madinah dan negeri Syam; tempatnya kaum Tsamud (rasul-rasulnya) mereka mendustakan nabi mereka yaitu Nabi Saleh, hal ini berarti sama saja dengan mendustakan rasul-rasul lainnya, karena sesungguhnya ajaran yang disampaikan oleh para rasul itu pada hakikatnya sama, yaitu ajaran tauhid.",[["وَلَقَدْ","Dan sungguh"],["كَذَّبَ","dinafikan"],["أَصْحَـٰبُ","(para) sahabat"],["ٱلْحِجْرِ","(dari) Rocky Tract"],["ٱلْمُرْسَلِينَ","para Rasul"]]],"1883":["(Dan Kami telah mendatangkan kepada mereka tanda-tanda kekuasaan Kami) melalui seekor unta betina tetapi mereka selalu berpaling daripadanya) tidak mau memikirkan tentangnya.",[["وَءَاتَيْنَـٰهُمْ","Dan Kami beri mereka"],["ءَايَـٰتِنَا","Tanda-Tanda Kami"],["فَكَانُوا۟","tetapi mereka"],["عَنْهَا","daripada mereka"],["مُعْرِضِينَ","berpaling"]]],"1884":["(Dan mereka memahat rumah-rumah dari gunung-gunung batu yang didiami dengan aman.)",[["وَكَانُوا۟","Dan mereka dahulu (untuk)"],["يَنْحِتُونَ","mengukir"],["مِنَ","daripada"],["ٱلْجِبَالِ","pergunungan"],["بُيُوتًا","rumah-rumah"],["ءَامِنِينَ","selamat"]]],"1885":["(Maka mereka dibinasakan oleh suara keras yang mengguntur di waktu pagi) pada waktu subuh.",[["فَأَخَذَتْهُمُ","Tetapi menangkap mereka"],["ٱلصَّيْحَةُ","tangisan yang mengerikan"],["مُصْبِحِينَ","(pada) awal pagi"]]],"1886":["(Maka tidak dapat menolong) tidak dapat menolak (mereka) daripada azab (apa yang telah mereka usahakan) yaitu berupa bangunan-bangunan benteng dan harta benda yang mereka miliki dan mereka kumpulkan itu.",[["فَمَآ","Dan tidak"],["أَغْنَىٰ","dimanfaatkan"],["عَنْهُم","mereka"],["مَّا","apa"],["كَانُوا۟","mereka pernah (untuk)"],["يَكْسِبُونَ","peroleh"]]],"1887":["(Dan tidaklah Kami ciptakan langit dan bumi dan apa yang ada di antara keduanya melainkan dengan benar. Dan sesungguhnya hari kiamat itu pasti akan datang) setiap orang akan menemukan pembalasan amal perbuatannya (maka maafkanlah) hai Muhammad kaummu (dengan cara yang baik) berpalinglah engkau dari mereka tanpa dibarengi dengan rasa menggerutu; akan tetapi ayat ini dinasakh oleh ayat yang memerintahkan memerangi mereka.",[["وَمَا","Dan tidak"],["خَلَقْنَا","Kami mencipta"],["ٱلسَّمَـٰوَٰتِ","langit"],["وَٱلْأَرْضَ","dan bumi"],["وَمَا","dan apa sahaja"],["بَيْنَهُمَآ","(adalah) di antara mereka"],["إِلَّا","kecuali"],["بِٱلْحَقِّ ۗ","dalam kebenaran"],["وَإِنَّ","Dan sesungguhnya"],["ٱلسَّاعَةَ","Jam itu"],["لَـَٔاتِيَةٌۭ ۖ","(ada) pasti datang"],["فَٱصْفَحِ","Jadi terlepas pandang"],["ٱلصَّفْحَ","(dengan) pengampunan"],["ٱلْجَمِيلَ","pemurah"]]],"1888":["(Sesungguhnya Rabbmu, Dialah Yang Maha Pencipta) segala sesuatu (lagi Maha Mengetahui) segala sesuatu.",[["إِنَّ","Sesungguhnya"],["رَبَّكَ","Tuhanmu"],["هُوَ","Dia"],["ٱلْخَلَّـٰقُ","(ialah) Pencipta"],["ٱلْعَلِيمُ","yang Maha Mengetahui"]]],"1889":["(Dan sesungguhnya Kami telah berikan kepadamu tujuh ayat yang dibaca berulang-ulang) Nabi saw. telah bersabda bahwa yang dimaksud adalah surah Al-Fatihah. Demikianlah menurut riwayat yang dikemukakan oleh Bukhari dan Muslim; surah Al-Fatihah dinamakan demikian karena selalu dibaca berulang-ulang dalam setiap salat (dan Alquran yang agung).",[["وَلَقَدْ","Dan sungguh"],["ءَاتَيْنَـٰكَ","Kami telah memberi kamu"],["سَبْعًۭا","tujuh"],["مِّنَ","daripada"],["ٱلْمَثَانِى","yang sering diulang"],["وَٱلْقُرْءَانَ","dan al-Quran"],["ٱلْعَظِيمَ","Hebat"]]],"1890":["(Janganlah sekali-kali kamu menunjukkan pandangan matamu kepada berbagai macam kenikmatan hidup yang telah Kami berikan kepada beberapa golongan) maksudnya terhadap berbagai macam kemewahan hidup (di antara mereka, dan janganlah kamu bersedih hati terhadap mereka) jika mereka tidak beriman (dan berendah dirilah kamu) bersikap lembutlah kamu (terhadap orang-orang yang beriman.)",[["لَا","Jangan"],["تَمُدَّنَّ","memanjangkan"],["عَيْنَيْكَ","mata kamu"],["إِلَىٰ","ke arah"],["مَا","apa"],["مَتَّعْنَا","Kami telah kurniakan"],["بِهِۦٓ","dengannya"],["أَزْوَٰجًۭا","(kepada) kategori"],["مِّنْهُمْ","daripada mereka"],["وَلَا","dan jangan"],["تَحْزَنْ","bersedih"],["عَلَيْهِمْ","atas mereka"],["وَٱخْفِضْ","Dan lebih rendah"],["جَنَاحَكَ","sayap kamu"],["لِلْمُؤْمِنِينَ","kepada orang yang beriman"]]],"1891":["(Dan katakanlah, \"Sesungguhnya aku adalah pemberi peringatan) tentang azab Allah supaya jangan menimpa kalian (yang menjelaskan.\") artinya yang jelas peringatannya.",[["وَقُلْ","Dan katakan"],["إِنِّىٓ","Sesungguhnya aku"],["أَنَا","[Aku] adalah"],["ٱلنَّذِيرُ","seorang pemberi amaran"],["ٱلْمُبِينُ","yang nyata"]]],"1892":["(Sebagaimana Kami telah menurunkan) azab (kepada orang-orang yang membagi-bagi kitab Allah) yaitu Yahudi dan Nasrani.",[["كَمَآ","Sebagai"],["أَنزَلْنَا","Kami turunkan"],["عَلَى","pada"],["ٱلْمُقْتَسِمِينَ","mereka yang berpecah"]]],"1893":["(Yaitu orang-orang yang telah menjadikan kitab bacaan) yaitu kitab-kitab yang diturunkan kepada mereka (terbagi-bagi) menjadi beberapa bagian; mereka beriman terhadap sebagiannya dan ingkar terhadap sebagian yang lainnya. Menurut pendapat orang lain dikatakan, yang dimaksud dengan mereka adalah orang-orang yang menguasai jalan-jalan yang menuju ke Mekah dengan maksud untuk menghalang-halangi manusia masuk Islam. Sebagian dari mereka mengatakan tentang Alquran, bahwa Alquran itu adalah sihir; sebagian lainnya mengatakan, Alquran adalah peramal; sedangkan sebagian yang lainnya lagi mengatakan, bahwa Alquran adalah syair.",[["ٱلَّذِينَ","Orang yang"],["جَعَلُوا۟","telah membuat"],["ٱلْقُرْءَانَ","al-Quran"],["عِضِينَ","(dalam) bahagian"]]],"1894":["(Maka demi Rabbmu, Kami pasti akan menanyai mereka semuanya) dengan pertanyaan yang bernada mengejek.",[["فَوَرَبِّكَ","Maka demi Tuhanmu"],["لَنَسْـَٔلَنَّهُمْ","sesungguhnya Kami akan menyoal mereka"],["أَجْمَعِينَ","semua"]]],"1895":["(Tentang apa yang telah mereka kerjakan dahulu.)",[["عَمَّا","Tentang apa"],["كَانُوا۟","mereka pernah (untuk)"],["يَعْمَلُونَ","lakukan"]]],"1896":["(Maka sampaikanlah olehmu secara terang-terangan) hai Muhammad (segala apa yang diperintahkan kepadamu) untuk melakukannya, artinya sampaikanlah secara terang-terangan dan laksanakanlah dengan rutin (dan berpalinglah dari orang-orang yang musyrik) ayat ini diturunkan sebelum diperintahkan untuk berjihad.",[["فَٱصْدَعْ","Maka isytiharkan"],["بِمَا","tentang apa"],["تُؤْمَرُ","kamu diperintahkan"],["وَأَعْرِضْ","dan berpaling"],["عَنِ","daripada"],["ٱلْمُشْرِكِينَ","orang musyrik"]]],"1897":["(Sesungguhnya Kami memelihara kamu daripada kejahatan orang-orang yang memperolok-olokkan) kamu, Kami akan membinasakan masing-masing dari mereka dengan malapetaka. Mereka yang memperolok-olokkan ialah Walid bin Mughirah, Ashi bin Wa'il, Addi bin Qais, Aswad bin Abdul Mutthalib dan Aswad bin Abdu Yaghuts.",[["إِنَّا","Sesungguhnya Kami"],["كَفَيْنَـٰكَ","[Kami] cukup untuk kamu"],["ٱلْمُسْتَهْزِءِينَ","(terhadap) orang-orang yang memperolok-olokkan"]]],"1898":["(Yaitu orang-orang yang menganggap adanya tuhan yang lain di samping Allah) kalimat ayat ini berkedudukan menjadi sifat. Akan tetapi menurut suatu pendapat dianggap sebagai mubtada, oleh karena mengandung makna syarat, maka khabarnya dimasuki huruf fa, yaitu (maka mereka kelak akan mengetahui) akibat-akibat perbuatannya itu.",[["ٱلَّذِينَ","Orang yang"],["يَجْعَلُونَ","sediakan"],["مَعَ","dengan"],["ٱللَّهِ","Allah"],["إِلَـٰهًا","tuhan"],["ءَاخَرَ ۚ","yang lain"],["فَسَوْفَ","Tetapi tidak lama lagi"],["يَعْلَمُونَ","mereka akan tahu"]]],"1899":["(Dan sungguh) lafal qad menunjukkan makna littahqiq (Kami telah mengetahui, bahwa dadamu menjadi sempit disebabkan apa yang mereka katakan) yaitu disebabkan perolok-olokkan dan pendustaan mereka itu.",[["وَلَقَدْ","Dan sesungguhnya"],["نَعْلَمُ","Kami tahu"],["أَنَّكَ","bahawa [kamu]"],["يَضِيقُ","(adalah) kesempitan"],["صَدْرُكَ","payudara kamu"],["بِمَا","oleh apa"],["يَقُولُونَ","mereka berkata"]]],"1900":["(Maka bertasbihlah) seraya (memuji Rabbmu) artinya katakanlah subhaanallaah wa bihamdihi (dan jadilah kamu di antara orang-orang yang bersujud) yakni orang-orang yang mendirikan salat.",[["فَسَبِّحْ","Maka bertasbihlah"],["بِحَمْدِ","dengan pujian itu"],["رَبِّكَ","Tuhanmu"],["وَكُن","dan jadilah"],["مِّنَ","daripada"],["ٱلسَّـٰجِدِينَ","mereka yang sujud"]]],"1901":["(Dan sembahlah Rabbmu sampai datang kepadamu yang diyakini) yaitu ajal.",[["وَٱعْبُدْ","Dan ibadah"],["رَبَّكَ","Tuhanmu"],["حَتَّىٰ","sehingga"],["يَأْتِيَكَ","datang kepada kamu"],["ٱلْيَقِينُ","kepastian"]]],"1902":["Ketika orang-orang musyrik merasa lambat akan datangnya azab yang diancamkan kepada mereka, lalu turunlah firman-Nya: (Telah pasti datangnya ketetapan Allah) yakni hari kiamat. Lafal ataa diungkapkan dalam bentuk fi`il madhi untuk menunjukkan kepastian kejadiannya, artinya telah dekat (maka janganlah kalian meminta disegerakan datangnya) artinya janganlah kalian meminta disegerakan sebelum saatnya karena sesungguhnya hari kiamat itu pasti akan terjadi (Maha Suci Allah) kalimat ini mengandung makna memahasucikan Dia (dan Maha Tinggi dari apa yang mereka persekutukan) di samping-Nya.",[["أَتَىٰٓ","Akan datang"],["أَمْرُ","(perintah) Allah"],["ٱللَّهِ","(perintah) Allah"],["فَلَا","jadi (jangan)"],["تَسْتَعْجِلُوهُ ۚ","(bersabar) untuknya"],["سُبْحَـٰنَهُۥ","Maha Suci Dia"],["وَتَعَـٰلَىٰ","dan Maha Suci Dia"],["عَمَّا","atas apa"],["يُشْرِكُونَ","mereka bergaul"]]],"1903":["(Dia menurunkan malaikat) yakni malaikat Jibril (dengan wahyu) dengan membawa wahyu (atas perintah-Nya) berdasarkan kehendak-Nya (kepada siapa yang Dia kehendaki di antara hamba-hamba-Nya) mereka adalah para nabi (yaitu) huruf an di sini bermakna mufassirah atau kata penafsir (peringatkanlah olehmu sekalian) peringatkanlah orang-orang kafir dengan azab, dan beritahukanlah kepada mereka (bahwasanya tidak ada Tuhan melainkan Aku, maka hendaklah kalian bertakwa kepada-Ku) artinya takutlah kalian kepada-Ku.",[["يُنَزِّلُ","Dia menghantar turun"],["ٱلْمَلَـٰٓئِكَةَ","para Malaikat"],["بِٱلرُّوحِ","dengan ilham"],["مِنْ","daripada"],["أَمْرِهِۦ","PerintahNya"],["عَلَىٰ","ke atas"],["مَن","yang"],["يَشَآءُ","Dia kehendaki"],["مِنْ","daripada"],["عِبَادِهِۦٓ","hambanya"],["أَنْ","bahawa"],["أَنذِرُوٓا۟","Beri amaran"],["أَنَّهُۥ","bahawa [Dia]"],["لَآ","(ada) tidak"],["إِلَـٰهَ","tuhan"],["إِلَّآ","kecuali"],["أَنَا۠","aku"],["فَٱتَّقُونِ","maka takutlah kepada-Ku"]]],"1904":["(Dia menciptakan langit dan bumi dengan hak) artinya secara sungguh-sungguh. (Maha Tinggi Allah daripada apa yang mereka persekutukan) bersama-Nya yaitu berhala-berhala.",[["خَلَقَ","Dia cipta"],["ٱلسَّمَـٰوَٰتِ","langit"],["وَٱلْأَرْضَ","dan bumi"],["بِٱلْحَقِّ ۚ","dalam kebenaran"],["تَعَـٰلَىٰ","Maha Tinggi Dia"],["عَمَّا","atas apa"],["يُشْرِكُونَ","mereka bergaul"]]],"1905":["(Dia telah menciptakan manusia dari mani) mulai dari mani hingga menjadi manusia yang kuat lagi kekar (tiba-tiba ia menjadi pembantah) sangat memusuhi (yang nyata) lalu Allah menjelaskan tentang bantahan manusia itu yang tidak mempercayai adanya hari berbangkit, yaitu melalui firman-Nya yang lain: \"Siapakah yang dapat menghidupkan tulang-belulang yang telah hancur luluh.\" (Q.S. Yasin 78)",[["خَلَقَ","Dia cipta"],["ٱلْإِنسَـٰنَ","jenis manusia"],["مِن","daripada"],["نُّطْفَةٍۢ","kuantiti air mani seminit"],["فَإِذَا","maka lihatlah"],["هُوَ","dia"],["خَصِيمٌۭ","(adalah) lawan"],["مُّبِينٌۭ","yang nyata"]]],"1906":["(Dan binatang ternak) yakni unta, sapi dan kambing. Lafal al-an`aam dibaca nashab karena dinashabkan oleh fi`il yang diperkirakan keberadaannya lalu fi`il tersebut ditafsirkan atau dijelaskan oleh lafal berikut ini, yaitu: (Dia telah menciptakannya untuk kalian) sebagian dari manusia (padanya ada kehangatan) yaitu bulu dan kulitnya dapat dibuat pakaian dan selimut untuk penghangat tubuh kalian (dan berbagai manfaat) yaitu dari anak-anaknya, air susunya dan dapat dijadikan sebagai kendaraan (dan sebagiannya kalian makan) zharaf didahulukan karena untuk tujuan fashilah.",[["وَٱلْأَنْعَـٰمَ","Dan lembu"],["خَلَقَهَا ۗ","Dia menciptakan mereka"],["لَكُمْ","bagi kamu"],["فِيهَا","dalam diri mereka"],["دِفْءٌۭ","(adalah) kehangatan"],["وَمَنَـٰفِعُ","dan faedah"],["وَمِنْهَا","dan daripada mereka"],["تَأْكُلُونَ","kamu makan"]]],"1907":["(Dan kalian memperoleh pandangan yang indah padanya) yakni sebagai perhiasan kalian (ketika kalian membawanya kembali ke kandang) ketika kalian menggiringnya kembali ke kandangnya di waktu sore hari (dan ketika kalian melepaskannya ke tempat penggembalaan) kalian mengeluarkannya dari kandangnya menuju ke tempat penggembalaan di waktu pagi hari.",[["وَلَكُمْ","Dan untuk kamu"],["فِيهَا","dalam diri mereka"],["جَمَالٌ","(ialah) kecantikan"],["حِينَ","apabila"],["تُرِيحُونَ","kamu bawa mereka masuk"],["وَحِينَ","dan apabila"],["تَسْرَحُونَ","kamu bawa mereka keluar"]]],"1908":["(Dan ia dapat memikul beban-beban kalian) barang-barang kalian (ke suatu negeri yang kalian tidak sanggup sampai kepadanya) kalian tidak sanggup mencapainya tanpa memakai kendaraan unta (melainkan dengan kesukaran-kesukaran yang memayahkan diri) yang membuat payah diri kalian. (Sesungguhnya Rabb kalian benar-benar Maha Pengasih lagi Maha Penyayang) terhadap kalian, Dia telah menciptakannya untuk kalian manfaatkan.",[["وَتَحْمِلُ","Dan mereka membawa"],["أَثْقَالَكُمْ","bebanan kamu"],["إِلَىٰ","kepada"],["بَلَدٍۢ","sebuah tanah"],["لَّمْ","tidak"],["تَكُونُوا۟","kamu boleh"],["بَـٰلِغِيهِ","mencapainya"],["إِلَّا","kecuali"],["بِشِقِّ","dengan masalah yang besar"],["ٱلْأَنفُسِ ۚ","(kepada) dirimu sendiri"],["إِنَّ","Sesungguhnya"],["رَبَّكُمْ","Tuhanmu"],["لَرَءُوفٌۭ","sesungguhnya Maha Pemurah"],["رَّحِيمٌۭ","Maha Mengasihani"]]],"1909":["(Dan) Dia telah menciptakan (kuda, bighal dan keledai agar kalian menungganginya dan menjadikannya sebagai perhiasan) lafal ziinatan menjadi maf`ul lah. Disebutkannya kedua `illat itu, yaitu untuk ditunggangi dan dianggap sebagai perhiasan hal ini sama sekali tidak bertentangan dengan manfaat lain yang ada padanya. Seperti halnya pada kuda, selain dapat ditunggangi dan dijadikan perhiasan dagingnya dapat dimakan, hal ini telah ditetapkan berdasarkan hadis kitab Sahih Bukhari dan Muslim. (Dan Allah menciptakan apa yang kalian tidak mengetahuinya) berupa hal-hal yang aneh dan menakjubkan.",[["وَٱلْخَيْلَ","Dan kuda"],["وَٱلْبِغَالَ","dan keldai"],["وَٱلْحَمِيرَ","dan keldai"],["لِتَرْكَبُوهَا","untuk kamu menunggang mereka"],["وَزِينَةًۭ ۚ","dan (sebagai) perhiasan"],["وَيَخْلُقُ","Dan Dia menciptakan"],["مَا","apa"],["لَا","tidak"],["تَعْلَمُونَ","kamu tahu"]]],"1910":["(Dan hak bagi Allah menerangkan jalan yang lurus) hak bagi Allah menjelaskannya (dan di antara jalan-jalan) tersebut (ada yang bengkok) menyimpang dari jalan yang lurus. (Dan jika Dia menghendaki) untuk memberi petunjuk kepada kalian (niscaya Dia memberi petunjuk kepada kalian) ke jalan yang lurus (semuanya) sehingga kalian semua mendapat petunjuk ke jalan yang lurus itu atas kehendak kalian sendiri.",[["وَعَلَى","Dan selepas"],["ٱللَّهِ","Allah"],["قَصْدُ","(adalah) arah"],["ٱلسَّبِيلِ","(dari) jalan"],["وَمِنْهَا","dan antara mereka"],["جَآئِرٌۭ ۚ","(adalah) bengkok"],["وَلَوْ","Dan jika"],["شَآءَ","Dia berkehendak"],["لَهَدَىٰكُمْ","nescaya Dia akan memberi petunjuk kepada kamu"],["أَجْمَعِينَ","semua"]]],"1911":["(Dialah Yang telah menurunkan air hujan itu dari langit untuk kalian, sebagiannya menjadi minuman) untuk kalian minum (dan sebagiannya menjadi tumbuh-tumbuhan) maksudnya oleh sebab air itu menjadi suburlah tumbuh-tumbuhan (yang pada tempat tumbuhnya kalian menggembalakan ternak kalian) kalian jadikan sebagai tempat menggembalakan ternak.",[["هُوَ","Dia"],["ٱلَّذِىٓ","(ialah) Yang"],["أَنزَلَ","menghantar turun"],["مِنَ","daripada"],["ٱلسَّمَآءِ","langit"],["مَآءًۭ ۖ","air"],["لَّكُم","bagi kamu"],["مِّنْهُ","daripadanya"],["شَرَابٌۭ","(adalah) minum"],["وَمِنْهُ","dan daripadanya"],["شَجَرٌۭ","(tumbuh) tumbuh-tumbuhan"],["فِيهِ","di mana"],["تُسِيمُونَ","kamu menggembalakan ternakan kamu"]]],"1912":["(Dia menumbuhkan bagi kalian dengan air itu tanam-tanaman, zaitun, kurma, anggur dan segala macam buah-buahan. Sesungguhnya pada yang demikian itu) hal yang telah disebutkan itu (benar-benar ada tanda) yang menunjukkan akan keesaan Allah swt. (bagi kaum yang memikirkan) mengenai ciptaan-Nya sehingga mereka mau beriman karenanya.",[["يُنۢبِتُ","Dia menyebabkan berkembang"],["لَكُم","bagi kamu"],["بِهِ","dengannya"],["ٱلزَّرْعَ","tanaman"],["وَٱلزَّيْتُونَ","dan buah zaitun"],["وَٱلنَّخِيلَ","dan pokok kurma"],["وَٱلْأَعْنَـٰبَ","dan buah anggur"],["وَمِن","dan daripada"],["كُلِّ","setiap jenis"],["ٱلثَّمَرَٰتِ ۗ","(dari) buah-buahan"],["إِنَّ","Sesungguhnya"],["فِى","dalam"],["ذَٰلِكَ","bahawa"],["لَـَٔايَةًۭ","sesungguhnya (adalah) satu tanda"],["لِّقَوْمٍۢ","bagi kaum"],["يَتَفَكَّرُونَ","yang merenung"]]],"1913":["(Dan Dia menundukkan malam dan siang untuk kalian, dan matahari) lafal wasysyamsa bila dibaca nashab berarti diathafkan kepada lafal sebelumnya, bila dibaca rafa' berarti menjadi mubtada (bulan dan bintang-bintang) kedua lafal ini dapat dibaca nashab dan rafa` (ditundukkan) kalau dibaca nashab, maka berkedudukan menjadi hal, dan kalau dibaca rafa` maka menjadi khabar (dengan perintah-Nya) berdasarkan kehendak-Nya (Sesungguhnya pada yang demikian itu benar-benar ada tanda-tanda kekuasaan Allah bagi kaum yang memahami-Nya) bagi kaum yang mau memikirkannya.",[["وَسَخَّرَ","Dan Dia telah menundukkan"],["لَكُمُ","bagi kamu"],["ٱلَّيْلَ","malam"],["وَٱلنَّهَارَ","dan hari"],["وَٱلشَّمْسَ","dan matahari"],["وَٱلْقَمَرَ ۖ","dan bulan"],["وَٱلنُّجُومُ","dan bintang"],["مُسَخَّرَٰتٌۢ","(adalah) tertakluk"],["بِأَمْرِهِۦٓ ۗ","dengan perintahNya"],["إِنَّ","Sesungguhnya"],["فِى","dalam"],["ذَٰلِكَ","bahawa"],["لَـَٔايَـٰتٍۢ","sesungguhnya (adalah) tanda-tanda"],["لِّقَوْمٍۢ","bagi kaum"],["يَعْقِلُونَ","yang menggunakan akal"]]],"1914":["(Dan) Dia menundukkan pula bagi kalian (apa yang Dia ciptakan) makhluk yang telah Dia ciptakan (untuk kalian di bumi ini) berupa hewan-hewan dan tumbuh-tumbuhan serta lain-lainnya (dengan berlain-lainan warnanya) seperti ada yang merah, kuning, hijau dan lain sebagainya (Sesungguhnya pada yang demikian itu benar-benar terdapat tanda kekuasaan Allah bagi kaum yang mengingatnya) mengambilnya sebagai pelajaran.",[["وَمَا","Dan apa sahaja"],["ذَرَأَ","Dia membiak"],["لَكُمْ","bagi kamu"],["فِى","dalam"],["ٱلْأَرْضِ","bumi"],["مُخْتَلِفًا","(daripada) berbeza-beza"],["أَلْوَٰنُهُۥٓ ۗ","warna"],["إِنَّ","Sesungguhnya"],["فِى","dalam"],["ذَٰلِكَ","bahawa"],["لَـَٔايَةًۭ","sesungguhnya (adalah) satu tanda"],["لِّقَوْمٍۢ","bagi kaum"],["يَذَّكَّرُونَ","yang ingat"]]],"1915":["(Dan Dialah yang menundukkan lautan) Dia telah membuatnya jinak sehingga dapat dinaiki dan diselami (agar kalian dapat memakan daripadanya daging yang segar) yaitu ikan (dan kalian mengeluarkan dari lautan itu perhiasan yang kalian pakai) yaitu berupa mutiara dan marjan (dan kamu melihat) menyaksikan (bahtera) perahu-perahu (berlayar padanya) dapat melaju di atas air; artinya dapat membelah ombak melaju ke depan atau ke belakang hanya ditiup oleh satu arah angin (dan supaya kalian mencari) lafal ini diathafkan kepada lafal lita'kuluu, artinya supaya kalian mencari keuntungan (dari karunia-Nya) karunia Allah swt. lewat berniaga (dan supaya kalian bersyukur) kepada Allah swt. atas karunia itu.",[["وَهُوَ","Dan Dia"],["ٱلَّذِى","(ialah) Yang"],["سَخَّرَ","tertakluk"],["ٱلْبَحْرَ","laut"],["لِتَأْكُلُوا۟","untuk kamu makan"],["مِنْهُ","daripadanya"],["لَحْمًۭا","daging"],["طَرِيًّۭا","segar"],["وَتَسْتَخْرِجُوا۟","dan yang kamu lahirkan"],["مِنْهُ","daripadanya"],["حِلْيَةًۭ","perhiasan"],["تَلْبَسُونَهَا","(bahawa) kamu memakainya"],["وَتَرَى","Dan kamu lihat"],["ٱلْفُلْكَ","kapal-kapal itu"],["مَوَاخِرَ","membajak"],["فِيهِ","melaluinya"],["وَلِتَبْتَغُوا۟","dan supaya kamu mencari"],["مِن","daripada"],["فَضْلِهِۦ","Bounty-Nya"],["وَلَعَلَّكُمْ","dan supaya kamu boleh"],["تَشْكُرُونَ","(bersyukur)."]]],"1916":["(Dan Dia menancapkan gunung-gunung di bumi dengan kokohnya) gunung-gunung yang tegak kokoh supaya (tidak) jangan (bumi itu goncang) bergerak (bersama kalian dan) Dia telah menciptakan padanya (sungai-sungai) seperti sungai Nil (dan jalan-jalan) jalan untuk dilalui (agar kalian mendapat petunjuk) untuk sampai kepada tujuan-tujuan kalian.",[["وَأَلْقَىٰ","Dan Dia telah melemparkan"],["فِى","dalam"],["ٱلْأَرْضِ","bumi"],["رَوَٰسِىَ","gunung yang kukuh"],["أَن","jangan-jangan"],["تَمِيدَ","ia harus bergegar"],["بِكُمْ","bersama kamu"],["وَأَنْهَـٰرًۭا","dan sungai"],["وَسُبُلًۭا","dan jalan raya"],["لَّعَلَّكُمْ","supaya kamu"],["تَهْتَدُونَ","dibimbing"]]],"1917":["(Dan Dia ciptakan, tanda-tanda) dengan melaluinya kalian mendapat petunjuk arah jalan yang kalian lalui, seperti gunung-gunung dan sungai-sungai. (Dan dengan bintang-bintang itulah) yang dimaksud adalah bentuk jamak sekalipun lafalnya mufrad (mereka mendapat petunjuk) jalan dan arah kiblat di waktu malam hari.",[["وَعَلَـٰمَـٰتٍۢ ۚ","Dan mercu tanda"],["وَبِٱلنَّجْمِ","Dan oleh bintang-bintang"],["هُمْ","mereka"],["يَهْتَدُونَ","membimbing diri mereka sendiri"]]],"1918":["(Maka apakah Tuhan yang menciptakan itu) itu Allah (sama dengan yang tidak menciptakan apa-apa) yang dimaksud adalah berhala-berhala, karena mereka menyekutukannya bersama dengan Allah dalam hal beribadah? Tentu saja tidak. (Maka mengapa kalian tidak mengambil pelajaran) dari hal ini, karenanya kemudian kalian beriman?",[["أَفَمَن","Maka adalah Dia yang"],["يَخْلُقُ","mencipta"],["كَمَن","seperti seorang yang"],["لَّا","tidak"],["يَخْلُقُ ۗ","cipta"],["أَفَلَا","Kemudian kamu tidak akan"],["تَذَكَّرُونَ","ingat"]]],"1919":["(Dan jika kalian menghitung-hitung nikmat Allah, niscaya kalian tak dapat menentukan jumlahnya) tidak dapat menghitungnya terlebih lagi untuk mensyukurinya secara layak kalian tidak akan mampu melakukannya (Sesungguhnya Allah benar-benar Maha Pengampun lagi Maha Penyayang) karena Dia telah melimpahkan nikmat-Nya kepada kalian padahal kalian meremehkan dan mendurhakai-Nya.",[["وَإِن","Dan jika"],["تَعُدُّوا۟","kamu patut mengira"],["نِعْمَةَ","nikmat Allah"],["ٱللَّهِ","nikmat Allah"],["لَا","tidak"],["تُحْصُوهَآ ۗ","kamu boleh menghitung mereka"],["إِنَّ","Sesungguhnya"],["ٱللَّهَ","Allah"],["لَغَفُورٌۭ","Maha Pengampun"],["رَّحِيمٌۭ","Maha Mengasihani"]]],"1920":["(Dan Allah mengetahui apa yang kalian rahasiakan dan apa yang kalian lahirkan.)",[["وَٱللَّهُ","Dan Allah"],["يَعْلَمُ","mengetahui"],["مَا","apa"],["تُسِرُّونَ","kamu sembunyikan"],["وَمَا","dan apa"],["تُعْلِنُونَ","kamu dedahkan"]]],"1921":["(Dan berhala-berhala yang mereka seru) dapat dibaca yad`uuna dan tad`uuna, artinya yang mereka sembah (selain Allah) yang dimaksud adalah berhala-berhala (tidak dapat membuat sesuatu apa pun sedangkan berhala-berhala itu sendiri dibuat orang) mereka pahat dari batu atau dari bahan-bahan yang lain.",[["وَٱلَّذِينَ","Dan mereka yang"],["يَدْعُونَ","mereka menyeru"],["مِن","selain"],["دُونِ","selain"],["ٱللَّهِ","Allah"],["لَا","tidak"],["يَخْلُقُونَ","mereka cipta"],["شَيْـًۭٔا","sesuatu"],["وَهُمْ","tetapi (adalah) diri mereka sendiri"],["يُخْلَقُونَ","dicipta"]]],"1922":["(Berhala-berhala itu benda mati) tidak ada rohnya; lafal ini menjadi khabar yang kedua (tidak hidup) berkedudukan menjadi taukid atau pengukuh (dan mereka tidak mengetahui) berhala-berhala tersebut tidak mengetahui (bilakah) menunjukkan makna waktu (mereka akan dibangkitkan) yang dimaksud adalah makhluk semuanya; maka jika keadaannya demikian mengapa berhala-berhala itu mereka sembah? Kalau demikian berarti tiada tuhan melainkan hanya Yang Maha Pencipta, Yang Maha Hidup dan Yang Maha Mengetahui semua yang gaib.",[["أَمْوَٰتٌ","(Mereka) mati"],["غَيْرُ","tidak bernyawa"],["أَحْيَآءٍۢ ۖ","tidak bernyawa"],["وَمَا","Dan tidak"],["يَشْعُرُونَ","mereka rasa"],["أَيَّانَ","apabila"],["يُبْعَثُونَ","mereka akan dibangkitkan"]]],"1923":["(Tuhan kalian) berhak untuk disembah oleh kalian (adalah Tuhan Yang Maha Esa) tidak ada tandingan-Nya, baik dalam Dzat-Nya maupun sifat-Nya, yaitu Allah swt. (Maka orang-orang yang tidak beriman kepada akhirat hati mereka mengingkari) keesaan Allah (sedangkan mereka sendiri adalah orang-orang yang sombong) orang-orang yang takabur tidak mau beriman kepada adanya hari akhirat.",[["إِلَـٰهُكُمْ","tuhan kamu"],["إِلَـٰهٌۭ","(ialah) Tuhan"],["وَٰحِدٌۭ ۚ","satu"],["فَٱلَّذِينَ","Tetapi mereka yang"],["لَا","jangan"],["يُؤْمِنُونَ","beriman"],["بِٱلْـَٔاخِرَةِ","di akhirat"],["قُلُوبُهُم","hati mereka"],["مُّنكِرَةٌۭ","menolak"],["وَهُم","dan mereka"],["مُّسْتَكْبِرُونَ","(adalah) sombong"]]],"1924":["(Tidak diragukan lagi) memang benar (bahwa sesungguhnya Allah mengetahui apa yang mereka rahasiakan dan apa yang mereka lahirkan) maka Dia membalas mereka berdasarkan hal tersebut. (Sesungguhnya Allah tidak menyukai orang-orang yang sombong) dengan pengertian, bahwa Dia akan menyiksa mereka.",[["لَا","Tidak syak lagi"],["جَرَمَ","Tidak syak lagi"],["أَنَّ","bahawa"],["ٱللَّهَ","Allah"],["يَعْلَمُ","mengetahui"],["مَا","apa"],["يُسِرُّونَ","mereka sembunyikan"],["وَمَا","dan apa"],["يُعْلِنُونَ ۚ","mereka mendedahkan"],["إِنَّهُۥ","Sesungguhnya Dia"],["لَا","tidak"],["يُحِبُّ","cinta"],["ٱلْمُسْتَكْبِرِينَ","yang sombong"]]],"1925":["Ayat ini diturunkan berkenaan dengan Nadhr bin Harits (Dan apabila dikatakan kepada mereka, \"Apakah) maa di sini bermakna istifham atau kata tanya (yang) dzaa di sini berfungsi sebagai maushul (telah diturunkan Rabb kalian?\") kepada Muhammad. (Mereka menjawab,) yaitu (\"Dongeng-dongengan) buat-buatan (orang-orang dahulu.\") untuk menyesatkan manusia.",[["وَإِذَا","Dan apabila"],["قِيلَ","dikatakan"],["لَهُم","kepada mereka"],["مَّاذَآ","Apa"],["أَنزَلَ","telahkah Tuhanmu menurunkan"],["رَبُّكُمْ ۙ","telahkah Tuhanmu menurunkan"],["قَالُوٓا۟","Mereka berkata"],["أَسَـٰطِيرُ","Tales"],["ٱلْأَوَّلِينَ","(dari) yang kuno"]]],"1926":["(Ucapan mereka, menyebabkan mereka memikul) akibatnya mereka akan memikul (dosa-dosanya) kesalahan-kesalahannya (dengan sepenuhnya) artinya tidak ada sesuatu pun yang dapat dijadikan sebagai tebusan daripadanya (pada hari kiamat, dan sebagian) ditimpakan pula kepada mereka sebagian (dosa-dosa orang-orang yang mereka sesatkan yang tidak mengetahui sedikit pun) bahwa mereka disesatkan, karena mereka mengajak orang-orang yang diserunya ke jalan yang sesat, kemudian orang-orang yang diserunya itu mengikuti langkah mereka. Dengan demikian maka orang-orang yang menyeru mereka ikut andil dalam dosanya. (Ingatlah, amat buruklah) amat jeleklah (apa yang mereka pikul itu) yakni, dosa-dosa yang mereka pikul itu adalah seburuk-buruk dosa.",[["لِيَحْمِلُوٓا۟","Supaya mereka menanggungnya"],["أَوْزَارَهُمْ","beban mereka sendiri"],["كَامِلَةًۭ","(dalam) penuh"],["يَوْمَ","pada (hari) itu"],["ٱلْقِيَـٰمَةِ ۙ","Kiamat"],["وَمِنْ","dan daripada"],["أَوْزَارِ","bebanan"],["ٱلَّذِينَ","(dari) mereka yang"],["يُضِلُّونَهُم","mereka menyesatkan [mereka]"],["بِغَيْرِ","tanpa"],["عِلْمٍ ۗ","pengetahuan"],["أَلَا","Tidak dinafikan"],["سَآءَ","jahat"],["مَا","(ialah) apa"],["يَزِرُونَ","mereka akan menanggung"]]],"1927":["(Sesungguhnya orang-orang yang sebelum mereka telah mengadakan makar) yaitu seperti apa yang telah dilakukan oleh raja Namrudz; ia membangun sebuah pencakar langit, lalu ia menaikinya dengan maksud untuk memerangi penduduk langit (maka Allah menghancurkan) bertujuan untuk menghancurkan (rumah-rumah mereka dari fondasinya) untuk itu maka Allah mengirimkan angin topan dan gempa bumi yang keras sehingga hancur leburlah apa yang telah mereka bangun itu (lalu atap rumah-rumah mereka jatuh menimpa mereka dari atas) artinya mereka ada di bawahnya lalu tertimpa hal tersebut (dan datanglah azab itu kepada mereka dari tempat yang tidak mereka sadari) artinya azab itu datang kepada mereka dari arah yang tidak mereka duga sebelumnya. Akan tetapi menurut pendapat yang lain dikatakan bahwa ini hanya tamtsil tentang dibinasakannya makar mereka yang telah direncanakan sebelumnya terhadap rasul.",[["قَدْ","Sesungguhnya"],["مَكَرَ","diplot"],["ٱلَّذِينَ","orang yang"],["مِن","(ada) sebelum mereka"],["قَبْلِهِمْ","(ada) sebelum mereka"],["فَأَتَى","tetapi Allah datang"],["ٱللَّهُ","tetapi Allah datang"],["بُنْيَـٰنَهُم","(di) bangunan mereka"],["مِّنَ","daripada"],["ٱلْقَوَاعِدِ","asas-asas"],["فَخَرَّ","jadi jatuh"],["عَلَيْهِمُ","ke atas mereka"],["ٱلسَّقْفُ","bumbung"],["مِن","daripada"],["فَوْقِهِمْ","di atas mereka"],["وَأَتَىٰهُمُ","dan datang kepada mereka"],["ٱلْعَذَابُ","azab"],["مِنْ","daripada"],["حَيْثُ","di mana"],["لَا","mereka (tidak) menyedarinya"],["يَشْعُرُونَ","mereka (tidak) menyedarinya"]]],"1928":["(Kemudian Allah menghinakan mereka di hari kiamat) membuat mereka hina (dan berfirman)-lah Allah kepada mereka melalui lisan malaikat-Nya dengan nada mengejek (\"Di manakah sekutu-sekutu-Ku itu?) yang menurut dugaan kalian itu (yang karena membelanya kalian selalu memusuhi) menentang kaum mukminin (tentang perihal mereka.\") mengenai perkara mereka. (Berkatalah) artinya nanti akan berkata/menjawab (orang-orang yang diberi ilmu) yaitu para nabi dan orang-orang mukmin (\"Sesungguhnya kehinaan dan azab hari ini ditimpakan atas orang-orang yang kafir.\") para nabi dan orang-orang mukmin mengatakan demikian sebagai ejekan yang ditujukan kepada orang-orang kafir.",[["ثُمَّ","Kemudian"],["يَوْمَ","(pada) hari itu"],["ٱلْقِيَـٰمَةِ","Kiamat"],["يُخْزِيهِمْ","Dia akan memalukan mereka"],["وَيَقُولُ","dan katakan"],["أَيْنَ","di mana"],["شُرَكَآءِىَ","(adalah) rakan kongsi aku"],["ٱلَّذِينَ","mereka (untuk) siapa"],["كُنتُمْ","kamu pernah (untuk)"],["تُشَـٰٓقُّونَ","menentang"],["فِيهِمْ ۚ","[pada mereka]"],["قَالَ","Akan berkata"],["ٱلَّذِينَ","orang yang"],["أُوتُوا۟","telah diberikan"],["ٱلْعِلْمَ","pengetahuan itu"],["إِنَّ","Sesungguhnya"],["ٱلْخِزْىَ","aib itu"],["ٱلْيَوْمَ","Hari ini"],["وَٱلسُّوٓءَ","dan jahat"],["عَلَى","(ada) atas"],["ٱلْكَـٰفِرِينَ","orang kafir"]]],"1929":["(Orang-orang yang dimatikan) dapat dibaca tatawaffaahum dan yatawaffaahum (oleh para malaikat dalam keadaan berbuat zalim kepada diri mereka sendiri) karena melakukan kekufuran (lalu mereka menyerahkan diri) mereka tunduk dan berserah diri ketika maut menjelang mereka seraya berkata (\"Kami sekali-kali tidak ada mengerjakan suatu kejahatan pun.\") yaitu perbuatan musyrik. Maka para malaikat berkata kepada mereka (\"Ada, sesungguhnya Allah Maha Mengetahui apa yang telah kalian kerjakan.\") oleh sebab itu Dia membalaskannya kepada diri kalian.",[["ٱلَّذِينَ","Mereka yang"],["تَتَوَفَّىٰهُمُ","bawa mereka dalam kematian"],["ٱلْمَلَـٰٓئِكَةُ","para Malaikat"],["ظَالِمِىٓ","(sementara) menzalimi"],["أَنفُسِهِمْ ۖ","diri mereka"],["فَأَلْقَوُا۟","maka mereka akan menawarkan"],["ٱلسَّلَمَ","penyerahan itu"],["مَا","Tidak"],["كُنَّا","kami"],["نَعْمَلُ","melakukan"],["مِن","sebarang"],["سُوٓءٍۭ ۚ","jahat"],["بَلَىٰٓ","Bahkan"],["إِنَّ","sesungguhnya"],["ٱللَّهَ","Allah"],["عَلِيمٌۢ","Maha Mengetahui"],["بِمَا","tentang apa"],["كُنتُمْ","kamu pernah (untuk)"],["تَعْمَلُونَ","lakukan"]]],"1930":["Lalu dikatakan kepada mereka (\"Maka masukilah pintu-pintu neraka Jahanam, kalian kekal di dalamnya. Maka amat buruklah tempat) menetap (orang-orang yang menyombongkan diri itu.\")",[["فَٱدْخُلُوٓا۟","Jadi masuk"],["أَبْوَٰبَ","(the) pintu gerbang"],["جَهَنَّمَ","(dari) Neraka"],["خَـٰلِدِينَ","(untuk) kekal selama-lamanya"],["فِيهَا ۖ","di dalamnya"],["فَلَبِئْسَ","Pasti, celaka"],["مَثْوَى","(adalah) tempat tinggal"],["ٱلْمُتَكَبِّرِينَ","(dari) orang yang sombong"]]],"1931":["(Dan dikatakan kepada orang-orang yang bertakwa) yang memelihara diri dari kemusyrikan (\"Apakah yang telah diturunkan oleh Rabb kalian?\" Mereka menjawab, \"Kebaikan.\" Orang-orang yang telah berbuat baik) karena beriman (di dunia ini mendapat pembalasan yang baik) yakni kehidupan yang baik. (Dan sesungguhnya kampung akhirat) yakni surga (lebih baik) daripada kehidupan dunia berikut semua isinya. Lalu Allah berfirman di dalam kampung akhirat itu. (Dan sebaik-baik tempat bagi orang-orang yang bertakwa) adalah surga itu.",[["۞ وَقِيلَ","Dan ia akan dikatakan"],["لِلَّذِينَ","kepada mereka yang"],["ٱتَّقَوْا۟","takut kepada Allah"],["مَاذَآ","Apa"],["أَنزَلَ","telahkah Tuhanmu menurunkan"],["رَبُّكُمْ ۚ","telahkah Tuhanmu menurunkan"],["قَالُوا۟","Mereka akan berkata"],["خَيْرًۭا ۗ","bagus"],["لِّلَّذِينَ","Bagi mereka yang"],["أَحْسَنُوا۟","berbuat baik"],["فِى","dalam"],["هَـٰذِهِ","ini"],["ٱلدُّنْيَا","dunia"],["حَسَنَةٌۭ ۚ","(adalah) yang baik"],["وَلَدَارُ","dan rumah"],["ٱلْـَٔاخِرَةِ","akhirat"],["خَيْرٌۭ ۚ","(lebih) baik"],["وَلَنِعْمَ","Dan pastinya sangat baik"],["دَارُ","(ialah) rumah"],["ٱلْمُتَّقِينَ","(dari) orang-orang yang soleh"]]],"1932":["(Yaitu surga Adn) sebagai tempat tinggal. Lafal jannaatu Adn adalah mubtada sedangkan khabarnya ialah (mereka masuk ke dalamnya; mengalir di bawahnya sungai-sungai, di dalam surga itu mereka mendapat segala apa yang mereka kehendaki. Demikianlah) pembalasan itu (Allah memberi balasan kepada orang-orang yang bertakwa.)",[["جَنَّـٰتُ","Taman-taman"],["عَدْنٍۢ","(dari) Eden"],["يَدْخُلُونَهَا","yang akan mereka masuki"],["تَجْرِى","mengalir"],["مِن","daripada"],["تَحْتِهَا","di bawah mereka"],["ٱلْأَنْهَـٰرُ ۖ","sungai-sungai"],["لَهُمْ","Untuk mereka"],["فِيهَا","di dalamnya"],["مَا","(akan) apa sahaja"],["يَشَآءُونَ ۚ","mereka mahu"],["كَذَٰلِكَ","Demikianlah"],["يَجْزِى","Allah beri ganjaran"],["ٱللَّهُ","Allah beri ganjaran"],["ٱلْمُتَّقِينَ","orang yang soleh"]]],"1933":["(Yaitu orang-orang) lafal alladziina di sini menjadi na`at atau sifat (yang diwafatkan oleh para malaikat dalam keadaan baik) yakni suci dari kekafiran (dengan mengatakan) para malaikat itu berkata kepada mereka ketika akan diwafatkan (\"Salaamun `alaikum.\") dan dikatakan pula kepada mereka kelak di hari akhirat (\"Masuklah kalian ke dalam surga itu disebabkan apa yang telah kalian kerjakan.\")",[["ٱلَّذِينَ","Mereka yang"],["تَتَوَفَّىٰهُمُ","bawa mereka dalam kematian"],["ٱلْمَلَـٰٓئِكَةُ","para Malaikat"],["طَيِّبِينَ ۙ","(apabila mereka) suci"],["يَقُولُونَ","berkata"],["سَلَـٰمٌ","Damai"],["عَلَيْكُمُ","(berada) atas kamu"],["ٱدْخُلُوا۟","Masuk"],["ٱلْجَنَّةَ","Syurga"],["بِمَا","bagi apa"],["كُنتُمْ","kamu pernah (untuk)"],["تَعْمَلُونَ","lakukan"]]],"1934":["(Tidak ada) tiada (yang ditunggu-tunggu) oleh orang-orang kafir (selain datang kepada mereka) dapat dibaca ta'tiyahum atau ya'tiyahum (para malaikat) untuk mencabut nyawa mereka (atau datangnya perintah Rabbmu) yakni azab atau hari kiamat yang terdapat di dalamnya azab buat mereka. (Demikianlah) seperti apa yang telah dilakukan oleh mereka (telah dilakukan pula oleh orang-orang sebelum mereka) daripada umat-umat terdahulu yang mendustakan rasul-rasul mereka kemudian mereka dibinasakan. (Dan sekali-kali Allah tidak menganiaya mereka) dengan membinasakan mereka tanpa dosa (akan tetapi merekalah yang selalu menganiaya diri mereka sendiri) karena melakukan kekafiran.",[["هَلْ","buat"],["يَنظُرُونَ","mereka menunggu"],["إِلَّآ","kecuali"],["أَن","bahawa"],["تَأْتِيَهُمُ","(hendaklah) datang kepada mereka"],["ٱلْمَلَـٰٓئِكَةُ","para Malaikat"],["أَوْ","atau"],["يَأْتِىَ","(harus) datang"],["أَمْرُ","(the) Perintah"],["رَبِّكَ ۚ","Tuhanmu"],["كَذَٰلِكَ","Demikianlah"],["فَعَلَ","lakukan"],["ٱلَّذِينَ","orang yang"],["مِن","(ada) sebelum mereka"],["قَبْلِهِمْ ۚ","(ada) sebelum mereka"],["وَمَا","Dan tidak"],["ظَلَمَهُمُ","menganiaya mereka"],["ٱللَّهُ","Allah"],["وَلَـٰكِن","tetapi"],["كَانُوٓا۟","mereka adalah"],["أَنفُسَهُمْ","diri mereka"],["يَظْلِمُونَ","menzalimi"]]],"1935":["(Maka mereka ditimpa oleh akibat kejahatan perbuatan mereka sendiri) yakni pembalasannya (dan dibinasakanlah) diazablah (mereka oleh apa yang selalu mereka perolok-olokkan) yaitu azab.",[["فَأَصَابَهُمْ","Kemudian memukul mereka"],["سَيِّـَٔاتُ","(yang) jahat (hasil)"],["مَا","apa"],["عَمِلُوا۟","mereka lakukan"],["وَحَاقَ","dan dikelilingi"],["بِهِم","mereka"],["مَّا","apa"],["كَانُوا۟","mereka pernah (untuk)"],["بِهِۦ","[daripadanya]"],["يَسْتَهْزِءُونَ","mengejek"]]],"1936":["(Dan berkatalah orang-orang musyrik) dari kalangan penduduk Mekah (\"Jika Allah menghendaki niscaya kami tidak akan menyembah sesuatu apa pun selain Dia, baik kami maupun bapak-bapak kami, dan tidak pula kami mengharamkan sesuatu pun tanda izin-Nya) yaitu mengharamkan bahirah dan saibah. Ini berarti bahwa kemusyrikan kami dan pengharaman kami ini berdasarkan kehendak-Nya karena Dia rela terhadapnya. Maka Allah berfirman menyanggah mereka: (Demikianlah yang diperbuat oleh orang-orang sebelum mereka) artinya mereka telah mendustakan rasul-rasul mereka tentang apa yang didatangkan oleh para rasul itu (maka tidak ada) (kewajiban atas para rasul selain dari menyampaikan amanat Allah dengan terang) dan mereka tidak berkewajiban untuk memberi hidayah.",[["وَقَالَ","Dan berkata"],["ٱلَّذِينَ","orang yang"],["أَشْرَكُوا۟","mempersekutukan (dengan Allah)"],["لَوْ","Jika"],["شَآءَ","Allah (telah) menghendaki"],["ٱللَّهُ","Allah (telah) menghendaki"],["مَا","tidak"],["عَبَدْنَا","kami (akan) menyembah"],["مِن","selain Dia"],["دُونِهِۦ","selain Dia"],["مِن","sebarang"],["شَىْءٍۢ","perkara"],["نَّحْنُ","kita"],["وَلَآ","dan bukan"],["ءَابَآؤُنَا","nenek moyang kita"],["وَلَا","dan bukan"],["حَرَّمْنَا","kami (akan) melarang"],["مِن","selain Dia"],["دُونِهِۦ","selain Dia"],["مِن","sesuatu"],["شَىْءٍۢ ۚ","sesuatu"],["كَذَٰلِكَ","Demikianlah"],["فَعَلَ","lakukan"],["ٱلَّذِينَ","orang yang"],["مِن","(ada) sebelum mereka"],["قَبْلِهِمْ ۚ","(ada) sebelum mereka"],["فَهَلْ","Kemudian adakah (ada)"],["عَلَى","pada"],["ٱلرُّسُلِ","para rasul"],["إِلَّا","kecuali"],["ٱلْبَلَـٰغُ","pengangkutan itu"],["ٱلْمُبِينُ","yang nyata"]]],"1937":["(Dan sesungguhnya Kami telah mengutus rasul pada tiap-tiap umat) seperti Aku mengutus kamu kepada mereka (untuk) artinya untuk menyerukan ('Sembahlah Allah) esakanlah Dia (dan jauhilah thaghut,') berhala-berhala itu janganlah kalian sembah (maka di antara umat itu ada orang-orang yang diberi petunjuk oleh Allah) lalu ia beriman (dan ada pula di antaranya orang-orang yang telah pasti) telah ditentukan (kesesatan baginya) menurut ilmu Allah, sehingga ia tidak beriman. (Maka berjalanlah kalian) hai orang-orang kafir Mekah (di muka bumi dan perhatikanlah bagaimana kesudahan orang-orang yang mendustakan) rasul-rasul mereka, yakni kebinasaan yang akan mereka alami nanti.",[["وَلَقَدْ","Dan sungguh"],["بَعَثْنَا","Kami utus"],["فِى","ke dalam"],["كُلِّ","setiap"],["أُمَّةٍۢ","bangsa"],["رَّسُولًا","seorang Rasul"],["أَنِ","bahawa"],["ٱعْبُدُوا۟","Ibadah"],["ٱللَّهَ","Allah"],["وَٱجْتَنِبُوا۟","dan elakkan"],["ٱلطَّـٰغُوتَ ۖ","dewa-dewa palsu"],["فَمِنْهُم","Kemudian di antara mereka"],["مَّنْ","(adalah beberapa) siapa"],["هَدَى","Allah beri petunjuk"],["ٱللَّهُ","Allah beri petunjuk"],["وَمِنْهُم","dan antara mereka"],["مَّنْ","(adalah) beberapa"],["حَقَّتْ","telah dibenarkan"],["عَلَيْهِ","ke atas mereka"],["ٱلضَّلَـٰلَةُ ۚ","yang sesat"],["فَسِيرُوا۟","Jadi melancong"],["فِى","dalam"],["ٱلْأَرْضِ","bumi"],["فَٱنظُرُوا۟","dan lihat"],["كَيْفَ","bagaimana"],["كَانَ","adalah"],["عَـٰقِبَةُ","penghujungnya"],["ٱلْمُكَذِّبِينَ","(dari) orang-orang yang mendustakan"]]],"1938":["(Jika kamu sangat mengharapkan) hai Muhammad (agar mereka dapat petunjuk) sedangkan Allah telah menyesatkan mereka niscaya kamu tidak akan mampu melakukan hal itu (maka sesungguhnya Allah tiada memberi petunjuk kepada orang yang disesatkan-Nya) dapat dibaca yudhillu dan yudhallu, artinya orang yang dikehendaki-Nya sesat (dan sekali-kali mereka tiada mempunyai penolong\") yang dapat mencegah azab Allah atas diri mereka.",[["إِن","Jika"],["تَحْرِصْ","kamu inginkan"],["عَلَىٰ","[untuk]"],["هُدَىٰهُمْ","bimbingan mereka"],["فَإِنَّ","maka sesungguhnya"],["ٱللَّهَ","Allah"],["لَا","(akan) tidak"],["يَهْدِى","panduan"],["مَن","yang"],["يُضِلُّ ۖ","Dia biarkan sesat"],["وَمَا","dan bukan (adalah)"],["لَهُم","bagi mereka"],["مِّن","sebarang"],["نَّـٰصِرِينَ","pembantu"]]],"1939":["(Mereka bersumpah dengan nama Allah dengan sumpahnya yang sungguh-sungguh) artinya mereka bersumpah dengan sungguh-sungguh (\"Allah tidak akan membangkitkan orang yang mati.\") maka Allah berfirman menyanggah mereka (Tidak demikian, bahkan) Allah pasti akan membangkitkan mereka (sebagai suatu janji yang benar dari Allah) lafal wa`dan dan haqqan kedua-duanya adalah bentuk mashdar yang fungsinya mengukuhkan makna fi`ilnya dan dinashabkan oleh fi`ilnya yang keberadaannya diperkirakan; artinya Allah sungguh telah menjanjikan hal tersebut dan Allah akan membuktikannya dengan benar (akan tetapi kebanyakan manusia) penduduk Mekah (tiada mengetahui) hal tersebut.",[["وَأَقْسَمُوا۟","Dan mereka bersumpah"],["بِٱللَّهِ","oleh Allah"],["جَهْدَ","terkuat"],["أَيْمَـٰنِهِمْ ۙ","(dari) sumpah mereka"],["لَا","Allah tidak akan membangkitkan"],["يَبْعَثُ","Allah tidak akan membangkitkan"],["ٱللَّهُ","Allah tidak akan membangkitkan"],["مَن","(satu) siapa"],["يَمُوتُ ۚ","mati"],["بَلَىٰ","Bahkan"],["وَعْدًا","(ia) janji"],["عَلَيْهِ","atas Dia"],["حَقًّۭا","(dalam) kebenaran"],["وَلَـٰكِنَّ","tetapi"],["أَكْثَرَ","kebanyakannya"],["ٱلنَّاسِ","(dari) manusia"],["لَا","jangan"],["يَعْلَمُونَ","mengetahui"]]],"1940":["(Agar Allah menjelaskan) lafal liyubayyina ini berta`lluq kepada lafal yab`atsuhum yang keberadaannya diperkirakan (kepada mereka apa yang mereka perselisihkan itu) bersama dengan orang-orang mukmin (tentangnya) tentang masalah agama; melalui cara mengazab orang-orang kafir dan memberi pahala orang-orang mukmin (agar orang-orang kafir itu mengetahui bahwasanya mereka adalah orang-orang yang berdusta) disebabkan mereka mengingkari adanya hari berbangkit.",[["لِيُبَيِّنَ","Yang akan Dia jelaskan"],["لَهُمُ","kepada mereka"],["ٱلَّذِى","bahawa"],["يَخْتَلِفُونَ","mereka berbeza"],["فِيهِ","di mana"],["وَلِيَعْلَمَ","dan itu mungkin tahu"],["ٱلَّذِينَ","orang yang"],["كَفَرُوٓا۟","kufur"],["أَنَّهُمْ","bahawa mereka"],["كَانُوا۟","adalah"],["كَـٰذِبِينَ","pembohong"]]],"1941":["(Sesungguhnya perkataan Kami terhadap sesuatu apabila Kami menghendakinya) artinya Kami berkehendak untuk mengadakannya. Lafal qaulunaa adalah mubtada sedangkan khabarnya ialah (Kami hanya mengatakan kepadanya, \"Jadilah,\" maka jadilah ia) artinya, maka sesuatu yang dikehendaki-Nya itu ada seketika. Menurut qiraat lafal fayakuunu dibaca nashab sehingga menjadi fayakuuna karena diathafkan kepada lafal naquula. Ayat ini menunjukkan makna menetapkan kekuasaan Allah di dalam membangkitkan makhluk.",[["إِنَّمَا","Hanya"],["قَوْلُنَا","Firman Kami"],["لِشَىْءٍ","kepada sesuatu perkara"],["إِذَآ","apabila"],["أَرَدْنَـٰهُ","Kami berniat"],["أَن","(ialah) itu"],["نَّقُولَ","Kami berkata"],["لَهُۥ","kepadanya"],["كُن","Jadilah"],["فَيَكُونُ","dan ia adalah"]]],"1942":["(Dan orang-orang yang berhijrah karena Allah) untuk menegakkan agama-Nya (sesudah mereka dianiaya) mengalami penganiayaan dari penduduk kota Mekah yang dimaksud adalah Nabi saw. dan para sahabatnya (pasti Kami akan memberikan tempat buat mereka) menempatkan mereka (di dunia ini) pada suatu tempat tinggal (yang baik) yakni kota Madinah. (Dan sesungguhnya pahala di akhirat) yaitu surga itu (adalah lebih besar) lebih agung (kalau mereka mengetahui) maksudnya kalau orang-orang kafir itu atau orang-orang yang tidak ikut hijrah benar-benar mengetahui tentang kemuliaan yang diperoleh oleh orang-orang yang berhijrah, niscaya mereka akan ikut hijrah bersama dengan orang-orang yang berhijrah.",[["وَٱلَّذِينَ","Dan orang yang"],["هَاجَرُوا۟","berhijrah"],["فِى","dalam (jalan)"],["ٱللَّهِ","(milik) Allah"],["مِنۢ","selepas"],["بَعْدِ","selepas"],["مَا","[apa]"],["ظُلِمُوا۟","mereka dizalimi"],["لَنُبَوِّئَنَّهُمْ","sesungguhnya Kami akan memberikan kedudukan kepada mereka"],["فِى","dalam"],["ٱلدُّنْيَا","dunia"],["حَسَنَةًۭ ۖ","kebaikan"],["وَلَأَجْرُ","tetapi yang pasti pahalanya"],["ٱلْـَٔاخِرَةِ","(dari) Akhirat"],["أَكْبَرُ ۚ","(adalah) lebih besar"],["لَوْ","jika"],["كَانُوا۟","mereka"],["يَعْلَمُونَ","mengetahui"]]],"1943":["Mereka adalah (orang-orang yang sabar) di dalam menghadapi penganiayaan kaum musyrikin dan berhijrah demi untuk memenangkan agama Islam (dan hanya kepada Rabb saja mereka bertawakal) maka Allah pasti memberi mereka rezeki dari jalan yang tiada mereka perhitungkan sebelumnya.",[["ٱلَّذِينَ","Orang yang"],["صَبَرُوا۟","(adalah) sabar"],["وَعَلَىٰ","dan seterusnya"],["رَبِّهِمْ","Tuhan mereka"],["يَتَوَكَّلُونَ","mereka meletakkan kepercayaan mereka"]]],"1944":["(Dan Kami tidak mengutus sebelum kamu kecuali orang-orang lelaki yang Kami beri wahyu kepada mereka) bukannya para malaikat (maka bertanyalah kepada orang yang mempunyai pengetahuan) yakni para ulama yang ahli dalam kitab Taurat dan kitab Injil (jika kalian tidak mengetahui) hal tersebut, mereka pasti mengetahuinya karena kepercayaan kalian kepada mereka lebih dekat daripada kepercayaan kalian terhadap Nabi Muhammad saw.",[["وَمَآ","Dan tidak"],["أَرْسَلْنَا","Kami utus"],["مِن","sebelum kamu"],["قَبْلِكَ","sebelum kamu"],["إِلَّا","kecuali"],["رِجَالًۭا","lelaki"],["نُّوحِىٓ","Kami mendedahkan"],["إِلَيْهِمْ ۚ","kepada mereka"],["فَسْـَٔلُوٓا۟","jadi tanya"],["أَهْلَ","kaum"],["ٱلذِّكْرِ","(dari) Peringatan"],["إِن","jika"],["كُنتُمْ","kamu"],["لَا","jangan"],["تَعْلَمُونَ","mengetahui"]]],"1945":["(Dengan membawa keterangan-keterangan) lafal ini berta`alluq kepada fi`il yang tidak disebutkan; artinya Kami utus mereka dengan membawa hujah-hujah yang jelas (dan kitab-kitab) yakni kitab-kitab suci. (Dan Kami turunkan kepadamu Adz-Dzikr) yakni Alquran (agar kamu menerangkan kepada umat manusia apa yang diturunkan kepada mereka) yang di dalamnya dibedakan antara halal dan haram (dan supaya mereka memikirkan) tentang hal tersebut kemudian mereka mengambil pelajaran daripadanya.",[["بِٱلْبَيِّنَـٰتِ","Dengan bukti yang jelas"],["وَٱلزُّبُرِ ۗ","dan Kitab-kitab"],["وَأَنزَلْنَآ","Dan Kami turunkan"],["إِلَيْكَ","kepada kamu"],["ٱلذِّكْرَ","Zikir itu"],["لِتُبَيِّنَ","supaya kamu jelaskan"],["لِلنَّاسِ","kepada umat manusia"],["مَا","apa"],["نُزِّلَ","telah diturunkan"],["إِلَيْهِمْ","kepada mereka"],["وَلَعَلَّهُمْ","dan supaya mereka boleh"],["يَتَفَكَّرُونَ","merenung"]]],"1946":["(Maka apakah merasa aman orang-orang yang membuat makar) tipu daya (yang jahat itu) terhadap diri Nabi saw. sewaktu mereka berunding di Darun Nadwah untuk mengikatnya, atau membunuhnya atau mengusirnya sebagaimana penjelasan yang telah dikemukakan dalam surah Al-Anfal (dari bencana ditenggelamkannya bumi oleh Allah bersama mereka) seperti apa yang terjadi terhadap diri Qarun (atau datangnya azab kepada mereka dari tempat yang tidak mereka sadari) dari arah yang tidak pernah mereka duga sebelumnya; dan sungguh mereka benar-benar dibinasakan dalam perang Badar, hal tersebut tidak masuk ke dalam perhitungan mereka sebelumnya.",[["أَفَأَمِنَ","Kemudian berasa selamat"],["ٱلَّذِينَ","orang yang"],["مَكَرُوا۟","diplot"],["ٱلسَّيِّـَٔاتِ","perbuatan jahat itu"],["أَن","bahawa"],["يَخْسِفَ","Allah akan gua"],["ٱللَّهُ","Allah akan gua"],["بِهِمُ","bersama mereka"],["ٱلْأَرْضَ","bumi"],["أَوْ","atau"],["يَأْتِيَهُمُ","akan datang kepada mereka"],["ٱلْعَذَابُ","azab"],["مِنْ","daripada"],["حَيْثُ","di mana"],["لَا","tidak"],["يَشْعُرُونَ","mereka rasa"]]],"1947":["(Atau Allah mengazab mereka di waktu mereka dalam perjalanan) sewaktu mereka sedang dalam perjalanan untuk berniaga (maka sekali-kali mereka tidak dapat menolak) azab itu.",[["أَوْ","Atau"],["يَأْخُذَهُمْ","supaya Dia dapat menangkap mereka"],["فِى","dalam"],["تَقَلُّبِهِمْ","mereka pergi dan balik"],["فَمَا","maka tidak"],["هُم","mereka"],["بِمُعْجِزِينَ","akan dapat melarikan diri"]]],"1948":["(Atau Allah mengazab mereka secara berangsur-angsur) sedikit demi sedikit hingga semuanya binasa; lafal takhawwufin menjadi hal dari fa`il atau dari maf'ul (maka sesungguhnya Rabb kalian adalah Maha Pengasih lagi Maha Penyayang) karena Dia tidak menyegerakan siksa-Nya terhadap mereka.",[["أَوْ","Atau"],["يَأْخُذَهُمْ","supaya Dia dapat menangkap mereka"],["عَلَىٰ","dengan"],["تَخَوُّفٍۢ","pembaziran secara beransur-ansur"],["فَإِنَّ","Tetapi sesungguhnya"],["رَبَّكُمْ","Tuhanmu"],["لَرَءُوفٌۭ","(adalah) sesungguhnya penuh dengan kebaikan"],["رَّحِيمٌ","Maha Mengasihani"]]],"1949":["(Dan apakah mereka tidak memperhatikan segala sesuatu yang telah diciptakan Allah) yang ia mempunyai bayangan, seperti pohon dan gunung (yang berbolak-balik) condong ke sana dan condong ke mari (bayangannya ke kanan dan ke kiri) lafal asysyamaail adalah bentuk jamak dari lafal syimaal; artinya bayangan itu condong ke arah dua sisinya, pertama di permulaan siang hari dan yang kedua pada sore harinya (dalam keadaan sujud kepada Allah) lafal sujjadan menjadi hal; artinya mereka lakukan demikian dalam keadaan tunduk kepada Allah sesuai dengan karakter mereka (sedangkan mereka) yakni bayangan-bayangan itu (berendah diri?) merendahkan dirinya terhadap Allah; bayangan-bayangan tersebut diungkapkan seolah-olah mereka berakal.",[["أَوَلَمْ","belum"],["يَرَوْا۟","mereka nampak"],["إِلَىٰ","[ke arah]"],["مَا","apa"],["خَلَقَ","Allah telah menciptakan"],["ٱللَّهُ","Allah telah menciptakan"],["مِن","daripada"],["شَىْءٍۢ","sesuatu perkara"],["يَتَفَيَّؤُا۟","condong"],["ظِلَـٰلُهُۥ","bayang-bayang mereka"],["عَنِ","kepada"],["ٱلْيَمِينِ","yang betul"],["وَٱلشَّمَآئِلِ","dan ke kiri"],["سُجَّدًۭا","sujud"],["لِّلَّهِ","kepada Allah"],["وَهُمْ","sedangkan mereka"],["دَٰخِرُونَ","(adalah) rendah hati"]]],"1950":["(Dan kepada Allah sajalah bersujud segala apa yang berada di langit dan semua makhluk yang melata di bumi) artinya semua makhluk itu tunduk kepada-Nya. Sesuai dengan karakternya; kemudian mereka diungkapkan dalam bentuk yang tidak berakal, mengingat mereka yang tidak berakal jumlahnya lebih banyak (dan juga para malaikat) mereka disebutkan secara khusus di sini karena mengingat keutamaan yang mereka miliki (sedangkan para malaikat itu tidak menyombongkan diri) tidak pernah sekejap pun meninggalkan beribadah kepada-Nya.",[["وَلِلَّهِ","Dan kepada Allah"],["يَسْجُدُ","sujud"],["مَا","apa sahaja"],["فِى","(berada) dalam"],["ٱلسَّمَـٰوَٰتِ","langit"],["وَمَا","dan apa sahaja"],["فِى","(berada) dalam"],["ٱلْأَرْضِ","bumi"],["مِن","daripada"],["دَآبَّةٍۢ","makhluk bergerak"],["وَٱلْمَلَـٰٓئِكَةُ","dan para Malaikat"],["وَهُمْ","dan mereka"],["لَا","(adalah) tidak"],["يَسْتَكْبِرُونَ","sombong"]]],"1951":["(Mereka takut) yakni para malaikat; lafal ini menjadi hal dari dhamir yang terkandung di dalam lafal yastakbiruuna (kepada Rabb mereka yang berkuasa atas mereka) lafal fauqahum menjadi hal daripada dhamir hum; artinya yang menguasai mereka dengan keperkasaan-Nya (dan melaksanakan apa yang diperintahkan kepada mereka) untuk melakukannya.",[["يَخَافُونَ","Mereka takut"],["رَبَّهُم","Tuhan mereka"],["مِّن","di atas mereka"],["فَوْقِهِمْ","di atas mereka"],["وَيَفْعَلُونَ","dan mereka lakukan"],["مَا","apa"],["يُؤْمَرُونَ ۩","mereka diperintah"]]],"1952":["(Allah berfirman, \"Janganlah kalian menyembah dua tuhan) lafal istnaini berfungsi sebagai taukid atau pengukuhan makna (Sesungguhnya Dialah Tuhan Yang Maha Esa) disebutkannya lafal ilaahun dan waahidun untuk menetapkan sifat uluhiah dan sifat wahdaniah Allah (maka hendaklah kepada-Ku saja kalian takut.\") janganlah kalian takut kepada selain Aku. Di dalam ungkapan ini terkandung pengertian iltifat dari dhamir gaib.",[["۞ وَقَالَ","Dan Allah telah berfirman"],["ٱللَّهُ","Dan Allah telah berfirman"],["لَا","Jangan"],["تَتَّخِذُوٓا۟","ambil"],["إِلَـٰهَيْنِ","[dua] tuhan"],["ٱثْنَيْنِ ۖ","dua"],["إِنَّمَا","sahaja"],["هُوَ","Dia"],["إِلَـٰهٌۭ","(ialah) Tuhan"],["وَٰحِدٌۭ ۖ","satu"],["فَإِيَّـٰىَ","jadi Aku Sendiri"],["فَٱرْهَبُونِ","kamu takut [Aku]"]]],"1953":["(Dan kepunyaan-Nyalah segala apa yang ada di langit dan di bumi) sebagai milik, makhluk dan hamba-Nya (dan untuk-Nyalah agama itu) ketaatan itu (selama-lamanya) untuk selamanya; lafal waashiban menjadi hal dari lafal ad-diin, sedangkan sebagai `amilnya adalah makna zharaf. (Maka mengapa kalian bertakwa kepada selain Allah?) sedangkan Dia adalah Tuhan yang sebenarnya, dan tiada Tuhan selain-Nya. Istifham atau kata tanya di sini mengandung pengertian ingkar dan celaan.",[["وَلَهُۥ","Dan kepunyaan-Nya"],["مَا","apa sahaja"],["فِى","(berada) dalam"],["ٱلسَّمَـٰوَٰتِ","langit"],["وَٱلْأَرْضِ","dan bumi"],["وَلَهُ","dan kepada-Nya"],["ٱلدِّينُ","(adalah kerana) ibadat itu"],["وَاصِبًا ۚ","secara berterusan"],["أَفَغَيْرَ","Kemudian adakah ia lain (selain)"],["ٱللَّهِ","Allah"],["تَتَّقُونَ","kamu takut"]]],"1954":["(Dan apa saja nikmat yang ada pada kalian maka dari Allahlah datangnya) tiada yang dapat mendatangkannya selain Dia. Huruf maa di sini adalah syarthiyah atau maushulah (dan bila kalian ditimpa) tertimpa (kemudaratan) seperti kemiskinan dan sakit (maka hanya kepada-Nyalah kalian meminta pertolongan) mengangkat suara kalian untuk meminta pertolongan seraya berdoa kepada-Nya, dan niscaya kalian tidak akan meminta kepada selain-Nya.",[["وَمَا","Dan apa sahaja"],["بِكُم","kamu ada"],["مِّن","daripada"],["نِّعْمَةٍۢ","nikmat"],["فَمِنَ","(adalah) daripada"],["ٱللَّهِ ۖ","Allah"],["ثُمَّ","Kemudian"],["إِذَا","apabila"],["مَسَّكُمُ","menyentuh kamu"],["ٱلضُّرُّ","kesusahan itu"],["فَإِلَيْهِ","kemudian kepada-Nya"],["تَجْـَٔرُونَ","kamu menangis minta tolong"]]],"1955":["(Kemudian apabila Dia telah menghilangkan kemudaratan itu daripada kalian, tiba-tiba sebagian daripada kalian mempersekutukan Rabbnya dengan yang lain).",[["ثُمَّ","Kemudian"],["إِذَا","apabila"],["كَشَفَ","Dia mengeluarkan"],["ٱلضُّرَّ","kesusahan itu"],["عَنكُمْ","daripada kamu"],["إِذَا","lihatlah"],["فَرِيقٌۭ","Satu kumpulan"],["مِّنكُم","daripada kamu"],["بِرَبِّهِمْ","dengan Tuhan mereka"],["يُشْرِكُونَ","mengaitkan orang lain"]]],"1956":["(Biarkanlah mereka mengingkari apa yang telah Kami berikan kepada mereka) yaitu nikmat (maka bersenang-senanglah kalian) sebab kesepakatan kalian untuk menyembah berhala-berhala. Amar atau perintah di sini mengandung pengertian ancaman. (Kelak kalian akan mengetahui) akibat daripada hal tersebut.",[["لِيَكْفُرُوا۟","Sehingga menafikan"],["بِمَآ","itu yang"],["ءَاتَيْنَـٰهُمْ ۚ","Kami telah memberi mereka"],["فَتَمَتَّعُوا۟ ۖ","Kemudian berseronoklah"],["فَسَوْفَ","tidak lama lagi"],["تَعْلَمُونَ","kamu akan tahu"]]],"1957":["(Dan mereka menyediakan) yakni orang-orang musyrik itu (untuk apa-apa yang mereka tiada mengetahui) bahwa hal itu mendatangkan mudarat dan tidak bermanfaat sama sekali; yang dimaksud adalah untuk berhala-berhala (satu bagian dari rezeki yang telah Kami berikan kepada mereka) berupa ladang dan ternak, yaitu melalui perkataan mereka, ini adalah untuk Allah dan ini adalah untuk sekutu-sekutu kami. (Demi Allah sesungguhnya kalian akan ditanya) dengan pertanyaan yang bernada mencela; di dalam ungkapan ini iltifat dari ghaibah (tentang apa yang telah kalian ada-adakan) terhadap Allah di mana kalian telah mengatakan bahwa Allah telah memerintahkan kalian untuk berbuat hal itu.",[["وَيَجْعَلُونَ","Dan mereka menugaskan"],["لِمَا","ke apa"],["لَا","tidak"],["يَعْلَمُونَ","mereka tahu"],["نَصِيبًۭا","sebahagian"],["مِّمَّا","tentang apa"],["رَزَقْنَـٰهُمْ ۗ","Kami rezekikan kepada mereka"],["تَٱللَّهِ","Demi Allah"],["لَتُسْـَٔلُنَّ","nescaya kamu akan ditanya"],["عَمَّا","tentang apa"],["كُنتُمْ","kamu pernah (untuk)"],["تَفْتَرُونَ","mencipta"]]],"1958":["(Dan mereka menetapkan bagi Allah anak-anak perempuan) yaitu melalui perkataan mereka, bahwa para malaikat itu adalah anak-anak perempuan Allah (Maha Suci Allah) ungkapan yang menyucikan-Nya daripada apa yang mereka duga (sedangkan untuk mereka sendiri apa yang mereka sukai) memilihnya, artinya anak-anak lelaki. Jumlah kalimat ini menjadi mahal rafa', atau menjadi mahal nashab dari fi'il yaj'aluuna. Artinya mereka menetapkan bagi Allah anak-anak perempuan yang mereka sendiri membencinya, sedangkan pada kenyataannya Dia Maha Suci dari mempunyai anak, kemudian mereka menetapkan untuk diri mereka sendiri anak-anak lelaki yang mereka pilih sendiri. Dengan demikian berarti mereka ingin merasa lebih unggul, sebagaimana yang telah dijelaskan oleh firman-Nya yang lain, yaitu, \"Tanyakanlah (hai Muhammad) kepada mereka (orang-orang kafir Mekah) apakah untuk Rabb kalian anak-anak perempuan dan untuk mereka anak-anak laki-laki.\" (Ash-Shaffat 149).",[["وَيَجْعَلُونَ","Dan mereka menugaskan"],["لِلَّهِ","kepada Allah"],["ٱلْبَنَـٰتِ","anak perempuan"],["سُبْحَـٰنَهُۥ ۙ","Maha Suci Dia"],["وَلَهُم","Dan untuk mereka"],["مَّا","(ialah) apa"],["يَشْتَهُونَ","mereka inginkan"]]],"1959":["(Dan apabila seorang dari mereka diberi kabar dengan kelahiran anak perempuan) ia mempunyai anak perempuan yang baru dilahirkan (maka jadilah) maka berubahlah (roman mukanya menjadi hitam) dengan perubahan yang menunjukkan kedukaan dan kesusahan (dan dia sangat marah) marah sekali, maka mengapa mereka menisbatkan anak-anak perempuan terhadap Allah swt.?",[["وَإِذَا","Dan apabila"],["بُشِّرَ","diberi khabar gembira"],["أَحَدُهُم","(kepada) salah seorang daripada mereka"],["بِٱلْأُنثَىٰ","seorang perempuan"],["ظَلَّ","berpusing"],["وَجْهُهُۥ","mukanya"],["مُسْوَدًّۭا","gelap"],["وَهُوَ","dan dia"],["كَظِيمٌۭ","menahan kesedihan"]]],"1960":["(Ia menyembunyikan dirinya) menghilang (dari orang banyak) dari pandangan kaumnya (disebabkan buruknya berita yang disampaikan kepadanya) karena ia takut akan mendapat celaan, sedangkan ia dalam keadaan bingung untuk melakukan tindakan selanjutnya sebagai pemecahannya. (Apakah dia akan memeliharanya) yakni membiarkannya tanpa dibunuh (dengan menanggung kehinaan) hina dan direndahkan (ataukah akan menguburkannya ke dalam tanah hidup-hidup) seumpamanya ia memendam anak perempuan itu ke dalam tanah. (Ketahuilah, alangkah buruknya) alangkah jeleknya (apa yang mereka tetapkan itu) keputusan mereka itu karena mereka telah menisbatkan kepada Tuhan yang menciptakan mereka mempunyai anak-anak perempuan padahal anak-anak perempuan itu kedudukannya di kalangan mereka serendah itu.",[["يَتَوَٰرَىٰ","Dia menyembunyikan dirinya"],["مِنَ","daripada"],["ٱلْقَوْمِ","manusia"],["مِن","(kerana) daripada"],["سُوٓءِ","yang jahat"],["مَا","tentang apa"],["بُشِّرَ","dia telah diberi khabar gembira"],["بِهِۦٓ ۚ","tentang"],["أَيُمْسِكُهُۥ","Patutkah dia menyimpannya"],["عَلَىٰ","dalam"],["هُونٍ","penghinaan"],["أَمْ","atau"],["يَدُسُّهُۥ","mengebumikannya"],["فِى","dalam"],["ٱلتُّرَابِ ۗ","habuk itu"],["أَلَا","Tidak dinafikan"],["سَآءَ","jahat"],["مَا","(ialah) apa"],["يَحْكُمُونَ","mereka membuat keputusan"]]],"1961":["(Bagi orang-orang yang tidak beriman kepada kehidupan akhirat) yaitu orang-orang kafir (ada perumpamaan yang buruk) sifat yang buruk, yaitu kebiasaan mereka mengubur hidup-hidup anak-anak perempuan padahal mereka membutuhkannya (dan bagi Allah ada perumpamaan yang maha tinggi) sifat yang maha tinggi, yaitu bahwasanya tidak ada Tuhan selain Dia (dan Dialah Yang Maha Perkasa) di dalam kerajaan-Nya (lagi Maha Bijaksana) di dalam mengatur makhluk-Nya.",[["لِلَّذِينَ","Bagi mereka yang"],["لَا","jangan"],["يُؤْمِنُونَ","beriman"],["بِٱلْـَٔاخِرَةِ","di akhirat"],["مَثَلُ","(adalah) suatu persamaan"],["ٱلسَّوْءِ ۖ","(dari) kejahatan"],["وَلِلَّهِ","dan untuk Allah"],["ٱلْمَثَلُ","(ialah) persamaan"],["ٱلْأَعْلَىٰ ۚ","yang Tertinggi"],["وَهُوَ","Dan Dia"],["ٱلْعَزِيزُ","(ialah) Yang Maha Perkasa"],["ٱلْحَكِيمُ","Maha Bijaksana"]]],"1962":["(Jika Allah menghukum manusia karena kezalimannya) disebabkan kedurhakaan-kedurhakaan mereka (niscaya tidak akan ditinggalkan-Nya padanya) yakni di muka bumi ini sesuatu pun (dari makhluk yang melata) makhluk yang hidup di permukaannya (tetapi Allah menangguhkan mereka sampai pada waktu yang ditentukan. Maka apabila telah tiba waktu yang ditentukan bagi mereka, tidaklah mereka dapat mengundurkan) waktunya (barang sesaat pun dan tidak pula mendahulukan) waktunya.",[["وَلَوْ","Dan jika"],["يُؤَاخِذُ","Allah akan merebut"],["ٱللَّهُ","Allah akan merebut"],["ٱلنَّاسَ","umat manusia"],["بِظُلْمِهِم","kerana kesalahan mereka"],["مَّا","tidak"],["تَرَكَ","Dia (akan) pergi"],["عَلَيْهَا","atasnya"],["مِن","sebarang"],["دَآبَّةٍۢ","makhluk bergerak"],["وَلَـٰكِن","tetapi"],["يُؤَخِّرُهُمْ","Dia menangguhkan mereka"],["إِلَىٰٓ","bagi"],["أَجَلٍۢ","satu istilah"],["مُّسَمًّۭى ۖ","dilantik"],["فَإِذَا","Kemudian apabila"],["جَآءَ","datang"],["أَجَلُهُمْ","syarat mereka"],["لَا","tidak"],["يَسْتَـْٔخِرُونَ","mereka (akan) tinggal di belakang"],["سَاعَةًۭ ۖ","sejam"],["وَلَا","dan bukan"],["يَسْتَقْدِمُونَ","mereka boleh maju (ia)"]]],"1963":["(Dan mereka menetapkan bagi Allah apa yang mereka sendiri membencinya) untuk diri mereka sendiri, yaitu anak-anak perempuan; menisbatkan sekutu kepada-Nya dan menghina rasul-rasul (dan keluarlah) perkataan (dari lidah mereka) selain dari hal-hal tersebut (kedustaan) yaitu (bahwa sesungguhnya merekalah yang akan mendapat kebaikan) di sisi Allah, yaitu mendapat surga; hal ini dijelaskan oleh firman Allah swt. yang lain, yaitu, \"Dan jika aku dikembalikan kepada Rabbku, maka sesungguhnya aku akan memperoleh kebaikan pada sisi-Nya.\" (Fushshilat 50). Selanjutnya Allah swt. berfirman: (Tiadalah diragukan) sudah dipastikan (bahwa nerakalah bagi mereka, dan sesungguhnya mereka segera dimasukkan ke dalamnya) artinya mereka dibiarkan di dalam neraka, atau mereka dijebloskan ke dalamnya. Menurut suatu qiraat lafal mufrathuuna dibaca mufrithuuna, artinya sesungguhnya mereka adalah orang-orang yang melampaui batas.",[["وَيَجْعَلُونَ","Dan mereka menugaskan"],["لِلَّهِ","kepada Allah"],["مَا","apa"],["يَكْرَهُونَ","mereka tidak suka"],["وَتَصِفُ","dan menegaskan"],["أَلْسِنَتُهُمُ","lidah mereka"],["ٱلْكَذِبَ","pembohongan itu"],["أَنَّ","bahawa"],["لَهُمُ","bagi mereka"],["ٱلْحُسْنَىٰ ۖ","(adalah) yang terbaik"],["لَا","Tidak"],["جَرَمَ","keraguan"],["أَنَّ","bahawa"],["لَهُمُ","bagi mereka"],["ٱلنَّارَ","(ialah) Api"],["وَأَنَّهُم","dan bahawa mereka"],["مُّفْرَطُونَ","(akan) ditinggalkan"]]],"1964":["(Demi Allah, sesungguhnya Kami telah mengutus kepada umat-umat sebelum kamu) telah mengutus rasul-rasul Kami (tetapi setan menjadikan umat-umat itu memandang baik perbuatan mereka) yang buruk itu sehingga perbuatan-perbuatan mereka yang buruk itu dilihatnya baik; oleh karenanya mereka mendustakan rasul-rasul (maka setan menjadi pemimpin mereka) yang mengatur urusan-urusan mereka (di hari itu) yakni di dalam kehidupan dunia (dan bagi mereka azab yang sangat pedih) yang sangat menyakitkan kelak di hari kemudian. Menurut suatu pendapat dikatakan bahwa makna yang dimaksud dengan hari ini ialah hari kiamat; ungkapan ini menggambarkan tentang kejadian di masa mendatang dalam bentuk sekarang; artinya tidak ada seorang penolong pun bagi mereka selain Dia, sedangkan setan sendiri tidak mampu untuk menyelamatkan dirinya sendiri, mana mungkin ia dapat menyelamatkan orang lain.",[["تَٱللَّهِ","Demi Allah"],["لَقَدْ","sudah tentu"],["أَرْسَلْنَآ","Kami telah menghantar"],["إِلَىٰٓ","kepada"],["أُمَمٍۢ","bangsa-bangsa"],["مِّن","sebelum kamu"],["قَبْلِكَ","sebelum kamu"],["فَزَيَّنَ","tetapi dibuat kelihatan adil"],["لَهُمُ","kepada mereka"],["ٱلشَّيْطَـٰنُ","syaitan"],["أَعْمَـٰلَهُمْ","perbuatan mereka"],["فَهُوَ","Jadi dia"],["وَلِيُّهُمُ","(adalah) sekutu mereka"],["ٱلْيَوْمَ","hari ini"],["وَلَهُمْ","dan untuk mereka"],["عَذَابٌ","(ialah) azab"],["أَلِيمٌۭ","yang pedih"]]],"1965":["(Dan Kami tidak menurunkan kepadamu) hai Muhammad (Alkitab ini) Alquran ini (melainkan agar kamu dapat menjelaskan kepada mereka apa yang mereka perselisihkan itu) yaitu tentang perkara agama (dan menjadi petunjuk) diathafkan kepada lafal litubayyina (dan rahmat bagi kaum yang beriman) kepada Alquran itu.",[["وَمَآ","Dan tidak"],["أَنزَلْنَا","Kami mendedahkan"],["عَلَيْكَ","kepada kamu"],["ٱلْكِتَـٰبَ","Kitab"],["إِلَّا","kecuali"],["لِتُبَيِّنَ","yang kamu jelaskan"],["لَهُمُ","kepada mereka"],["ٱلَّذِى","itu yang"],["ٱخْتَلَفُوا۟","mereka berbeza pendapat"],["فِيهِ ۙ","di dalamnya"],["وَهُدًۭى","dan (sebagai) petunjuk"],["وَرَحْمَةًۭ","dan belas kasihan"],["لِّقَوْمٍۢ","bagi kaum"],["يُؤْمِنُونَ","yang beriman"]]],"1966":["(Dan Allah menurunkan dari langit air hujan dan dengan air itu dihidupkan-Nya bumi) dengan tumbuh-tumbuhan (sesudah matinya) dimaksud sesudah mengalami kekeringan. (Sesungguhnya pada yang demikian itu) dalam hal yang telah disebutkan itu (benar benar terdapat tanda) yang menunjukkan adanya hari berbangkit (bagi orang-orang yang mendengarkan) dengan pendengaran dibarengi dengan pemikiran.",[["وَٱللَّهُ","Dan Allah"],["أَنزَلَ","telah menurunkan"],["مِنَ","daripada"],["ٱلسَّمَآءِ","langit"],["مَآءًۭ","air"],["فَأَحْيَا","kemudian memberi kehidupan"],["بِهِ","olehnya"],["ٱلْأَرْضَ","(ke) bumi"],["بَعْدَ","selepas"],["مَوْتِهَآ ۚ","kematiannya"],["إِنَّ","Sesungguhnya"],["فِى","dalam"],["ذَٰلِكَ","bahawa"],["لَـَٔايَةًۭ","(adalah) sesungguhnya suatu tanda"],["لِّقَوْمٍۢ","bagi kaum"],["يَسْمَعُونَ","yang mendengar"]]],"1967":["(Dan sesungguhnya pada binatang ternak itu benar-benar terdapat pelajaran bagi kalian) bahan pelajaran. (Kami memberi kalian minum) lafal ini berfungsi sebagai penjelas daripada pengertian pelajaran tadi (daripada apa yang berada dalam perutnya) dalam perut binatang ternak itu (di) huruf min di sini menunjukkan makna ibtida dan bertaalluq kepada lafal nusqiikum (antara kotoran) yakni lemak ususnya (dan darah berupa air susu yang bersih) sedikit pun tidak bercampur kotoran dan darah baik dari segi rasa, bau atau warnanya atau campuran di antara keduanya (yang mudah ditelan bagi orang-orang yang meminumnya) lewat dengan mudah di tenggorokan mereka dan tidak sulit untuk ditelan.",[["وَإِنَّ","Dan sesungguhnya"],["لَكُمْ","bagi kamu"],["فِى","dalam"],["ٱلْأَنْعَـٰمِ","lembu itu"],["لَعِبْرَةًۭ ۖ","(adalah) pengajaran"],["نُّسْقِيكُم","Kami memberi kamu minum"],["مِّمَّا","daripada apa"],["فِى","(berada) dalam"],["بُطُونِهِۦ","perut mereka"],["مِنۢ","daripada"],["بَيْنِ","antara"],["فَرْثٍۢ","usus"],["وَدَمٍۢ","dan darah"],["لَّبَنًا","susu"],["خَالِصًۭا","tulen"],["سَآئِغًۭا","sedap"],["لِّلشَّـٰرِبِينَ","kepada peminum"]]],"1968":["(Dan dari buah kurma dan anggur) terdapat jenis buah-buahan (yang kalian dapat membuat minuman yang memabukkan daripadanya) dimaksud khamar yang dapat memabukkan. Di sini kata muskiran disebutkan dengan memakai mashdarnya, yaitu sakaran. Hal ini diturunkan sebelum adanya pengharaman khamar (dan rezeki yang baik) seperti selai kurma, anggur kering, cuka dan sirup. (Sesungguhnya pada yang demikian itu) hal yang telah disebutkan itu (benar-benar terdapat tanda) yang menunjukkan kekuasaan Allah swt. (bagi orang-orang yang berakal) yang memikirkannya.",[["وَمِن","Dan daripada"],["ثَمَرَٰتِ","buah-buahan"],["ٱلنَّخِيلِ","pokok kurma"],["وَٱلْأَعْنَـٰبِ","dan buah anggur"],["تَتَّخِذُونَ","kamu ambil"],["مِنْهُ","daripadanya"],["سَكَرًۭا","memabukkan"],["وَرِزْقًا","dan peruntukan"],["حَسَنًا ۗ","kebaikan"],["إِنَّ","Sesungguhnya"],["فِى","dalam"],["ذَٰلِكَ","bahawa"],["لَـَٔايَةًۭ","(adalah) sesungguhnya suatu tanda"],["لِّقَوْمٍۢ","bagi kaum"],["يَعْقِلُونَ","yang menggunakan akal"]]],"1969":["(Dan Rabbmu mewahyukan kepada lebah) dalam bentuk ilham (hendaknya) huruf an di sini dapat diartikan sebagai an mashdariyah atau an mufassirah (buatlah sarang-sarang di bukit-bukit) tempat kamu berdiam (dan di pohon-pohon) sebagai tempat tinggal (dan di tempat-tempat yang dibikin manusia) sarang-sarang buatan manusia untuk kamu, jika kamu tidak suka kepada sarang buatan manusia, kamu boleh menempati tempat yang lainnya.",[["وَأَوْحَىٰ","Dan diilhamkan"],["رَبُّكَ","Tuhanmu"],["إِلَى","kepada"],["ٱلنَّحْلِ","lebah itu"],["أَنِ","[bahawa]"],["ٱتَّخِذِى","ambil"],["مِنَ","antara"],["ٱلْجِبَالِ","pergunungan"],["بُيُوتًۭا","rumah-rumah"],["وَمِنَ","dan antara"],["ٱلشَّجَرِ","pokok-pokok"],["وَمِمَّا","dan dalam apa"],["يَعْرِشُونَ","mereka membina"]]],"1970":["(Kemudian makanlah dari setiap buah-buahan dan tempuhlah) masukilah (jalan Rabbmu) jalan-jalan yang telah ditunjukkan oleh-Nya kepadamu di dalam mencari rezekimu (yang telah dimudahkan) lafal dzululan ini adalah bentuk jamak dari lafal tunggal dzaluulun; berkedudukan menjadi hal dari lafal subula rabbiki. Artinya jalan yang telah dimudahkan bagimu sehingga amat mudah ditempuh sekali pun sangat sulit dan kamu tidak akan sesat untuk kembali ke sarangmu dari tempat itu betapa pun jauhnya. Akan tetapi menurut pendapat yang lain dikatakan bahwa lafal dzululan ini menjadi hal daripada dhamir yang terdapat di dalam lafal uslukiy sehingga artinya menjadi: yang telah ditundukkan untuk memenuhi kehendakmu. (Dari perut lebah itu keluar minuman) yakni berupa madu (yang bermacam-macam warnanya di dalamnya terdapat obat yang menyembuhkan bagi manusia) dari berbagai macam penyakit. Menurut suatu pendapat dikatakan dari sebagian penyakit saja karena ditunjukkan oleh pengertian ungkapan lafal syifaaun yang memakai nakirah. Atau sebagai obat untuk berbagai macam penyakit bila digabungkan dengan obat-obat lainnya. Aku katakan bila tidak dicampur dengan obat yang lain, maka sesuai dengan niat peminumnya. Sungguh Nabi saw. telah memerintahkan untuk meminum madu bagi orang yang perutnya kembung demikianlah menurut riwayat yang telah dikemukakan oleh Imam Bukhari dan Muslim. (Sesungguhnya pada yang demikian itu benar-benar terdapat tanda kebesaran Allah bagi orang-orang yang memikirkan) ciptaan-Nya",[["ثُمَّ","Kemudian"],["كُلِى","makan"],["مِن","daripada"],["كُلِّ","semua"],["ٱلثَّمَرَٰتِ","buah-buahan"],["فَٱسْلُكِى","dan ikut"],["سُبُلَ","(the) cara"],["رَبِّكِ","Tuhanmu"],["ذُلُلًۭا ۚ","dibuat licin"],["يَخْرُجُ","Muncul"],["مِنۢ","daripada"],["بُطُونِهَا","perut mereka"],["شَرَابٌۭ","minuman"],["مُّخْتَلِفٌ","(daripada) berbeza-beza"],["أَلْوَٰنُهُۥ","warna"],["فِيهِ","di dalamnya"],["شِفَآءٌۭ","(adalah) penyembuhan"],["لِّلنَّاسِ ۗ","untuk umat manusia"],["إِنَّ","Sesungguhnya"],["فِى","dalam"],["ذَٰلِكَ","bahawa"],["لَـَٔايَةًۭ","(adalah) sesungguhnya suatu tanda"],["لِّقَوْمٍۢ","bagi kaum"],["يَتَفَكَّرُونَ","yang merenung"]]],"1971":["(Allah menciptakan kalian) yang sebelumnya kalian bukan merupakan apa-apa (kemudian mewafatkan kalian) bila ajal kalian telah tiba (dan di antara kalian ada yang dikembalikan kepada umur yang paling lemah) umur yang sangat lanjut dan pikun (supaya dia tidak mengetahui lagi sesuatu pun yang pernah diketahuinya) Ikrimah mengatakan, bahwa barang siapa yang selalu membaca Alquran, maka ia tidak akan sampai kepada keadaan seperti ini. (Sesungguhnya Allah Maha Mengetahui) di dalam mengatur makhluk-Nya (lagi Maha Kuasa) terhadap apa yang dikehendaki-Nya.",[["وَٱللَّهُ","Dan Allah"],["خَلَقَكُمْ","mencipta kamu"],["ثُمَّ","kemudian"],["يَتَوَفَّىٰكُمْ ۚ","akan menyebabkan kamu mati"],["وَمِنكُم","Dan di antara kamu"],["مَّن","(adalah seorang) siapa"],["يُرَدُّ","dihantar balik"],["إِلَىٰٓ","kepada"],["أَرْذَلِ","yang paling teruk"],["ٱلْعُمُرِ","(dari) umur"],["لِكَىْ","supaya"],["لَا","tidak"],["يَعْلَمَ","dia akan tahu"],["بَعْدَ","selepas"],["عِلْمٍۢ","pengetahuan"],["شَيْـًٔا ۚ","sesuatu perkara"],["إِنَّ","Sesungguhnya"],["ٱللَّهَ","Allah"],["عَلِيمٌۭ","(adalah) Maha Mengetahui"],["قَدِيرٌۭ","Maha Berkuasa"]]],"1972":["(Dan Allah melebihkan sebagian kalian dari sebagian yang lain dalam hal rezeki) di antara kalian ada yang kaya dan ada pula yang miskin, serta ada pula yang menjadi raja dan yang menjadi hamba sahaya (tetapi orang-orang yang dilebihkan rezekinya tidak mau) yakni tuan-tuan pemilik hamba sahaya (memberikan rezeki mereka kepada budak-budak yang mereka miliki) artinya mereka tidak mau menjadikan rezeki yang Kami limpahkan kepada mereka menjadi milik bersama antara mereka dan hamba-hamba sahaya mereka (agar mereka) yakni para pemilik hamba sahaya dan para hamba sahaya yang dimilikinya (sama merasakan rezeki itu) bersekutu memilikinya. Makna yang dimaksud ialah, bahwa mereka tidak akan mau menjadikan harta mereka untuk milik bersama dengan hamba-hamba sahaya mereka, maka mengapa mereka menjadikan sebagian daripada milik-milik Allah menjadi sekutu-sekutu-Nya. (Maka mengapa mereka mengingkari nikmat Allah?) karena ternyata mereka telah menjadikan bagi-Nya sekutu-sekutu.",[["وَٱللَّهُ","Dan Allah"],["فَضَّلَ","telah memihak"],["بَعْضَكُمْ","sebahagian daripada kamu"],["عَلَىٰ","atas"],["بَعْضٍۢ","yang lain"],["فِى","dalam"],["ٱلرِّزْقِ ۚ","peruntukan itu"],["فَمَا","Tetapi tidak"],["ٱلَّذِينَ","orang yang"],["فُضِّلُوا۟","telah digemari"],["بِرَآدِّى","akan menyerahkan"],["رِزْقِهِمْ","rezeki mereka"],["عَلَىٰ","kepada"],["مَا","yang"],["مَلَكَتْ","memiliki"],["أَيْمَـٰنُهُمْ","tangan kanan mereka"],["فَهُمْ","supaya (supaya) mereka"],["فِيهِ","(ada) di dalamnya"],["سَوَآءٌ ۚ","sama rata"],["أَفَبِنِعْمَةِ","Maka adakah Nikmat itu"],["ٱللَّهِ","daripada Allah"],["يَجْحَدُونَ","mereka menolak"]]],"1973":["(Allah menjadikan bagi kalian istri-istri dari jenis kalian sendiri) maka Allah menciptakan Siti Hawa dari tulang rusuk Nabi Adam dan semua manusia lainnya dari mani kaum laki-laki dan wanita (dan menjadikan bagi kalian dari istri-istri kalian itu, anak-anak dan cucu-cucu) keturunan dari anak-anaknya (dan memberi kalian rezeki dari yang baik-baik) berupa berbagai macam buah-buahan, biji-bijian dan hewan-hewan ternak (maka mengapa kepada yang batil) kepada berhala (mereka beriman dan mengapa mereka ingkar terhadap nikmat Allah) dengan menyekutukan-Nya.",[["وَٱللَّهُ","Dan Allah"],["جَعَلَ","(telah) membuat"],["لَكُم","bagi kamu"],["مِّنْ","daripada"],["أَنفُسِكُمْ","kamu sendiri"],["أَزْوَٰجًۭا","pasangan suami isteri"],["وَجَعَلَ","dan telah membuat"],["لَكُم","bagi kamu"],["مِّنْ","daripada"],["أَزْوَٰجِكُم","pasangan kamu"],["بَنِينَ","anak lelaki"],["وَحَفَدَةًۭ","dan cucu"],["وَرَزَقَكُم","dan telah menyediakan untuk kamu"],["مِّنَ","daripada"],["ٱلطَّيِّبَـٰتِ ۚ","perkara yang baik"],["أَفَبِٱلْبَـٰطِلِ","Kemudian dalam kebatilan lakukan"],["يُؤْمِنُونَ","mereka beriman"],["وَبِنِعْمَتِ","dan Nikmat"],["ٱللَّهِ","daripada Allah"],["هُمْ","mereka"],["يَكْفُرُونَ","kufur"]]],"1974":["(Dan mereka menyembah selain Allah) (sesuatu yang tidak dapat memberikan rezeki kepada mereka dari langit) yang dimaksud adalah hujan (dan bumi) yakni tumbuh-tumbuhan (barang sedikit pun) lafal syaian berkedudukan menjadi badal atau pengganti dari lafal rizqan (dan tidak berkuasa) tidak mampu berbuat apa-apa sedikit pun, yang dimaksud adalah berhala-berhala.",[["وَيَعْبُدُونَ","Dan mereka menyembah"],["مِن","selain daripada"],["دُونِ","selain daripada"],["ٱللَّهِ","Allah"],["مَا","yang"],["لَا","tidak"],["يَمْلِكُ","memiliki"],["لَهُمْ","bagi mereka"],["رِزْقًۭا","sebarang peruntukan"],["مِّنَ","daripada"],["ٱلسَّمَـٰوَٰتِ","langit"],["وَٱلْأَرْضِ","dan bumi"],["شَيْـًۭٔا","[apa-apa]"],["وَلَا","dan bukan"],["يَسْتَطِيعُونَ","mereka mampu"]]],"1975":["(Maka janganlah kalian menjadikan bagi Allah tandingan-tandingan) artinya janganlah kalian menjadikan bagi Allah persamaan-persamaan yang kalian sekutukan mereka dengan-Nya. (Sesungguhnya Allah mengetahui) bahwa tiada tandingan bagi-Nya (sedangkan kalian tidak mengetahui) hal tersebut.",[["فَلَا","Jadi (jangan)"],["تَضْرِبُوا۟","mengemukakan"],["لِلَّهِ","kerana Allah"],["ٱلْأَمْثَالَ ۚ","persamaan itu"],["إِنَّ","Sesungguhnya"],["ٱللَّهَ","Allah"],["يَعْلَمُ","mengetahui"],["وَأَنتُمْ","dan kamu"],["لَا","jangan"],["تَعْلَمُونَ","mengetahui"]]],"1976":["(Allah membuat perumpamaan) lafal matsalan ini kemudian dijelaskan oleh badalnya yaitu (dengan seorang hamba sahaya yang dimiliki) lafal mamlukan ini berkedudukan menjadi sifat dari lafal `abdan, dimaksud untuk membedakannya dari manusia yang merdeka, karena manusia yang merdeka disebutkan dengan istilah Abdullaah atau hamba Allah (yang tidak dapat bertindak terhadap sesuatu) karena ia tidak memiliki apa pun (dan seorang) lafal man di sini nakirah maushufah, artinya seorang yang merdeka, bukan hamba sahaya (yang Kami beri rezeki yang baik dari Kami, lalu dia menafkahkan sebagian dari rezeki itu secara sembunyi dan secara terang-terangan) artinya dia menafkahkannya sekehendak hatinya. Misal yang pertama untuk menggambarkan tentang berhala dan misal yang kedua untuk menggambarkan tentang Allah swt. (adakah mereka itu sama?) antara hamba sahaya dan orang merdeka yang bebas dalam bertindak; tentu saja tidak. (Segala puji bagi Allah) semata (tetapi kebanyakan mereka) yakni penduduk kota Mekah (tidak mengetahui) apa yang bakal menimpa mereka kelak yaitu berupa azab, yang karena ketidaktahuan mereka itu akhirnya mereka menyekutukan Allah swt.",[["۞ ضَرَبَ","Allah menetapkan"],["ٱللَّهُ","Allah menetapkan"],["مَثَلًا","contoh"],["عَبْدًۭا","(dari) seorang hamba"],["مَّمْلُوكًۭا","(yang) dimiliki"],["لَّا","tidak"],["يَقْدِرُ","dia ada kuasa"],["عَلَىٰ","pada"],["شَىْءٍۢ","sesuatu"],["وَمَن","dan (satu) siapa"],["رَّزَقْنَـٰهُ","Kami menyediakan dia"],["مِنَّا","daripada Kami"],["رِزْقًا","suatu peruntukan"],["حَسَنًۭا","kebaikan"],["فَهُوَ","jadi dia"],["يُنفِقُ","berbelanja"],["مِنْهُ","daripadanya"],["سِرًّۭا","secara rahsia"],["وَجَهْرًا ۖ","dan secara terbuka"],["هَلْ","boleh"],["يَسْتَوُۥنَ ۚ","mereka sama rata"],["ٱلْحَمْدُ","Segala puji"],["لِلَّهِ ۚ","(adalah) untuk Allah"],["بَلْ","Bahkan"],["أَكْثَرُهُمْ","tetapi kebanyakan mereka"],["لَا","jangan"],["يَعْلَمُونَ","mengetahui"]]],"1977":["(Dan Allah membuat pula perumpamaan) lafal matsalan ini kemudian dijelaskan oleh badalnya, yaitu (dua orang lelaki yang seorang bisu) dilahirkan dalam keadaan cacat tidak dapat berbicara (tidak dapat berbuat sesuatu pun) karenanya ia tidak dapat menangkap pemahaman dan tidak pula dapat memberikan pemahaman (dan dia menjadi beban) yang berat (atas orang yang menanggungnya) atas walinya (ke mana saja dia diarahkan) disuruh (dia tidak dapat mendatangkan) dari tindakannya itu (suatu kebaikan pun) artinya ia tidak pernah berhasil; ini perumpamaan orang kafir. (Samakah orang itu) orang yang bisu itu (dengan orang yang menyuruh berbuat keadilan) artinya dengan orang yang dapat berbicara dan pembicaraannya itu bermanfaat bagi manusia karena ia menyuruh dan menganjurkan manusia untuk berbuat keadilan (dan dia berada pula di atas jalan) di jalan (yang lurus) ini perumpamaan orang yang kedua, yaitu orang muslim. Tentu saja keduanya tidak sama. Akan tetapi menurut suatu pendapat dikatakan bahwa yang kedua ini merupakan misal bagi Allah sedangkan misal yang pertama ditujukan untuk berhala-berhala. Sedangkan perumpamaan yang ada pada ayat sebelumnya adalah perumpamaan antara orang kafir dan orang mukmin.",[["وَضَرَبَ","Dan Allah menetapkan"],["ٱللَّهُ","Dan Allah menetapkan"],["مَثَلًۭا","satu contoh"],["رَّجُلَيْنِ","(dari) dua lelaki"],["أَحَدُهُمَآ","salah seorang daripada mereka"],["أَبْكَمُ","(adalah) bodoh"],["لَا","tidak"],["يَقْدِرُ","dia ada kuasa"],["عَلَىٰ","pada"],["شَىْءٍۢ","sesuatu"],["وَهُوَ","sedangkan dia"],["كَلٌّ","(adalah) beban"],["عَلَىٰ","pada"],["مَوْلَىٰهُ","tuannya"],["أَيْنَمَا","di mana sahaja"],["يُوَجِّههُّ","dia mengarahkannya"],["لَا","tidak"],["يَأْتِ","dia datang"],["بِخَيْرٍ ۖ","dengan apa-apa kebaikan"],["هَلْ","Adakah"],["يَسْتَوِى","sama rata"],["هُوَ","dia"],["وَمَن","dan (yang) siapa"],["يَأْمُرُ","arahan"],["بِٱلْعَدْلِ ۙ","[dari] keadilan"],["وَهُوَ","dan dia"],["عَلَىٰ","(berada) di atas"],["صِرَٰطٍۢ","satu laluan"],["مُّسْتَقِيمٍۢ","lurus"]]],"1978":["(Dan kepunyaan Allahlah segala apa yang tersembunyi di langit dan di bumi) artinya Allah mengetahui semua yang gaib pada keduanya (Tidak adalah kejadian kiamat itu melainkan seperti sekejap mata atau lebih cepat lagi) karena hal itu berlangsung hanya dengan kalimat kun terjadilah ia. (Sesungguhnya Allah Maha Kuasa atas segala sesuatu.)",[["وَلِلَّهِ","Dan kepunyaan Allah"],["غَيْبُ","(yang) ghaib"],["ٱلسَّمَـٰوَٰتِ","langit"],["وَٱلْأَرْضِ ۚ","dan bumi"],["وَمَآ","Dan tidak"],["أَمْرُ","(ialah) perkara"],["ٱلسَّاعَةِ","(dari) hari kiamat"],["إِلَّا","tetapi"],["كَلَمْحِ","sebagai sekelip mata"],["ٱلْبَصَرِ","(dari) mata"],["أَوْ","atau"],["هُوَ","ia"],["أَقْرَبُ ۚ","(adalah) lebih dekat"],["إِنَّ","Sesungguhnya"],["ٱللَّهَ","Allah"],["عَلَىٰ","pada"],["كُلِّ","setiap"],["شَىْءٍۢ","perkara"],["قَدِيرٌۭ","(adalah) Maha Kuasa"]]],"1979":["(Dan Allah mengeluarkan kalian dari perut ibu kalian dalam keadaan tidak mengetahui sesuatu pun) jumlah kalimat laa ta'lamuuna syaian berkedudukan menjadi hal atau kalimat keterangan (dan Dia memberi kalian pendengaran) lafal as-sam'u bermakna jamak sekali pun lafalnya mufrad (penglihatan dan hati) kalbu (agar kalian bersyukur) kepada-Nya atas hal-hal tersebut, oleh karenanya kalian beriman kepada-Nya.",[["وَٱللَّهُ","Dan Allah"],["أَخْرَجَكُم","melahirkan kamu"],["مِّنۢ","daripada"],["بُطُونِ","rahim"],["أُمَّهَـٰتِكُمْ","(dari) ibu kamu"],["لَا","tidak"],["تَعْلَمُونَ","mengetahui"],["شَيْـًۭٔا","sesuatu"],["وَجَعَلَ","dan dibuat"],["لَكُمُ","bagi kamu"],["ٱلسَّمْعَ","pendengaran"],["وَٱلْأَبْصَـٰرَ","dan penglihatan"],["وَٱلْأَفْـِٔدَةَ ۙ","dan hati"],["لَعَلَّكُمْ","supaya kamu"],["تَشْكُرُونَ","bersyukurlah"]]],"1980":["(Tidakkah mereka memperhatikan burung-burung yang dimudahkan) terbang (di angkasa bebas) di udara antara langit dan bumi. (Tidak ada yang menahannya) sewaktu ia melipat sayap atau mengembangkannya sehingga ia tidak jatuh ke bawah (selain daripada Allah) yakni dengan kekuasaan-Nya. (Sesungguhnya pada yang demikian itu benar-benar terdapat tanda-tanda kekuasaan Allah bagi orang-orang yang beriman) yaitu penciptaan burung itu sehingga dapat terbang dan penciptaan udara sehingga dapat memungkinkan bagi burung untuk terbang mengarunginya dan menahan burung untuk tidak jatuh ke tanah.",[["أَلَمْ","Jangan"],["يَرَوْا۟","mereka lihat"],["إِلَى","ke arah"],["ٱلطَّيْرِ","burung-burung itu"],["مُسَخَّرَٰتٍۢ","terkawal"],["فِى","dalam"],["جَوِّ","tengah-tengah"],["ٱلسَّمَآءِ","(dari) langit"],["مَا","tiada"],["يُمْسِكُهُنَّ","menahan mereka"],["إِلَّا","kecuali"],["ٱللَّهُ ۗ","Allah"],["إِنَّ","Sesungguhnya"],["فِى","dalam"],["ذَٰلِكَ","bahawa"],["لَـَٔايَـٰتٍۢ","(adalah) Tanda-tanda"],["لِّقَوْمٍۢ","bagi kaum"],["يُؤْمِنُونَ","yang beriman"]]],"1981":["(Dan Allah menjadikan bagi kalian rumah-rumah kalian sebagai tempat tinggal) tempat kalian menetap di dalamnya (dan Dia menjadikan bagi kalian rumah-rumah dari kulit binatang ternak) seperti kemah-kemah dan tenda-tenda (yang kalian merasa ringan) ketika membawanya (di waktu kalian berjalan) mengadakan perjalanan (dan waktu kalian bermukim, dan dijadikan-Nya pula, dari bulunya) dari bulu domba (bulu unta) (dan bulu kambing) (alat-alat) perabot rumah tangga kalian; seperti permadani dan perhiasan dinding rumah (dan perhiasan) yang kalian dapat menikmatinya (sampai waktu yang tertentu) sehingga barang-barang itu rusak.",[["وَٱللَّهُ","Dan Allah"],["جَعَلَ","(telah) membuat"],["لَكُم","bagi kamu"],["مِّنۢ","[dari]"],["بُيُوتِكُمْ","rumah kamu"],["سَكَنًۭا","tempat berehat"],["وَجَعَلَ","dan dibuat"],["لَكُم","bagi kamu"],["مِّن","daripada"],["جُلُودِ","kulit"],["ٱلْأَنْعَـٰمِ","(dari) lembu"],["بُيُوتًۭا","khemah"],["تَسْتَخِفُّونَهَا","yang kamu dapati cahaya"],["يَوْمَ","(pada) hari itu"],["ظَعْنِكُمْ","(dari) perjalanan kamu"],["وَيَوْمَ","dan hari"],["إِقَامَتِكُمْ ۙ","(dari) perkhemahan kamu"],["وَمِنْ","dan daripada"],["أَصْوَافِهَا","bulu mereka"],["وَأَوْبَارِهَا","dan bulu mereka"],["وَأَشْعَارِهَآ","dan rambut mereka"],["أَثَـٰثًۭا","(adalah) kelengkapan"],["وَمَتَـٰعًا","dan peruntukan"],["إِلَىٰ","bagi"],["حِينٍۢ","suatu masa"]]],"1982":["(Dan Allah menjadikan bagi kalian dari apa yang telah Dia ciptakan) seperti rumah-rumah, pohon-pohon dan mendung (sebagai tempat bernaung) lafal zhilaalan adalah bentuk jamak dari lafal zhillun; yang dapat melindungi diri kalian dari sengatan panas matahari (dan Dia jadikan bagi kalian tempat-tempat tinggal di gunung-gunung) lafal aknaanan adalah bentuk jamak dari lafal kinnun, yang artinya tempat untuk tinggal seperti gua dan liang besar (dan Dia jadikan bagi kalian pakaian) baju-baju gamis (yang memelihara kalian dari panas) dan dari dingin (dan pakaian/baju besi yang memelihara kalian dalam peperangan) sewaktu kalian berperang yakni dari tusukan dan pukulan senjata di dalam peperangan, seperti baju dan topi besi. (Demikianlah) sebagaimana Dia telah menciptakan semuanya itu (Allah menyempurnakan nikmat-Nya) di dunia (atas kalian) dengan menciptakan segala sesuatu yang menjadi keperluan kalian (agar kalian) hai penduduk Mekah (masuk Islam) agar kalian mengesakan-Nya.",[["وَٱللَّهُ","Dan Allah"],["جَعَلَ","(telah) membuat"],["لَكُم","bagi kamu"],["مِّمَّا","daripada apa"],["خَلَقَ","Dia cipta"],["ظِلَـٰلًۭا","warna"],["وَجَعَلَ","dan (telah) membuat"],["لَكُم","bagi kamu"],["مِّنَ","daripada"],["ٱلْجِبَالِ","pergunungan"],["أَكْنَـٰنًۭا","tempat perlindungan"],["وَجَعَلَ","dan (telah) membuat"],["لَكُمْ","bagi kamu"],["سَرَٰبِيلَ","pakaian"],["تَقِيكُمُ","untuk melindungi kamu"],["ٱلْحَرَّ","(dari) kepanasan"],["وَسَرَٰبِيلَ","dan pakaian"],["تَقِيكُم","untuk melindungi kamu"],["بَأْسَكُمْ ۚ","daripada keganasan (saling) kamu"],["كَذَٰلِكَ","Demikianlah"],["يُتِمُّ","Dia melengkapkan"],["نِعْمَتَهُۥ","NikmatNya"],["عَلَيْكُمْ","ke atas kamu"],["لَعَلَّكُمْ","supaya kamu"],["تُسْلِمُونَ","menyerahkan"]]],"1983":["(Jika mereka tetap berpaling) tidak juga mau masuk Islam (maka sesungguhnya kewajiban yang dibebankan kepadamu) hai Muhammad (hanyalah menyampaikan amanat Allah, dengan terang) ayat ini diturunkan sebelum ada perintah untuk memerangi orang-orang kafir.",[["فَإِن","Kemudian, jika"],["تَوَلَّوْا۟","mereka berpaling"],["فَإِنَّمَا","kemudian sahaja"],["عَلَيْكَ","ke atas kamu"],["ٱلْبَلَـٰغُ","(ialah) pengangkutan"],["ٱلْمُبِينُ","yang jelas"]]],"1984":["(Mereka mengetahui nikmat Allah) artinya mereka mengakui bahwa semua nikmat itu dari sisi-Nya (kemudian mereka mengingkarinya) karena ternyata mereka menyekutukan-Nya (dan kebanyakan mereka adalah orang-orang yang kafir).",[["يَعْرِفُونَ","Mereka mengenali"],["نِعْمَتَ","(yang) nikmat"],["ٱللَّهِ","(milik) Allah"],["ثُمَّ","kemudian"],["يُنكِرُونَهَا","mereka menafikannya"],["وَأَكْثَرُهُمُ","Dan kebanyakan mereka"],["ٱلْكَـٰفِرُونَ","(ialah) orang-orang yang kafir"]]],"1985":["(Dan) ingatlah (akan hari ketika Kami membangkitkan dari tiap-tiap umat seorang saksi) yakni nabinya yang berkesaksian tentang kebaikan atau keburukan yang dilakukan oleh umatnya, yaitu pada hari kiamat nanti (kemudian tidak diizinkan kepada orang-orang yang kafir) untuk mengemukakan alasannya (dan tidak pula mereka dibolehkan meminta maaf) artinya mereka tidak diperkenankan untuk minta maaf kepada Allah swt.",[["وَيَوْمَ","Dan Hari"],["نَبْعَثُ","Kami akan bangkitkan"],["مِن","daripada"],["كُلِّ","setiap"],["أُمَّةٍۢ","bangsa"],["شَهِيدًۭا","seorang saksi"],["ثُمَّ","kemudian"],["لَا","tidak"],["يُؤْذَنُ","akan dibenarkan"],["لِلَّذِينَ","kepada mereka yang"],["كَفَرُوا۟","kufur"],["وَلَا","dan bukan"],["هُمْ","mereka"],["يُسْتَعْتَبُونَ","akan diminta untuk membuat perubahan"]]],"1986":["(Dan apabila orang-orang lalim telah menyaksikan) yang dimaksud adalah orang-orang yang kafir (azab) yakni neraka (maka tidak diringankan bagi mereka) azab itu (dan tidak pula mereka diberi tangguh) ditangguhkan dari siksa neraka bila mereka telah melihatnya.",[["وَإِذَا","Dan apabila"],["رَءَا","(akan) melihat"],["ٱلَّذِينَ","orang yang"],["ظَلَمُوا۟","dizalimi"],["ٱلْعَذَابَ","azab"],["فَلَا","maka tidak"],["يُخَفَّفُ","ia akan diringankan"],["عَنْهُمْ","bagi mereka"],["وَلَا","dan bukan"],["هُمْ","mereka"],["يُنظَرُونَ","akan diberi tangguh"]]],"1987":["(Dan apabila orang-orang yang mempersekutukan Allah melihat sekutu-sekutu mereka) yang terdiri daripada setan-setan dan lain-lainnya (mereka berkata, \"Ya Rabb kami! Mereka inilah sekutu-sekutu kami yang dahulu kami seru) kami sembah (selain dari Engkau.\" Lalu sekutu-sekutu mereka mengatakan kepada mereka) artinya para sekutu mereka itu berkata kepada mereka (\"Sesungguhnya kalian benar-benar orang-orang yang dusta.\") di dalam pengakuan kalian itu, yang mengatakan bahwa kalian telah menyembah kami, sebagaimana yang telah dijelaskan di dalam ayat yang lain, yaitu melalui firman-Nya, \"Mereka sekali-kali tidak menyembah kami.\" (Al-Qashash 63). Sekutu-sekutu itu pasti akan mengingkari penyembahan mereka terhadap dirinya.",[["وَإِذَا","Dan apabila"],["رَءَا","(akan) melihat"],["ٱلَّذِينَ","orang yang"],["أَشْرَكُوا۟","mempersekutukan Allah"],["شُرَكَآءَهُمْ","rakan kongsi mereka"],["قَالُوا۟","Mereka akan berkata"],["رَبَّنَا","Wahai Tuhan kami"],["هَـٰٓؤُلَآءِ","ini"],["شُرَكَآؤُنَا","(adalah) rakan kongsi kami"],["ٱلَّذِينَ","mereka yang"],["كُنَّا","kita dulu"],["نَدْعُوا۟","menyeru"],["مِن","selain Engkau"],["دُونِكَ ۖ","selain Engkau"],["فَأَلْقَوْا۟","Tetapi mereka (akan) melemparkan kembali"],["إِلَيْهِمُ","pada mereka"],["ٱلْقَوْلَ","perkataan (mereka)."],["إِنَّكُمْ","Sesungguhnya kamu"],["لَكَـٰذِبُونَ","(adalah) sesungguhnya pendusta"]]],"1988":["(Dan mereka menyatakan ketundukannya kepada Allah pada hari itu) artinya mereka tunduk terhadap keputusan Allah (dan hilanglah) lenyaplah (dari mereka apa yang selalu mereka ada-adakan) yang menyatakan bahwa sekutu-sekutu mereka itu dapat memberikan syafaat bagi mereka.",[["وَأَلْقَوْا۟","Dan mereka (akan) menawarkan"],["إِلَى","kepada"],["ٱللَّهِ","Allah"],["يَوْمَئِذٍ","(pada) hari itu"],["ٱلسَّلَمَ ۖ","penyerahan itu"],["وَضَلَّ","dan (sedang) hilang"],["عَنْهُم","daripada mereka"],["مَّا","apa"],["كَانُوا۟","mereka pernah (untuk)"],["يَفْتَرُونَ","mencipta"]]],"1989":["(Orang-orang yang kafir dan menghalang-halangi) manusia (dari jalan Allah) dari agama-Nya (Kami tambahkan kepada mereka siksaan di atas siksaan) yakni di atas siksaan yang berhak mereka terima dikarenakan kekafiran mereka. Ibnu Masud r.a. mengatakan, bahwa siksaan tambahan itu berupa kelabang-kelabang yang taringnya bagaikan batang-batang pohon kurma yang tinggi (disebabkan mereka selalu berbuat kerusakan) karena mereka telah mencegah manusia untuk beriman kepada Allah.",[["ٱلَّذِينَ","Dan orang yang"],["كَفَرُوا۟","kufur"],["وَصَدُّوا۟","dan terhalang"],["عَن","daripada"],["سَبِيلِ","jalan"],["ٱللَّهِ","(milik) Allah"],["زِدْنَـٰهُمْ","Kami akan meningkatkan mereka"],["عَذَابًۭا","(dalam) hukuman"],["فَوْقَ","atas"],["ٱلْعَذَابِ","hukuman"],["بِمَا","kerana"],["كَانُوا۟","mereka pernah (untuk)"],["يُفْسِدُونَ","menyebarkan rasuah"]]],"1990":["(Dan) ingatlah (akan hari ketika Kami bangkitkan pada tiap-tiap umat seorang saksi atas mereka dari mereka sendiri) yakni nabi mereka sendiri (dan Kami datangkan kamu) hai Muhammad (menjadi saksi atas mereka) bagi kaummu. (Dan Kami turunkan kepadamu Alkitab) yakni Alquran (untuk menjelaskan) untuk menerangkan (segala sesuatu) yang diperlukan oleh umat manusia menyangkut masalah syariat (dan petunjuk) supaya jangan tersesat (serta rahmat dan kabar gembira) memperoleh surga (bagi orang-orang yang beriman) bagi orang-orang yang mentauhidkan Allah.",[["وَيَوْمَ","Dan Hari"],["نَبْعَثُ","Kami akan bangkitkan"],["فِى","antara"],["كُلِّ","setiap"],["أُمَّةٍۢ","bangsa"],["شَهِيدًا","seorang saksi"],["عَلَيْهِم","atas mereka"],["مِّنْ","daripada"],["أَنفُسِهِمْ ۖ","diri mereka"],["وَجِئْنَا","Dan Kami (akan) mendatangkan"],["بِكَ","kamu"],["شَهِيدًا","(sebagai) saksi"],["عَلَىٰ","atas"],["هَـٰٓؤُلَآءِ ۚ","ini"],["وَنَزَّلْنَا","Dan Kami turunkan"],["عَلَيْكَ","kepada kamu"],["ٱلْكِتَـٰبَ","Kitab"],["تِبْيَـٰنًۭا","(sebagai) penjelasan"],["لِّكُلِّ","daripada setiap"],["شَىْءٍۢ","perkara"],["وَهُدًۭى","dan hidayah"],["وَرَحْمَةًۭ","dan belas kasihan"],["وَبُشْرَىٰ","dan khabar gembira"],["لِلْمُسْلِمِينَ","untuk umat Islam"]]],"1991":["(Sesungguhnya Allah menyuruh kalian berlaku adil) bertauhid atau berlaku adil dengan sesungguhnya (dan berbuat kebaikan) menunaikan fardu-fardu, atau hendaknya kamu menyembah Allah seolah-olah kamu melihat-Nya sebagaimana yang telah dijelaskan oleh hadis (memberi) bantuan (kepada kaum kerabat) famili; mereka disebutkan secara khusus di sini, sebagai pertanda bahwa mereka harus dipentingkan terlebih dahulu (dan Allah melarang dari perbuatan keji) yakni zina (dan kemungkaran) menurut hukum syariat, yaitu berupa perbuatan kekafiran dan kemaksiatan (dan permusuhan) menganiaya orang lain. Lafal al-baghyu disebutkan di sini secara khusus sebagai pertanda, bahwa ia harus lebih dijauhi; dan demikian pula halnya dengan penyebutan lafal al-fahsyaa (Dia memberi pengajaran kepada kalian) melalui perintah dan larangan-Nya (agar kalian dapat mengambil pelajaran) mengambil pelajaran dari hal tersebut. Di dalam lafal tadzakkaruuna menurut bentuk asalnya ialah huruf ta-nya diidghamkan kepada huruf dzal. Di dalam kitab Al-Mustadrak disebutkan suatu riwayat yang bersumber dari Ibnu Masud yang telah mengatakan, bahwa ayat ini yakni ayat 90 surah An-Nahl, adalah ayat yang paling padat mengandung anjuran melakukan kebaikan dan menjauhi keburukan di dalam Alquran.",[["۞ إِنَّ","Sesungguhnya"],["ٱللَّهَ","Allah"],["يَأْمُرُ","arahan"],["بِٱلْعَدْلِ","keadilan"],["وَٱلْإِحْسَـٰنِ","dan yang baik"],["وَإِيتَآئِ","dan memberi"],["ذِى","(kepada) saudara mara"],["ٱلْقُرْبَىٰ","(kepada) saudara mara"],["وَيَنْهَىٰ","dan melarang"],["عَنِ","[dari]"],["ٱلْفَحْشَآءِ","maksiat itu"],["وَٱلْمُنكَرِ","dan yang buruk"],["وَٱلْبَغْىِ ۚ","dan penindasan"],["يَعِظُكُمْ","Dia menasihati kamu"],["لَعَلَّكُمْ","supaya kamu"],["تَذَكَّرُونَ","ambil iktibar"]]],"1992":["(Dan tepatilah perjanjian dengan Allah) dalam masalah jual beli dan sumpah-sumpah serta masalah-masalah yang lain (apabila kalian berjanji dan janganlah kalian membatalkan sumpah-sumpah itu sesudah meneguhkannya) artinya sesudah sumpah-sumpah itu kalian teguhkan (sedangkan kalian telah menjadikan Allah sebagai saksi kalian) untuk memenuhinya, karena kalian telah bersumpah dengan memakai nama-Nya; jumlah ayat ini berkedudukan menjadi hal atau kalimat keterangan. (Sesungguhnya Allah mengetahui apa yang kalian perbuat) ayat ini merupakan ancaman buat mereka yang membatalkan sumpahnya.",[["وَأَوْفُوا۟","Dan penuhi"],["بِعَهْدِ","perjanjian itu"],["ٱللَّهِ","(milik) Allah"],["إِذَا","apabila"],["عَـٰهَدتُّمْ","kamu telah mengambil perjanjian"],["وَلَا","dan jangan"],["تَنقُضُوا۟","rehat"],["ٱلْأَيْمَـٰنَ","sumpah"],["بَعْدَ","selepas"],["تَوْكِيدِهَا","pengesahan mereka"],["وَقَدْ","sedangkan sesungguhnya"],["جَعَلْتُمُ","kamu telah buat"],["ٱللَّهَ","Allah"],["عَلَيْكُمْ","atas kamu"],["كَفِيلًا ۚ","seorang penjamin"],["إِنَّ","Sesungguhnya"],["ٱللَّهَ","Allah"],["يَعْلَمُ","mengetahui"],["مَا","apa"],["تَفْعَلُونَ","kamu lakukan"]]],"1993":["(Dan janganlah kalian seperti seorang perempuan yang menguraikan) merusak (benangnya) hasil apa yang telah dipintalnya (yang sudah dipintal dengan kuat) sudah dijadikan benang (menjadi cerai-berai kembali) lafal ankaatsan berkedudukan menjadi hal, bentuk jamak daripada lafal naktsun; artinya mencerai-beraikan benang yang sudah dipintal kuat. Hal ini merupakan gambaran tentang seorang wanita penduduk kota Mekah; ia setiap hari memintal benang, tetapi sesudah benang itu jadi, lalu ia uraikan kembali; wanita itu dikenal sebagai wanita yang tolol (kalian menjadikan) lafal tattakhidzuuna menjadi hal dari dhamir lafal takuunuu; artinya janganlah kalian seperti wanita yang tolol itu, yaitu kalian menjadikan (sumpah kalian sebagai alat penipu) arti dakhalan ialah memasukkan sesuatu bukan pada tempatnya dan ia bukan merupakan bagian daripadanya; makna yang dimaksud ialah menimbulkan kerusakan atau tipu muslihat (di antara kalian) seumpamanya kalian merusak sumpah itu (disebabkan) lafal an di sini asalnya lian (adanya satu golongan) satu kelompok (yang lebih banyak) jumlahnya (dari golongan yang lain). Disebutkan bahwa mereka mengadakan sumpah perjanjian pertahanan dengan suatu golongan, tetapi bila mereka melihat ada golongan yang lain yang lebih kuat dan lebih banyak jumlahnya, lalu mereka merusak dan membatalkan perjanjiannya dengan golongan yang pertama itu, kemudian mereka mengadakan perjanjian pertahanan dengan golongan yang baru dan yang lebih kuat itu. (Sesungguhnya kalian dicoba) diuji (oleh Allah dengannya) yakni dengan perintah supaya kalian memenuhi sumpah, agar Dia melihat siapakah yang taat di antara kalian dan siapa yang durhaka. Atau membuat suatu umat yang kuat agar Dia melihat apakah mereka memenuhi janjinya atau tidak. (Dan sesungguhnya di hari kiamat akan dijelaskan-Nya kepada kalian apa yang dahulu kalian perselisihkan itu) sewaktu di dunia menyangkut masalah sumpah dan masalah-masalah lainnya; kelak Dia akan mengazab orang yang melanggar sumpahnya dan akan memberi pahala kepada orang yang memenuhinya.",[["وَلَا","Dan jangan"],["تَكُونُوا۟","jadilah"],["كَٱلَّتِى","seperti dia yang"],["نَقَضَتْ","meleraikan"],["غَزْلَهَا","benang yang dipintalnya"],["مِنۢ","selepas"],["بَعْدِ","selepas"],["قُوَّةٍ","kekuatan"],["أَنكَـٰثًۭا","(ke dalam) helai yang tidak berpintal"],["تَتَّخِذُونَ","kamu ambil"],["أَيْمَـٰنَكُمْ","sumpah kamu"],["دَخَلًۢا","(sebagai) satu penipuan"],["بَيْنَكُمْ","antara kamu"],["أَن","kerana"],["تَكُونَ","ialah"],["أُمَّةٌ","sesebuah komuniti"],["هِىَ","[ia]"],["أَرْبَىٰ","lebih ramai"],["مِنْ","daripada"],["أُمَّةٍ ۚ","masyarakat (yang lain)."],["إِنَّمَا","Hanya"],["يَبْلُوكُمُ","Allah menguji kamu"],["ٱللَّهُ","Allah menguji kamu"],["بِهِۦ ۚ","olehnya"],["وَلَيُبَيِّنَنَّ","Dan Dia akan menerangkan"],["لَكُمْ","kepada kamu"],["يَوْمَ","(pada) hari itu"],["ٱلْقِيَـٰمَةِ","Kiamat"],["مَا","apa"],["كُنتُمْ","kamu pernah (untuk)"],["فِيهِ","di dalamnya"],["تَخْتَلِفُونَ","berbeza"]]],"1994":["(Dan kalau Allah menghendaki, niscaya Dia menjadikan kalian satu umat) menjadi pemeluk satu agama (tetapi Allah menyesatkan siapa yang dikehendaki-Nya dan memberi petunjuk kepada siapa yang dikehendaki-Nya. Dan sesungguhnya kalian akan ditanya) kelak di hari kiamat dengan pertanyaan yang keras (tentang apa yang telah kalian kerjakan) kemudian kalian mendapatkan balasannya.",[["وَلَوْ","Dan jika"],["شَآءَ","Allah (telah) menghendaki"],["ٱللَّهُ","Allah (telah) menghendaki"],["لَجَعَلَكُمْ","sesungguhnya Dia (boleh) menjadikan kamu"],["أُمَّةًۭ","sebuah bangsa"],["وَٰحِدَةًۭ","satu"],["وَلَـٰكِن","tetapi"],["يُضِلُّ","Dia biarkan sesat"],["مَن","yang"],["يَشَآءُ","Dia kehendaki"],["وَيَهْدِى","dan panduan"],["مَن","yang"],["يَشَآءُ ۚ","Dia kehendaki"],["وَلَتُسْـَٔلُنَّ","Dan sesungguhnya kamu akan ditanya"],["عَمَّا","tentang apa"],["كُنتُمْ","kamu pernah (untuk)"],["تَعْمَلُونَ","lakukan"]]],"1995":["(Dan janganlah kalian jadikan sumpah-sumpah kalian sebagai alat penipu di antara kalian) Allah swt. mengulang-ulang kalimat ini untuk mengukuhkannya (yang menyebabkan tergelincir kaki kalian) artinya kalian tergelincir dari ajaran Islam (sesudah kokoh tegaknya) sesudah kalian teguh memegangnya (dan kalian rasakan azab) siksaan (karena kalian menghalangi manusia dari jalan Allah) artinya disebabkan kalian tidak mau memenuhi janji kalian sendiri, atau disebabkan kalian menghalang-halangi orang lain untuk memenuhi sumpah dan janjinya, kemudian orang lain itu menuruti perintah kalian (dan bagi kalian azab yang besar) di akhirat nanti.",[["وَلَا","Dan jangan"],["تَتَّخِذُوٓا۟","ambil"],["أَيْمَـٰنَكُمْ","sumpah kamu"],["دَخَلًۢا","(sebagai) satu penipuan"],["بَيْنَكُمْ","antara kamu"],["فَتَزِلَّ","jangan-jangan, akan tergelincir"],["قَدَمٌۢ","satu kaki"],["بَعْدَ","selepas"],["ثُبُوتِهَا","ia ditanam dengan kukuh"],["وَتَذُوقُوا۟","dan kamu akan rasa"],["ٱلسُّوٓءَ","yang jahat"],["بِمَا","bagi apa"],["صَدَدتُّمْ","kamu menghalang"],["عَن","daripada"],["سَبِيلِ","jalan"],["ٱللَّهِ ۖ","(milik) Allah"],["وَلَكُمْ","dan untuk kamu"],["عَذَابٌ","(ialah) azab"],["عَظِيمٌۭ","yang besar"]]],"1996":["(Dan janganlah kalian tukar perjanjian kalian dengan Allah dengan harga yang sedikit) berupa keduniaan, seumpamanya kalian membatalkan janji itu demi karena perkara duniawi (sesungguhnya apa yang ada di sisi Allah) berupa pahala (itulah yang lebih baik bagi kalian) daripada apa yang terdapat di dunia (jika kalian mengetahui) hal tersebut; maka oleh sebab itu janganlah kalian merusak janji kalian.",[["وَلَا","Dan jangan"],["تَشْتَرُوا۟","pertukaran"],["بِعَهْدِ","perjanjian itu"],["ٱللَّهِ","(milik) Allah"],["ثَمَنًۭا","(untuk) harga"],["قَلِيلًا ۚ","sedikit"],["إِنَّمَا","Memang apa"],["عِندَ","(adalah) dengan"],["ٱللَّهِ","Allah"],["هُوَ","ia"],["خَيْرٌۭ","(lebih) baik"],["لَّكُمْ","bagi kamu"],["إِن","jika"],["كُنتُمْ","kamu (untuk)"],["تَعْلَمُونَ","mengetahui"]]],"1997":["(Apa yang di sisi kalian) berupa duniawi (akan lenyap) akan musnah (dan apa yang ada di sisi Allah adalah kekal) abadi. (Dan sesungguhnya Kami akan memberi balasan) dapat dibaca walayajziyanna dan walanajziyanna (orang-orang yang sabar) demi menunaikan janjinya (dengan pahala yang lebih baik dari apa yang telah mereka kerjakan) lafal ahsana di sini maknanya sama dengan hasuna.",[["مَا","apapun"],["عِندَكُمْ","(ada) bersama kamu"],["يَنفَدُ ۖ","akan habis"],["وَمَا","dan apa sahaja"],["عِندَ","(adalah) dengan"],["ٱللَّهِ","Allah"],["بَاقٍۢ ۗ","(akan) kekal"],["وَلَنَجْزِيَنَّ","Dan sesungguhnya Kami akan membayar"],["ٱلَّذِينَ","orang yang"],["صَبَرُوٓا۟","(adalah) sabar"],["أَجْرَهُم","ganjaran mereka"],["بِأَحْسَنِ","kepada (yang) terbaik"],["مَا","apa"],["كَانُوا۟","mereka pernah (untuk)"],["يَعْمَلُونَ","lakukan"]]],"1998":["(Barang siapa yang mengerjakan amal saleh baik laki-laki maupun perempuan dalam keadaan beriman, maka sesungguhnya akan Kami berikan kepadanya kehidupan yang baik) menurut suatu pendapat dikatakan bahwa yang dimaksud adalah kehidupan di surga. Menurut pendapat yang lain dikatakan adalah kehidupan dunia, yaitu dengan mendapatkan rasa qana`ah atau menerima apa adanya atau ia mendapatkan rezeki yang halal (dan sesungguhnya akan Kami beri balasan kepada mereka dengan pahala yang lebih baik dari apa yang telah mereka kerjakan).",[["مَنْ","Siapa pun"],["عَمِلَ","tidak"],["صَـٰلِحًۭا","amal soleh"],["مِّن","sama ada"],["ذَكَرٍ","lelaki"],["أَوْ","atau"],["أُنثَىٰ","perempuan"],["وَهُوَ","sedangkan dia"],["مُؤْمِنٌۭ","(adalah) seorang yang beriman"],["فَلَنُحْيِيَنَّهُۥ","maka sesungguhnya Kami akan menghidupkannya"],["حَيَوٰةًۭ","sebuah kehidupan"],["طَيِّبَةًۭ ۖ","kebaikan"],["وَلَنَجْزِيَنَّهُمْ","dan Kami akan membayar mereka"],["أَجْرَهُم","ganjaran mereka"],["بِأَحْسَنِ","kepada (yang) terbaik"],["مَا","tentang apa"],["كَانُوا۟","mereka pernah (untuk)"],["يَعْمَلُونَ","lakukan"]]],"1999":["(Apabila kamu membaca Alquran) artinya bila kamu hendak membaca Alquran (hendaklah kamu meminta perlindungan kepada Allah dari setan yang terkutuk) artinya ucapkanlah a`uudzu billaahi minasy syaithaanirrajiim.",[["فَإِذَا","Maka apabila"],["قَرَأْتَ","kamu mengaji"],["ٱلْقُرْءَانَ","al-Quran"],["فَٱسْتَعِذْ","mencari perlindungan"],["بِٱللَّهِ","kepada Allah"],["مِنَ","daripada"],["ٱلشَّيْطَـٰنِ","syaitan"],["ٱلرَّجِيمِ","yang terkutuk"]]],"2000":["(Sesungguhnya setan itu tidak ada kekuasaan baginya) tidak mempunyai pengaruh (atas orang-orang yang beriman dan bertawakal kepada Rabbnya.)",[["إِنَّهُۥ","Memang dia"],["لَيْسَ","tidak"],["لَهُۥ","baginya"],["سُلْطَـٰنٌ","(adalah) mana-mana pihak berkuasa"],["عَلَى","pada"],["ٱلَّذِينَ","orang yang"],["ءَامَنُوا۟","beriman"],["وَعَلَىٰ","dan seterusnya"],["رَبِّهِمْ","Tuhan mereka"],["يَتَوَكَّلُونَ","mereka meletakkan kepercayaan mereka"]]],"2001":["(Sesungguhnya kekuasaannya hanyalah atas orang-orang yang mengambilnya sebagai pemimpin) yaitu yang taat kepadanya (dan atas orang-orang yang terhadap-Nya) maksudnya kepada Allah (mereka mempersekutukan.)",[["إِنَّمَا","Hanya"],["سُلْطَـٰنُهُۥ","kewibawaannya"],["عَلَى","(sudah) tamat"],["ٱلَّذِينَ","orang yang"],["يَتَوَلَّوْنَهُۥ","ambil dia sebagai sekutu"],["وَٱلَّذِينَ","dan orang yang"],["هُم","[mereka]"],["بِهِۦ","dengan Dia"],["مُشْرِكُونَ","rakan kongsi bersekutu"]]],"2002":["(Dan apabila Kami letakkan suatu ayat di tempat ayat yang lain) artinya dengan memansukhnya kemudian menggantinya dengan ayat yang lain demi kemaslahatan semua hamba (padahal Allah lebih mengetahui apa yang diturunkan-Nya, mereka berkata) orang-orang kafir kepada Nabi saw. (\"Sesungguhnya kamu adalah orang yang mengada-ada saja.\") seorang pendusta yang pandai membuat-buat perkataan dari dirimu sendiri. (Bahkan kebanyakan mereka tiada mengetahui) hakikat Alquran dan faedah yang terkandung di dalam penasikhan ini.",[["وَإِذَا","Dan apabila"],["بَدَّلْنَآ","Kami menggantikan"],["ءَايَةًۭ","sebuah Ayat"],["مَّكَانَ","(di) tempat"],["ءَايَةٍۢ ۙ","(dari) sebuah Ayat"],["وَٱللَّهُ","dan Allah"],["أَعْلَمُ","(adalah) yang paling mengetahui"],["بِمَا","tentang apa"],["يُنَزِّلُ","Dia menghantar turun"],["قَالُوٓا۟","mereka berkata"],["إِنَّمَآ","Hanya"],["أَنتَ","kamu"],["مُفْتَرٍۭ ۚ","(adalah) seorang pencipta"],["بَلْ","Bahkan"],["أَكْثَرُهُمْ","kebanyakan mereka"],["لَا","jangan"],["يَعْلَمُونَ","mengetahui"]]],"2003":["(Katakanlah) kepada mereka! (\"Ruh Quduslah yang telah menurunkannya) yakni Alquran itu (dari sisi Rabbmu dengan benar) lafal bilhaqqi berta`alluq kepada lafal nazzalahu (untuk meneguhkan hati orang-orang yang beriman) dengan keimanan mereka kepada Alquran (dan menjadi petunjuk serta kabar gembira bagi orang-orang yang berserah diri.\")",[["قُلْ","Katakanlah"],["نَزَّلَهُۥ","Telah menurunkannya"],["رُوحُ","Roh Kudus"],["ٱلْقُدُسِ","Roh Kudus"],["مِن","daripada"],["رَّبِّكَ","Tuhanmu"],["بِٱلْحَقِّ","dalam kebenaran"],["لِيُثَبِّتَ","untuk membuat teguh"],["ٱلَّذِينَ","orang yang"],["ءَامَنُوا۟","beriman"],["وَهُدًۭى","dan (sebagai) petunjuk"],["وَبُشْرَىٰ","dan khabar gembira"],["لِلْمُسْلِمِينَ","kepada umat Islam"]]],"2004":["(Dan sesungguhnya) lafal qad di sini menunjukkan makna tahqiq (Kami mengetahui bahwa mereka berkata, \"Sesungguhnya ia itu diajarkan kepadanya) yakni Alquran itu (oleh seorang manusia.\") dimaksud adalah seorang pendeta Nasrani yang Nabi saw. pernah berkunjung kepadanya; lalu Allah swt. menyanggah melalui firman-Nya: (Padahal bahasa) atau logat (yang mereka tuduhkan) mereka sangkakan (kepada Muhammad) bahwa ia belajar daripadanya (adalah bahasa ajam sedangkan ini) yakni Alquran ini (adalah dalam bahasa Arab yang terang) memiliki kejelasan dan kefasihan, maka mengapa bahasa ini diajarkan oleh orang asing?",[["وَلَقَدْ","Dan sungguh"],["نَعْلَمُ","Kami tahu"],["أَنَّهُمْ","bahawa mereka"],["يَقُولُونَ","berkata"],["إِنَّمَا","Hanya"],["يُعَلِّمُهُۥ","mengajarnya"],["بَشَرٌۭ ۗ","seorang manusia"],["لِّسَانُ","(The) lidah"],["ٱلَّذِى","(dari) yang satu"],["يُلْحِدُونَ","mereka merujuk"],["إِلَيْهِ","kepadanya"],["أَعْجَمِىٌّۭ","(adalah) asing"],["وَهَـٰذَا","sedangkan ini"],["لِسَانٌ","(adalah) bahasa"],["عَرَبِىٌّۭ","bahasa arab"],["مُّبِينٌ","yang nyata"]]],"2005":["(Sesungguhnya orang-orang yang tidak beriman kepada ayat-ayat Allah, Allah tidak akan memberi petunjuk kepada mereka dan bagi mereka azab yang pedih) azab yang menyakitkan.",[["إِنَّ","Sesungguhnya"],["ٱلَّذِينَ","orang yang"],["لَا","jangan"],["يُؤْمِنُونَ","beriman"],["بِـَٔايَـٰتِ","dalam Ayat"],["ٱللَّهِ","(milik) Allah"],["لَا","tidak"],["يَهْدِيهِمُ","Allah akan memberi petunjuk kepada mereka"],["ٱللَّهُ","Allah akan memberi petunjuk kepada mereka"],["وَلَهُمْ","dan untuk mereka"],["عَذَابٌ","(ialah) azab"],["أَلِيمٌ","yang pedih"]]],"2006":["(Sesungguhnya yang mengada-adakan kebohongan, hanyalah orang-orang yang tidak beriman kepada ayat-ayat Allah) yakni Alquran; melalui tuduhan mereka yang mengatakan, bahwa Alquran adalah perkataan manusia (dan mereka itulah orang-orang pendusta) pengertian taukid di sini disimpulkan dari pengulangan dhamir. Ayat ini merupakan sanggahan terhadap perkataan mereka sebagaimana yang disitir oleh firman-Nya yang lain, yaitu, \"Sesungguhnya kamu adalah orang yang mengada-ada saja.\" (Q.S. An-Nahl 101).",[["إِنَّمَا","Hanya"],["يَفْتَرِى","mereka cipta"],["ٱلْكَذِبَ","kepalsuan itu"],["ٱلَّذِينَ","orang yang"],["لَا","jangan"],["يُؤْمِنُونَ","beriman"],["بِـَٔايَـٰتِ","dalam Ayat"],["ٱللَّهِ ۖ","(milik) Allah"],["وَأُو۟لَـٰٓئِكَ","dan mereka"],["هُمُ","mereka"],["ٱلْكَـٰذِبُونَ","(adalah) orang-orang yang berdusta"]]],"2007":["(Barang siapa yang kafir kepada Allah sesudah dia beriman, kecuali orang yang dipaksa) untuk mengucapkan kalimat kekafiran kemudian ia terpaksa mengucapkannya (padahal hatinya tetap tenang dalam beriman) lafal man dianggap sebagai mubtada, atau syarthiyah sedangkan khabar atau jawabnya ialah: maka bagi mereka ancaman yang keras. Pengertian ini ditunjukkan oleh firman selanjutnya, yaitu: (akan tetapi orang yang melapangkan dadanya untuk kekafiran) yakni hatinya menerima kekafiran dengan lapang (maka kemurkaan Allah menimpanya dan baginya azab yang besar).",[["مَن","Siapa pun"],["كَفَرَ","tidak beriman"],["بِٱللَّهِ","kepada Allah"],["مِنۢ","selepas"],["بَعْدِ","selepas"],["إِيمَـٰنِهِۦٓ","kepercayaannya"],["إِلَّا","kecuali"],["مَنْ","(satu) siapa"],["أُكْرِهَ","terpaksa"],["وَقَلْبُهُۥ","manakala hatinya"],["مُطْمَئِنٌّۢ","(adalah) kandungan"],["بِٱلْإِيمَـٰنِ","dengan iman"],["وَلَـٰكِن","Tetapi"],["مَّن","(satu) siapa"],["شَرَحَ","dibuka"],["بِٱلْكُفْرِ","kepada ketidakpercayaan"],["صَدْرًۭا","(nya) payudara"],["فَعَلَيْهِمْ","kemudian atas mereka"],["غَضَبٌۭ","(adalah) kemurkaan"],["مِّنَ","daripada"],["ٱللَّهِ","Allah"],["وَلَهُمْ","dan untuk mereka"],["عَذَابٌ","(ialah) azab"],["عَظِيمٌۭ","yang besar"]]],"2008":["(Yang demikian itu) ancaman yang ditujukan kepada mereka itu (disebabkan karena sesungguhnya mereka mencintai kehidupan di dunia) mereka memilihnya (lebih dari akhirat dan bahwasanya Allah tiada memberi petunjuk kepada kaum yang kafir.)",[["ذَٰلِكَ","Itu (ialah)"],["بِأَنَّهُمُ","kerana"],["ٱسْتَحَبُّوا۟","mereka lebih suka"],["ٱلْحَيَوٰةَ","kehidupan"],["ٱلدُّنْيَا","dunia"],["عَلَى","atas"],["ٱلْـَٔاخِرَةِ","akhirat"],["وَأَنَّ","dan bahawa"],["ٱللَّهَ","Allah"],["لَا","tidak"],["يَهْدِى","panduan"],["ٱلْقَوْمَ","manusia"],["ٱلْكَـٰفِرِينَ","orang kafir"]]],"2009":["(Mereka itulah orang-orang yang hatinya, pendengarannya dan penglihatannya telah dikunci mati oleh Allah dan mereka itulah orang-orang yang lalai) dari apa yang dikehendaki terhadap diri mereka.",[["أُو۟لَـٰٓئِكَ","Mereka itu"],["ٱلَّذِينَ","(adalah) mereka"],["طَبَعَ","Allah telah menetapkan meterai"],["ٱللَّهُ","Allah telah menetapkan meterai"],["عَلَىٰ","atas"],["قُلُوبِهِمْ","hati mereka"],["وَسَمْعِهِمْ","dan pendengaran mereka"],["وَأَبْصَـٰرِهِمْ ۖ","dan penglihatan mereka"],["وَأُو۟لَـٰٓئِكَ","Dan mereka"],["هُمُ","mereka adalah"],["ٱلْغَـٰفِلُونَ","yang lalai"]]],"2010":["(Tidak diragukan lagi) pastilah (bahwa mereka di akhirat nanti adalah orang-orang yang merugi) karena tempat kembali mereka adalah neraka dan mereka kekal di dalamnya.",[["لَا","Tidak"],["جَرَمَ","keraguan"],["أَنَّهُمْ","bahawa mereka"],["فِى","dalam"],["ٱلْـَٔاخِرَةِ","akhirat"],["هُمُ","[mereka]"],["ٱلْخَـٰسِرُونَ","(adalah) orang-orang yang rugi"]]],"2011":["(Dan sesungguhnya Rabbmu terhadap orang-orang yang berhijrah) ke Madinah (sesudah menderita cobaan) sesudah mereka disiksa dan dipaksa mengucapkan kalimat kekafiran. Menurut qiraat lafal futinuu dibaca fatanuu; artinya sesudah mereka kafir, atau sesudah mereka memfitnah manusia supaya jangan beriman (kemudian mereka berjihad dan sabar) di dalam melakukan ketaatan (sesungguhnya Rabbmu sesudah itu) sesudah cobaan itu (benar-benar Maha Pengampun) kepada mereka (lagi Maha Penyayang) terhadap mereka. Khabarnya inna yang pertama sama dengan khabar inna yang kedua.",[["ثُمَّ","Kemudian"],["إِنَّ","sesungguhnya"],["رَبَّكَ","Tuhanmu"],["لِلَّذِينَ","kepada mereka yang"],["هَاجَرُوا۟","berhijrah"],["مِنۢ","selepas"],["بَعْدِ","selepas"],["مَا","apa"],["فُتِنُوا۟","mereka telah diadili"],["ثُمَّ","kemudian"],["جَـٰهَدُوا۟","berusaha keras"],["وَصَبَرُوٓا۟","dan bersabar"],["إِنَّ","Sesungguhnya"],["رَبَّكَ","Tuhanmu"],["مِنۢ","selepas itu"],["بَعْدِهَا","selepas itu"],["لَغَفُورٌۭ","sesungguhnya adalah Maha Pengampun"],["رَّحِيمٌۭ","Maha Mengasihani"]]],"2012":["Ingatlah (suatu hari ketika tiap-tiap diri datang untuk membela) berhujah untuk membela (dirinya sendiri) ia tidak menghiraukan selain daripada dirinya sendiri, yaitu hari kiamat (dan bagi tiap-tiap diri disempurnakan) balasan (apa yang telah dikerjakannya, sedangkan mereka tidak dianiaya) sedikit pun juga.",[["۞ يَوْمَ","(Pada) hari itu"],["تَأْتِى","(apabila) akan datang"],["كُلُّ","setiap"],["نَفْسٍۢ","jiwa"],["تُجَـٰدِلُ","merayu"],["عَن","bagi"],["نَّفْسِهَا","sendiri"],["وَتُوَفَّىٰ","dan akan dibayar penuh"],["كُلُّ","setiap"],["نَفْسٍۢ","jiwa"],["مَّا","apa"],["عَمِلَتْ","ia berlaku"],["وَهُمْ","dan mereka"],["لَا","(akan) tidak"],["يُظْلَمُونَ","dizalimi"]]],"2013":["(Dan Allah telah membuat suatu perumpamaan) kata perumpamaan ini dijelaskan oleh badalnya, yaitu (dengan sebuah negeri) yaitu Mekah, yang dimaksud adalah penduduknya (dahulunya aman) dari serbuan musuh dan tidak pernah ada kerusuhan (lagi tenteram) tidak perlu pindah karena alasan sempit atau takut (rezekinya datang kepadanya melimpah-ruah) dengan luas (dari segenap tempat, tetapi penduduknya mengingkari nikmat-nikmat Allah) disebabkan mereka mendustakan Nabi saw. (karena itu Allah merasakan kepada mereka pakaian kelaparan) sehingga mereka mengalami paceklik selama tujuh tahun (dan ketakutan) terhadap pasukan-pasukan tentara Nabi saw. (disebabkan apa yang selalu mereka perbuat).",[["وَضَرَبَ","Dan Allah menetapkan"],["ٱللَّهُ","Dan Allah menetapkan"],["مَثَلًۭا","suatu persamaan"],["قَرْيَةًۭ","(dari) sebuah bandar"],["كَانَتْ","(itu) adalah"],["ءَامِنَةًۭ","selamat"],["مُّطْمَئِنَّةًۭ","dan kandungan"],["يَأْتِيهَا","datang kepadanya"],["رِزْقُهَا","peruntukannya"],["رَغَدًۭا","(dalam) kelimpahan"],["مِّن","daripada"],["كُلِّ","setiap"],["مَكَانٍۢ","tempat"],["فَكَفَرَتْ","tetapi ia menafikan"],["بِأَنْعُمِ","(nikmat) Allah"],["ٱللَّهِ","(nikmat) Allah"],["فَأَذَٰقَهَا","maka Allah menjadikannya rasa"],["ٱللَّهُ","maka Allah menjadikannya rasa"],["لِبَاسَ","(the) pakaian"],["ٱلْجُوعِ","(dari) kelaparan"],["وَٱلْخَوْفِ","dan ketakutan itu"],["بِمَا","bagi apa"],["كَانُوا۟","mereka pernah (untuk)"],["يَصْنَعُونَ","lakukan"]]],"2014":["(Dan sesungguhnya telah datang kepada mereka seorang rasul dari mereka sendiri) yaitu Nabi Muhammad saw. (tetapi mereka mendustakannya karena itu mereka ditimpa azab) yaitu berupa kelaparan dan dicekam rasa takut (sedangkan mereka adalah orang-orang yang zalim).",[["وَلَقَدْ","Dan sungguh"],["جَآءَهُمْ","datang kepada mereka"],["رَسُولٌۭ","seorang Rasul"],["مِّنْهُمْ","daripada kalangan mereka"],["فَكَذَّبُوهُ","tetapi mereka menafikannya"],["فَأَخَذَهُمُ","jadi merampas mereka"],["ٱلْعَذَابُ","azab"],["وَهُمْ","sedangkan mereka"],["ظَـٰلِمُونَ","(adalah) orang-orang yang zalim"]]],"2015":["(Maka makanlah) hai orang-orang yang beriman (yang halal lagi baik dari rezeki yang telah diberikan Allah kepada kalian dan syukurilah nikmat Allah jika kalian hanya kepada-Nya saja menyembah).",[["فَكُلُوا۟","Jadi makan"],["مِمَّا","tentang apa"],["رَزَقَكُمُ","Allah telah menyediakan kamu"],["ٱللَّهُ","Allah telah menyediakan kamu"],["حَلَـٰلًۭا","halal"],["طَيِّبًۭا","dan baik"],["وَٱشْكُرُوا۟","Dan bersyukurlah"],["نِعْمَتَ","(untuk) Nikmat"],["ٱللَّهِ","(milik) Allah"],["إِن","jika"],["كُنتُمْ","[kamu]"],["إِيَّاهُ","Dia sahaja"],["تَعْبُدُونَ","kamu menyembah"]]],"2016":["(Sesungguhnya Allah hanya mengharamkan atas kalian bangkai, darah, daging babi dan apa yang disembelih dengan menyebut nama selain Allah; tetapi barang siapa yang terpaksa memakannya dengan tidak menganiaya dan tidak pula melampaui batas, maka sesungguhnya Allah Maha Pengampun lagi Maha Penyayang.)",[["إِنَّمَا","Hanya"],["حَرَّمَ","Dia telah melarang"],["عَلَيْكُمُ","kepada kamu"],["ٱلْمَيْتَةَ","haiwan yang mati itu"],["وَٱلدَّمَ","dan darah"],["وَلَحْمَ","dan daging"],["ٱلْخِنزِيرِ","(dari) babi"],["وَمَآ","dan apa"],["أُهِلَّ","telah didedikasikan"],["لِغَيْرِ","kepada yang lain (selain)"],["ٱللَّهِ","Allah"],["بِهِۦ ۖ","[dengannya]"],["فَمَنِ","Tetapi (jika) satu"],["ٱضْطُرَّ","(adalah) dipaksa"],["غَيْرَ","tanpa (menjadi)"],["بَاغٍۢ","ingkar"],["وَلَا","dan bukan"],["عَادٍۢ","seorang penceroboh"],["فَإِنَّ","maka sesungguhnya"],["ٱللَّهَ","Allah"],["غَفُورٌۭ","Maha Pengampun"],["رَّحِيمٌۭ","Maha Mengasihani"]]],"2017":["(Dan janganlah kalian mengatakan terhadap apa yang disebut-sebut oleh lidah kalian) yang sering digambarkan oleh lisan kalian (secara dusta, \"Ini halal dan ini haram.\") terhadap apa yang tidak dihalalkan oleh Allah dan apa yang tidak diharamkan oleh-Nya (untuk mengada-adakan kebohongan terhadap Allah) dengan menisbatkan hal itu kepada-Nya. (Sesungguhnya orang-orang yang mengada-adakan kebohongan terhadap Allah tiadalah beruntung).",[["وَلَا","Dan jangan"],["تَقُولُوا۟","berkata"],["لِمَا","untuk itu yang"],["تَصِفُ","tegaskan"],["أَلْسِنَتُكُمُ","lidah kamu"],["ٱلْكَذِبَ","pembohongan itu"],["هَـٰذَا","Ini"],["حَلَـٰلٌۭ","(adalah) halal"],["وَهَـٰذَا","dan ini"],["حَرَامٌۭ","(adalah) dilarang"],["لِّتَفْتَرُوا۟","supaya kamu mencipta"],["عَلَى","tentang"],["ٱللَّهِ","Allah"],["ٱلْكَذِبَ ۚ","pembohongan itu"],["إِنَّ","Sesungguhnya"],["ٱلَّذِينَ","orang yang"],["يَفْتَرُونَ","mencipta"],["عَلَى","tentang"],["ٱللَّهِ","Allah"],["ٱلْكَذِبَ","pembohongan itu"],["لَا","mereka tidak akan berjaya"],["يُفْلِحُونَ","mereka tidak akan berjaya"]]],"2018":["Bagi mereka yang mengada-adakan kedustaan atas nama Allah (kesenangan yang sedikit) di dunia (dan bagi mereka) kelak di akhirat (azab yang pedih) azab yang menyakitkan.",[["مَتَـٰعٌۭ","Satu kenikmatan"],["قَلِيلٌۭ","sedikit"],["وَلَهُمْ","dan untuk mereka"],["عَذَابٌ","(ialah) azab"],["أَلِيمٌۭ","yang pedih"]]],"2019":["(Dan terhadap orang-orang Yahudi) dimaksud para pemeluk agama Yahudi (Kami haramkan apa yang telah Kami ceritakan dahulu kepadamu) di dalam firman-Nya yang lain, yaitu, \"Dan kepada orang-orang Yahudi, Kami haramkan segala binatang yang berkuku...\" (Q.S. Al-An'am 146) (dan Kami tiada menganiaya mereka) dengan mengharamkan hal tersebut kepada mereka (akan tetapi merekalah yang menganiaya diri mereka sendiri) dengan melakukan perbuatan-perbuatan maksiat yang menyebabkan diharamkannya hal-hal tersebut.",[["وَعَلَى","Dan kepada"],["ٱلَّذِينَ","orang yang"],["هَادُوا۟","adalah Yahudi"],["حَرَّمْنَا","Kami telah melarang"],["مَا","apa"],["قَصَصْنَا","Kami berkaitan"],["عَلَيْكَ","kepada kamu"],["مِن","sebelum"],["قَبْلُ ۖ","sebelum"],["وَمَا","Dan tidak"],["ظَلَمْنَـٰهُمْ","Kami menganiaya mereka"],["وَلَـٰكِن","tetapi"],["كَانُوٓا۟","mereka pernah (untuk)"],["أَنفُسَهُمْ","diri mereka"],["يَظْلِمُونَ","salah"]]],"2020":["(Kemudian sesungguhnya Rabbmu terhadap orang-orang yang mengerjakan keburukan) kemusyrikan (karena kebodohannya kemudian mereka bertobat) kembali kepada Allah (sesudah itu dan memperbaiki dirinya) memperbaiki amal perbuatannya (sesungguhnya Rabbmu sesudah itu) sesudah kebodohannya dan sesudah bertobat (benar-benar Maha Pengampun) kepada mereka (lagi Maha Penyayang) kepada mereka.",[["ثُمَّ","Kemudian"],["إِنَّ","sesungguhnya"],["رَبَّكَ","Tuhanmu"],["لِلَّذِينَ","kepada mereka yang"],["عَمِلُوا۟","lakukan"],["ٱلسُّوٓءَ","jahat"],["بِجَهَـٰلَةٍۢ","dalam kejahilan"],["ثُمَّ","kemudian"],["تَابُوا۟","bertaubat"],["مِنۢ","selepas"],["بَعْدِ","selepas"],["ذَٰلِكَ","bahawa"],["وَأَصْلَحُوٓا۟","dan membetulkan diri mereka"],["إِنَّ","sesungguhnya"],["رَبَّكَ","Tuhanmu"],["مِنۢ","selepas itu"],["بَعْدِهَا","selepas itu"],["لَغَفُورٌۭ","(adalah) sesungguhnya Maha Pengampun"],["رَّحِيمٌ","Maha Mengasihani"]]],"2021":["(Sesungguhnya Ibrahim adalah seorang imam) seorang penghulu yang menjadi panutan dan di dalam dirinya terkandung semua akhlak yang baik (lagi patuh) sangat taat (kepada Allah dan hanif) cenderung kepada agama yang lurus. (Dan sekali-kali dia bukanlah termasuk orang-orang yang mempersekutukan Tuhan.)",[["إِنَّ","Sesungguhnya"],["إِبْرَٰهِيمَ","Ibrahim"],["كَانَ","adalah"],["أُمَّةًۭ","sebuah bangsa"],["قَانِتًۭا","patuh"],["لِّلَّهِ","kepada Allah"],["حَنِيفًۭا","tegak"],["وَلَمْ","dan bukan"],["يَكُ","dia adalah"],["مِنَ","daripada"],["ٱلْمُشْرِكِينَ","orang musyrik"]]],"2022":["(Lagi yang mensyukuri nikmat-nikmat Allah, Allah telah memilihnya) menjadikannya sebagai pilihan-Nya (dan menunjukkannya kepada jalan yang lurus.)",[["شَاكِرًۭا","Bersyukur"],["لِّأَنْعُمِهِ ۚ","atas nikmatNya"],["ٱجْتَبَىٰهُ","Dia memilih dia"],["وَهَدَىٰهُ","dan membimbingnya"],["إِلَىٰ","kepada"],["صِرَٰطٍۢ","caranya"],["مُّسْتَقِيمٍۢ","lurus"]]],"2023":["(Dan Kami berikan kepadanya) di dalam ungkapan ini terkandung pengertian iltifat dari gaibah, atau perpindahan ungkapan dari dhamir gaib kepada dhamir mutakallim (kebaikan di dunia) yaitu mendapatkan pujian dari kalangan semua agama. (Dan sesungguhnya dia di akhirat benar-benar termasuk orang-orang yang saleh) yaitu orang-orang yang memiliki derajat yang tinggi di akhirat.",[["وَءَاتَيْنَـٰهُ","Dan Kami berikan kepadanya"],["فِى","dalam"],["ٱلدُّنْيَا","dunia"],["حَسَنَةًۭ ۖ","kebaikan"],["وَإِنَّهُۥ","dan sesungguhnya, dia"],["فِى","dalam"],["ٱلْـَٔاخِرَةِ","akhirat"],["لَمِنَ","(dia) pasti (berada) di antara"],["ٱلصَّـٰلِحِينَ","orang yang soleh"]]],"2024":["(Kemudian Kami wahyukan kepadamu) hai Muhammad (ikutilah millah) yakni agama (Ibrahim seorang yang hanif. Dan bukanlah dia termasuk orang-orang yang mempersekutukan Tuhan) Allah swt. mengulangi ayat ini untuk menyanggah anggapan orang-orang Yahudi dan orang-orang Nasrani yang mengakui bahwa Nabi Ibrahim adalah pemeluk agama mereka.",[["ثُمَّ","Kemudian"],["أَوْحَيْنَآ","Kami mendedahkan"],["إِلَيْكَ","kepada kamu"],["أَنِ","bahawa"],["ٱتَّبِعْ","kamu ikut"],["مِلَّةَ","(agama)."],["إِبْرَٰهِيمَ","(dari) Ibrahim"],["حَنِيفًۭا ۖ","tegak"],["وَمَا","dan bukan"],["كَانَ","dia adalah"],["مِنَ","daripada"],["ٱلْمُشْرِكِينَ","orang musyrik"]]],"2025":["(Sesungguhnya telah dijadikan hari Sabtu) diwajibkan menghormatinya (atas orang-orang Yahudi yang berselisih mengenainya) dengan nabi mereka; mereka adalah orang-orang Yahudi yang diperintahkan oleh Allah supaya mereka menyibukkan dirinya untuk beribadah di hari Jumat, akan tetapi mereka mengatakan, \"Kami tidak menghendakinya,\" lalu mereka memilih hari Sabtu sebagai hari untuk ibadah. Akhirnya Allah memperketat peraturan kepada mereka di hari Sabtu. (Dan sesungguhnya Rabbmu benar-benar akan memberi putusan di antara mereka di hari kiamat terhadap apa yang telah mereka perselisihkan itu) yaitu Dia kelak akan memberi pahala kepada orang yang taat, dan Dia akan mengazab orang-orang yang durhaka melanggar hal-hal yang diharamkan-Nya.",[["إِنَّمَا","Hanya"],["جُعِلَ","telah dilantik"],["ٱلسَّبْتُ","hari Sabat"],["عَلَى","bagi"],["ٱلَّذِينَ","orang yang"],["ٱخْتَلَفُوا۟","berbeza"],["فِيهِ ۚ","di dalamnya"],["وَإِنَّ","Dan sesungguhnya"],["رَبَّكَ","Tuhanmu"],["لَيَحْكُمُ","pasti akan menilai"],["بَيْنَهُمْ","antara mereka"],["يَوْمَ","(pada) hari itu"],["ٱلْقِيَـٰمَةِ","Kiamat"],["فِيمَا","pada apa"],["كَانُوا۟","mereka pernah (untuk)"],["فِيهِ","[di dalamnya]"],["يَخْتَلِفُونَ","berbeza"]]],"2026":["(Serulah) manusia, hai Muhammad (kepada jalan Rabbmu) yakni agama-Nya (dengan hikmah) dengan Alquran (dan pelajaran yang baik) pelajaran yang baik atau nasihat yang lembut (dan bantahlah mereka dengan cara) bantahan (yang baik) seperti menyeru mereka untuk menyembah Allah dengan menampilkan kepada mereka tanda-tanda kebesaran-Nya atau dengan hujah-hujah yang jelas. (Sesungguhnya Rabbmu Dialah Yang lebih mengetahui) Maha Mengetahui (tentang siapa yang tersesat dari jalan-Nya dan Dialah yang lebih mengetahui orang-orang yang mendapat petunjuk) maka Dia membalas mereka; ayat ini diturunkan sebelum diperintahkan untuk memerangi orang-orang kafir. Dan diturunkan ketika Hamzah gugur dalam keadaan tercincang; ketika Nabi saw. melihat keadaan jenazahnya, lalu beliau saw. bersumpah melalui sabdanya, \"Sungguh aku bersumpah akan membalas tujuh puluh orang dari mereka sebagai penggantimu.\"",[["ٱدْعُ","Panggil"],["إِلَىٰ","kepada"],["سَبِيلِ","jalan"],["رَبِّكَ","Tuhanmu"],["بِٱلْحِكْمَةِ","dengan hikmahnya"],["وَٱلْمَوْعِظَةِ","dan arahan"],["ٱلْحَسَنَةِ ۖ","yang baik"],["وَجَـٰدِلْهُم","dan berbincang dengan mereka"],["بِٱلَّتِى","dalam itu"],["هِىَ","yang"],["أَحْسَنُ ۚ","(adalah) terbaik"],["إِنَّ","Sesungguhnya"],["رَبَّكَ","Tuhanmu"],["هُوَ","Dia"],["أَعْلَمُ","(adalah) yang paling mengetahui"],["بِمَن","daripada siapa"],["ضَلَّ","telah sesat"],["عَن","daripada"],["سَبِيلِهِۦ ۖ","cara dia"],["وَهُوَ","Dan Dia"],["أَعْلَمُ","(adalah) yang paling mengetahui"],["بِٱلْمُهْتَدِينَ","daripada orang-orang yang mendapat petunjuk"]]],"2027":["(Dan jika kalian memberikan balasan, maka balaslah dengan balasan yang sama dengan siksaan yang ditimpakan kepada kalian. Akan tetapi jika kalian bersabar) tidak mau membalas (sesungguhnya itulah) bersikap sabar itulah (yang lebih baik bagi orang-orang yang sabar) kemudian Nabi saw. membatalkan sumpahnya itu, dan membayar kafaratnya. Demikianlah menurut hadis yang telah diriwayatkan oleh Imam Bazzar.",[["وَإِنْ","Dan jika"],["عَاقَبْتُمْ","kamu balas balik"],["فَعَاقِبُوا۟","kemudian membalas dendam"],["بِمِثْلِ","dengan seumpamanya"],["مَا","tentang apa"],["عُوقِبْتُم","kamu ditimpa musibah"],["بِهِۦ ۖ","dengan [ia]"],["وَلَئِن","Tetapi jika"],["صَبَرْتُمْ","kamu sabar"],["لَهُوَ","sesungguhnya (ia) itu"],["خَيْرٌۭ","lebih baik"],["لِّلصَّـٰبِرِينَ","bagi mereka yang sabar"]]],"2028":["(Bersabarlah dan tiadalah kesabaranmu itu melainkan dengan pertolongan Allah) berkat taufiq-Nya (dan janganlah kamu bersedih hati terhadap kekafiran mereka) terhadap kekafiran orang-orang kafir, jika mereka tidak juga mau beriman, karena kamu menginginkan dengan sangat akan keimanan mereka (dan janganlah kamu bersempit dada terhadap apa yang mereka tipu-dayakan) artinya janganlah engkau hiraukan tipu muslihat mereka, karena sesungguhnya Akulah yang akan menolongmu dalam menghadapi mereka.",[["وَٱصْبِرْ","Dan bersabarlah"],["وَمَا","dan bukan"],["صَبْرُكَ","(adalah) kesabaran kamu"],["إِلَّا","tetapi"],["بِٱللَّهِ ۚ","daripada Allah"],["وَلَا","Dan jangan"],["تَحْزَنْ","bersedih"],["عَلَيْهِمْ","atas mereka"],["وَلَا","dan jangan"],["تَكُ","jadilah"],["فِى","dalam"],["ضَيْقٍۢ","kesusahan"],["مِّمَّا","bagi apa"],["يَمْكُرُونَ","mereka merancang"]]],"2029":["(Sesungguhnya Allah beserta orang-orang yang bertakwa) orang-orang yang takut terhadap kekafiran dan kemaksiatan (dan orang-orang yang berbuat kebaikan) dengan menjalankan ketaatan, kesabaran; Allah akan menolong mereka dengan bantuan dan pertolongan-Nya.",[["إِنَّ","Sesungguhnya"],["ٱللَّهَ","Allah"],["مَعَ","(adalah) dengan"],["ٱلَّذِينَ","orang yang"],["ٱتَّقَوا۟","takut (Dia)"],["وَّٱلَّذِينَ","dan orang yang"],["هُم","[mereka]"],["مُّحْسِنُونَ","(adalah) orang yang berbuat baik"]]]});